// WF3 "Select and build": pick leads that need a message and build one OpenRouter request per lead.
// Offer-agnostic: the offer, the lead facts and the collected insights are the only inputs.
// Tact (spec 6.3b step 5): the model NEVER receives complaints or weaknesses as something to mention. Insights only choose the angle.
// Round 2: when the seller's product writes messages, the first message IS the product demo, so it must not read like a template:
// no rating, no micro-district, no jargon, no time-of-day greeting, one personal detail at most (from the lead's specialty or what its
// customers praise), only benefits the offer really delivers (the model must quote them from the offer), a concrete call to action, a signature.
// Lead insights core (spec 6.2, 6.3a, 6.3b). Plain ESM JS with no imports so the SAME source is inlined into n8n Code
// nodes (marker /*__INSIGHTS__*/) and used by unit tests and the fixture runner. Nothing here knows any industry,
// segment or offer: relevance always comes from the campaign (allowed categories, signal weights, opportunity map).

// ───────────────────────── text helpers ─────────────────────────
const INVISIBLE = new RegExp('[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]', 'g');
const DIACRITICS = new RegExp('[\u064B-\u065F\u0670\u0640]', 'g');

/** Lowercase, strip invisible/bidi marks and Arabic diacritics, unify alef/yaa/taa-marbuta, collapse spaces. */
function norm(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(INVISIBLE, '')
    .replace(DIACRITICS, '')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Invisible/bidi marks removed, whitespace collapsed. */
function stripInvisible(s) {
  return String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
}

/** Clean one location part for Apify: no invisible marks, no repeated words ("التجمع الخامس القاهرة القاهرة"). */
function cleanPlace(s) {
  const t = String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
  const out = [];
  for (const w of t.split(' ')) if (!out.length || norm(out[out.length - 1]) !== norm(w)) out.push(w);
  return out.join(' ');
}

// ───────────────────────── global exclusions (spec 6.3a) ─────────────────────────
// Always on, for every campaign. Matched against Google Maps CATEGORIES (Arabic and English), never against the name alone.
// Hospitals only for health: clinics, labs and pharmacies are legitimate prospects for many offers.
const GLOBAL_EXCLUSIONS = {
  government: ['مكتب حكومي', 'جهه حكوميه', 'هيئه حكوميه', 'مبني حكومي', 'وزاره', 'محافظه', 'مجلس مدينه', 'قسم شرطه', 'مركز شرطه', 'محكمه', 'نيابه', 'مصلحه', 'سجل مدني', 'government office', 'government organization', 'government agency', 'local government', 'city government', 'county government', 'municipality', 'ministry', 'police', 'courthouse', 'public administration'],
  utility: ['محطه كهرباء', 'محطه توليد', 'محطه مياه', 'محطه معالجه', 'محطه تحويل', 'محطه صرف', 'شركه كهرباء', 'شركه مياه', 'شركه غاز', 'سنترال', 'مرفق عام', 'power station', 'power plant', 'electric utility', 'electricity', 'water utility', 'water treatment', 'water works', 'sewage', 'telephone exchange', 'substation', 'gas utility', 'public utility'],
  education: ['جامعه', 'كليه', 'مدرسه', 'روضه اطفال', 'ثانويه', 'اعداديه', 'ابتدائيه', 'university', 'college', 'school', 'kindergarten', 'academy of', 'faculty'],
  health: ['مستشفي', 'hospital'],
  worship: ['مسجد', 'جامع', 'كنيسه', 'دير', 'معبد', 'مكان عباده', 'mosque', 'church', 'temple', 'synagogue', 'place of worship', 'cathedral', 'monastery'],
  embassy: ['سفاره', 'قنصليه', 'embassy', 'consulate'],
  military: ['موقع عسكري', 'قاعده عسكريه', 'معسكر', 'عسكري', 'military', 'army base', 'air force', 'naval'],
};

const hasEn = (p) => /^[a-z ]+$/.test(p);
const catMatches = (c, p) => (hasEn(p) ? new RegExp(`(^| )${p}( |$|s\\b)`).test(c) : c.includes(p));

/** @returns {{group:string, match:string, category:string}|null} */
function globalExclusion(categories) {
  for (const raw of categories || []) {
    const c = norm(raw);
    if (!c) continue;
    for (const [group, pats] of Object.entries(GLOBAL_EXCLUSIONS)) {
      for (const p of pats) if (catMatches(c, norm(p))) return { group, match: p, category: String(raw) };
    }
  }
  return null;
}

/** Brand part of a business name ("X - Nasr City" and "X (Maadi)" are the same brand), normalized. */
function brandKey(name) {
  return norm(String(name || '').split(/\s[-–|]\s|\(|\|/)[0]).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

/**
 * Branches of one business: listings of the organization with the same normalized brand name AND the same website or the same phone
 * (a Facebook/Instagram page is not a shared website). Name similarity alone never counts: it is what made unrelated places look like chains.
 * @param {{business_name?:string, website?:string, phone_e164?:string}} self
 * @param {{business_name?:string, website?:string, phone_e164?:string}[]} all every listing of the organization (the business itself included)
 */
function countBranches(self, all) {
  const key = brandKey(self.business_name);
  if (!key) return 1;
  const site = (u) => (u && !isSocialUrl(u) ? hostOf(String(u)) : '');
  const mySite = site(self.website);
  const myPhone = self.phone_e164 || '';
  let n = 0;
  for (const o of all || []) {
    if (brandKey(o.business_name) !== key) continue;
    if ((mySite && site(o.website) === mySite) || (myPhone && o.phone_e164 === myPhone)) n++;
  }
  return Math.max(1, n);
}

/** Light stemmer so "وكالات" matches "وكالة" and "Agencies" matches "agency" (no dictionary, no segment knowledge). */
function stemToken(raw) {
  let t = norm(raw);
  if (/^[a-z0-9]+$/.test(t)) {
    if (t.length > 4 && t.endsWith('ies')) return t.slice(0, -3) + 'y';
    if (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) return t.slice(0, -1);
    return t;
  }
  if (t.length > 4) t = t.replace(/^(وال|بال|لل|ال)/, '');
  if (t.length > 3) t = t.replace(/(ات|ون|ين|ان)$/, '');
  if (t.length > 3) t = t.replace(/ه$/, '');
  if (t.length > 3) t = t.replace(/ي$/, '');
  return t;
}
const catTokens = (s) => norm(s).split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(stemToken);

/**
 * Does any Maps category match the campaign's allowed categories (Arabic and English)? Done by us, never by the actor.
 * Singular/plural and the Arabic article are ignored. An allowed entry matches a place category when all its words occur in the
 * category, or the category is a (parent) subset of the entry. An empty allow-list means "no category restriction" (old campaigns).
 * @returns {{ok:boolean, matched:string|null}}
 */
function categoryMatch(placeCategories, allowed) {
  const list = (allowed || []).map((a) => ({ a, tokens: catTokens(a) })).filter((x) => x.tokens.length && norm(x.a).length >= 3);
  if (!list.length) return { ok: true, matched: null };
  for (const raw of placeCategories || []) {
    const c = catTokens(raw);
    if (!c.length) continue;
    const cs = new Set(c);
    for (const { a, tokens } of list) {
      const as = new Set(tokens);
      if (tokens.every((t) => cs.has(t))) return { ok: true, matched: a };
      if (c.every((t) => as.has(t)) && (c.length >= 2 || c[0].length >= 4)) return { ok: true, matched: a };
    }
  }
  return { ok: false, matched: null };
}

// ───────────────────────── deterministic facts (spec 6.3b step 1) ─────────────────────────
const DAY = 86400000;
const MONTH = 30.44 * DAY;
const r1 = (x) => Math.round(x * 10) / 10;

/**
 * @param {any} place raw Google Maps place (compass/crawler-google-places)
 * @param {any[]} reviews raw reviews for that place (compass/google-maps-reviews-scraper), newest first or any order
 * @param {{now?:number, branches?:number}} [opt]
 */
function computeFacts(place, reviews = [], opt = {}) {
  const now = opt.now ?? Date.now();
  const seen = new Set();
  const rev = [];
  for (const r of reviews || []) {
    if (!r) continue;
    const id = r.reviewId || `${r.publishedAtDate}|${r.stars}|${r.text}`;
    if (seen.has(id)) continue;
    seen.add(id);
    rev.push(r);
  }
  const dates = rev.map((r) => Date.parse(r.publishedAtDate)).filter(Number.isFinite).sort((a, b) => a - b);
  const n = rev.length;
  const total = Number(place.reviewsCount) || n;
  const overall = Number(place.totalScore) || null;
  const last = dates.length ? dates[dates.length - 1] : null;
  const oldest = dates.length ? dates[0] : null;
  const sinceLast = last == null ? null : (now - last) / DAY;
  const activity_label = last == null ? 'unknown' : sinceLast <= 90 ? 'active' : sinceLast <= 365 ? 'slowing' : 'dormant';
  const spanMonths = oldest == null ? null : Math.max(0.25, (now - oldest) / MONTH);
  const replies = rev.filter((r) => r.responseFromOwnerText && String(r.responseFromOwnerText).trim()).length;
  const low = rev.filter((r) => Number(r.stars) <= 2);
  const stars = rev.map((r) => Number(r.stars)).filter(Number.isFinite);
  const recent_avg = stars.length ? stars.reduce((a, b) => a + b, 0) / stars.length : null;
  const texts = rev.filter((r) => (r.text || r.textTranslated || '').toString().trim());
  const images = Number(place.imagesCount) || 0;
  return {
    n_reviews_fetched: n,
    n_texts: texts.length,
    total_reviews: total,
    overall_rating: overall,
    last_review_at: last == null ? null : new Date(last).toISOString(),
    days_since_last_review: sinceLast == null ? null : Math.round(sinceLast),
    reviews_per_month: spanMonths == null || n < 2 ? null : r1(n / spanMonths),
    activity_label,
    // Only claim "new" when the fetched window provably covers the whole history and it started within a year.
    is_new_business: oldest != null && now - oldest <= 365 * DAY && total <= n ? true : null,
    owner_reply_rate: n ? Math.round((replies / n) * 100) / 100 : null,
    low_reviews: low.length,
    unanswered_low_reviews: low.filter((r) => !(r.responseFromOwnerText && String(r.responseFromOwnerText).trim())).length,
    recent_avg_rating: recent_avg == null ? null : r1(recent_avg),
    rating_delta: recent_avg == null || overall == null ? null : r1(recent_avg - overall),
    unclaimed_listing: place.claimThisBusiness === true,
    images_count: images,
    has_hours: Array.isArray(place.openingHours) && place.openingHours.length > 0,
    has_description: !!(place.description || place.ownerDescription || place.subTitle),
    // A Facebook/Instagram/link page used as the "website" is not a real website.
    has_website: !!(place.website && String(place.website).trim()) && !isSocialUrl(place.website),
    website_social: !!(place.website && isSocialUrl(place.website)),
    search_rank: Number.isFinite(Number(place.rank)) && Number(place.rank) > 0 ? Number(place.rank) : null,
    categories: [...new Set([place.categoryName, ...(Array.isArray(place.categories) ? place.categories : [])].filter(Boolean))].slice(0, 8),
    low_star_share: (() => { const d = place.reviewsDistribution; if (!d) return null; const t = ['oneStar', 'twoStar', 'threeStar', 'fourStar', 'fiveStar'].reduce((x, k) => x + (Number(d[k]) || 0), 0); return t ? Math.round((((Number(d.oneStar) || 0) + (Number(d.twoStar) || 0)) / t) * 100) / 100 : null; })(),
    permanently_closed: !!place.permanentlyClosed,
    temporarily_closed: !!place.temporarilyClosed,
    branches: opt.branches ?? 1,
  };
}

const clamp01 = (v) => Math.max(0, Math.min(1, v));
const round3 = (v) => Math.round(clamp01(v) * 1000) / 1000;

/** Normalized signal values (0..1, 1 = the signal's HIGH state) from facts. Unknown stays absent (never guessed). */
function signalValues(f) {
  const out = {};
  out.has_website = f.has_website ? 1 : 0;
  const rc = Math.min(1, Math.log10(1 + (f.total_reviews || 0)) / 3.3);
  const rt = clamp01(((f.overall_rating || 0) - 3) / 2);
  out.size_proxy = round3(0.6 * rc + 0.15 * rt + 0.25 * Math.min(1, ((f.branches || 1) - 1) / 3));
  out.unclaimed_listing = f.unclaimed_listing ? 1 : 0;
  out.profile_completeness = round3(0.7 * Math.min(1, (f.images_count || 0) / 15) + 0.3 * (f.has_hours ? 1 : 0));
  if (f.activity_label !== 'unknown') out.activity = f.activity_label === 'active' ? 1 : f.activity_label === 'slowing' ? 0.5 : 0;
  if (f.n_reviews_fetched >= 3) out.owner_engagement = round3(f.owner_reply_rate ?? 0);
  if (f.n_reviews_fetched >= 1) out.unanswered_low_reviews = round3((f.unanswered_low_reviews || 0) / 3);
  if (f.n_reviews_fetched >= 5 && f.rating_delta != null) out.rating_trend = round3(0.5 + Math.max(-0.5, Math.min(0.5, f.rating_delta / 1.0)));
  if (f.is_new_business === true) out.new_business = 1;
  return out;
}

/**
 * Value of the review_insights signal: how much of what customers complain about the seller's offer can help with (0..1).
 * Complaints the offer cannot help with count for nothing (spec 6.3b step 5). Undefined when there is no analysis.
 */
function reviewInsightValue(analysis) {
  if (!analysis || analysis.skipped) return undefined;
  const rel = (analysis.complaints || []).filter((c) => c && c.offer_can_help);
  const n = rel.reduce((a, c) => a + (Number(c.count) || 1), 0);
  const top = rel.slice().sort((a, b) => (b.count || 0) - (a.count || 0))[0];
  return { value: Math.min(1, n / 3), theme: top ? top.theme : null };
}

// ───────────────────────── opportunities (spec 6.3b step 3) ─────────────────────────
// Generic insight types computed from facts. WHICH ones matter, and the angle sentence for each, comes from the
// campaign's opportunity_map (planner output for this offer). Nothing is tied to a segment.
const OPPORTUNITY_TYPES = ['unclaimed_listing', 'no_website', 'thin_profile', 'unanswered_low_reviews', 'dormant_activity', 'declining_rating', 'low_owner_engagement', 'new_business', 'multi_branch', 'review_theme', 'weak_search_rank'];

function evalOpportunity(type, f, analysis) {
  switch (type) {
    case 'unclaimed_listing':
      return f.unclaimed_listing ? { strength: 2, evidence: { reviews: f.total_reviews } } : null;
    case 'no_website':
      return !f.has_website ? { strength: f.total_reviews >= 30 ? 3 : 2, evidence: { reviews: f.total_reviews, rating: f.overall_rating } } : null;
    case 'thin_profile':
      return f.images_count <= 5 || !f.has_hours ? { strength: f.images_count === 0 ? 3 : f.images_count <= 2 ? 2 : 1, evidence: { photos: f.images_count, hours: f.has_hours } } : null;
    case 'unanswered_low_reviews':
      return f.unanswered_low_reviews >= 1 ? { strength: Math.min(3, f.unanswered_low_reviews), evidence: { count: f.unanswered_low_reviews, of: f.n_reviews_fetched } } : null;
    case 'dormant_activity':
      return f.activity_label === 'dormant' ? { strength: 3, evidence: { days: f.days_since_last_review, last: f.last_review_at } }
        : f.activity_label === 'slowing' ? { strength: 1, evidence: { days: f.days_since_last_review, last: f.last_review_at } } : null;
    case 'declining_rating':
      return f.n_reviews_fetched >= 5 && f.rating_delta != null && f.rating_delta <= -0.3
        ? { strength: f.rating_delta <= -0.6 ? 3 : 2, evidence: { recent: f.recent_avg_rating, overall: f.overall_rating } } : null;
    case 'low_owner_engagement':
      return f.n_reviews_fetched >= 5 && f.owner_reply_rate != null && f.owner_reply_rate < 0.2
        ? { strength: f.owner_reply_rate === 0 && f.n_reviews_fetched >= 8 ? 3 : 2, evidence: { rate: f.owner_reply_rate, of: f.n_reviews_fetched } } : null;
    case 'new_business':
      return f.is_new_business === true ? { strength: 2, evidence: { reviews: f.total_reviews } } : null;
    case 'multi_branch':
      return f.branches >= 2 ? { strength: Math.min(3, f.branches), evidence: { branches: f.branches } } : null;
    case 'weak_search_rank':
      // Rank of the place inside the Maps result list of its search: the lower it appears, the less customers find it.
      return f.search_rank != null && f.search_rank >= 5 ? { strength: f.search_rank >= 10 ? 3 : f.search_rank >= 7 ? 2 : 1, evidence: { rank: f.search_rank } } : null;
    case 'review_theme': {
      // Complaint themes become an opportunity ONLY when the analysis says this offer can help, and confidence is not low.
      if (!analysis || analysis.confidence === 'low') return null;
      const hit = (analysis.complaints || []).filter((c) => c && c.offer_can_help).sort((a, b) => (b.count || 0) - (a.count || 0))[0];
      return hit ? { strength: Math.min(3, Math.max(1, hit.count || 1)), evidence: { theme: hit.theme, count: hit.count || 1 } } : null;
    }
    default:
      return null;
  }
}

/**
 * Top opportunities for one lead in one campaign.
 * @param {any} facts
 * @param {any} analysis review analysis (may be null)
 * @param {{type:string, angle:string}[]} oppMap campaign opportunity map, in the planner's priority order
 */
function buildOpportunities(facts, analysis, oppMap, max = 3) {
  const out = [];
  (oppMap || []).forEach((m, idx) => {
    if (!m || !OPPORTUNITY_TYPES.includes(m.type)) return;
    const e = evalOpportunity(m.type, facts, analysis);
    if (e) out.push({ type: m.type, strength: e.strength, evidence: e.evidence, angle: String(m.angle || '').slice(0, 200), _p: idx });
  });
  out.sort((a, b) => b.strength - a.strength || a._p - b._p);
  return out.slice(0, max).map((o) => ({ type: o.type, strength: o.strength, evidence: o.evidence, angle: o.angle }));
}

// ───────────────────────── score (spec 6.3a) ─────────────────────────
// Mirrors public.recompute_campaign_scores in SQL (same constants). Signed weights: w>0 rewards the HIGH state, w<0 the LOW state.
const SCORE = {
  favorable: 0.66, // a signal counts as "above zero" for the two-signal rule when its favorable state is this strong
  noBaseCap: 69, // fewer than two relevant non-baseline signals => score cannot exceed 69 (never "high" alone)
  maybeCap: 60,
  reasonMinWeight: 15, // a reason is shown only if its signal weighs MORE than this in the campaign (unless nothing stronger exists)
  baselineMaxWeight: 25, // baseline facts (e.g. has a website) are clamped unless the planner marked the signal as emphasized
};

/**
 * @param {{fit?:'fit'|'maybe'|'not_fit'|null, signals:{key:string, weight:number, value:number, baseline?:boolean, emphasis?:boolean}[]}} x
 * @returns {{score:number|null, relevant:number, capped_by:string|null, favorable:{key:string, side:'high'|'low', contribution:number}[]}}
 */
function scoreLead({ fit, signals }) {
  if (fit === 'not_fit') return { score: null, relevant: 0, capped_by: 'not_fit', favorable: [] };
  let sum = 0;
  let den = 0;
  let relevant = 0;
  const favorable = [];
  for (const s of signals) {
    let w = Number(s.weight);
    if (!w) continue;
    if (s.baseline && !s.emphasis) w = Math.sign(w) * Math.min(Math.abs(w), SCORE.baselineMaxWeight);
    const v = clamp01(Number(s.value));
    const c = w * v - Math.min(w, 0);
    sum += c;
    den += Math.abs(w);
    const fav = (w > 0 && v >= SCORE.favorable) || (w < 0 && v <= 1 - SCORE.favorable);
    if (fav) {
      favorable.push({ key: s.key, side: w > 0 ? 'high' : 'low', contribution: c, weight: Math.abs(Number(s.weight)) });
      if (!s.baseline || s.emphasis) relevant++;
    }
  }
  if (!den) return { score: null, relevant, capped_by: null, favorable };
  let score = Math.round((100 * sum) / den);
  let capped_by = null;
  if (relevant < 2 && score > SCORE.noBaseCap) { score = SCORE.noBaseCap; capped_by = 'needs_two_signals'; }
  if (fit === 'maybe' && score > SCORE.maybeCap) { score = SCORE.maybeCap; capped_by = 'maybe_fit'; }
  favorable.sort((a, b) => b.contribution - a.contribution);
  // Reasons from a signal weighing 15 or less in the campaign say little ("has a website"): hidden unless nothing stronger exists (mirrors the SQL).
  const strong = favorable.filter((f) => f.weight > SCORE.reasonMinWeight);
  return { score, relevant, capped_by, favorable: strong.length ? strong : favorable };
}

// ───────────────────────── message tact (spec 6.3b step 5) ─────────────────────────
// Safety net on top of the prompt: the first message never mentions complaints, low ratings or any weakness of the lead.
const NEGATIVE_AR = ['شكوي', 'شكاوي', 'شكوه', 'شتك', 'مشكله', 'مشاكل', 'سيء', 'سيئ', 'وحش', 'ضعيف', 'ضعف', 'تاخير', 'متاخر', 'اهمال', 'مهمل', 'قصور', 'فشل', 'بطيء', 'بطئ', 'غير راضي', 'مش راضي', 'تقييم سيء', 'تقييم منخفض', 'تقييم قليل', 'تقييمات منخفضه', 'تقييمات سلبيه', 'سلبي', 'نجمه واحده', 'نجمتين', 'ريفيوهات وحشه', 'عيب', 'عيوب', 'نقطه ضعف', 'نقاط ضعف', 'مفيش رد', 'بدون رد', 'مرددتوش', 'ما ردتوش', 'مردتوش', 'مش بتردو', 'مبتردوش'];
const NEGATIVE_EN = ['complain', 'bad review', 'low rating', 'poor rating', 'negative', 'weakness', 'problem with', 'unanswered'];

// Unsupported first-person claims about the lead (the sender has not seen their work): hearsay, own opinions, visits.
const CLAIMS_AR = ['سمعت', 'سمعنا', 'عاجبني', 'عجبني', 'عاجبنا', 'عجبنا', 'شايف ان شغل', 'شايف انكم', 'متابع شغل', 'تابعت', 'زرت', 'جربت', 'اتعاملت معاكم', 'شغلكم رائع', 'شغلكم ممتاز', 'شغلكم حلو', 'شغلكم تحفه', 'بتعملوا شغل رائع', 'بتقدموا شغل حلو', 'من افضل'];

/** @returns {{ok:boolean, reasons:string[]}} */
function checkTact(message, complaints = []) {
  const m = norm(message);
  const reasons = [];
  for (const w of NEGATIVE_AR.concat(NEGATIVE_EN)) if (m.includes(norm(w))) reasons.push(`word:${w}`);
  for (const w of CLAIMS_AR) if (m.includes(norm(w))) reasons.push(`claim:${w}`);
  // "your rating/reviews are low/bad" in any phrasing
  if (/(تقييم|ريفيو|نجوم|rating|review)\S*\s+(\S+\s+){0,2}(منخفض|قليل|ضعيف|سلبي|وحش|سيء|واطي|low|poor|bad)/.test(m)) reasons.push('rating_negative');
  for (const c of complaints || []) {
    const theme = typeof c === 'string' ? c : c && c.theme;
    for (const tok of norm(theme).split(' ')) if (tok.length >= 5 && m.includes(tok)) reasons.push(`theme:${tok}`);
  }
  return { ok: reasons.length === 0, reasons: [...new Set(reasons)] };
}


// ───────────────────────── message style rules (round 2) ─────────────────────────
// When the seller's product writes messages, the first message IS the demo: it must not read like a template. These are the
// checks that can be made in code; the prompt carries the rest. Nothing here depends on an industry or an offer.
const RATING_WORDS = ['تقييم', 'تقيم', 'نجمه', 'نجوم', 'ريفيو', 'rating', 'star', 'review'];
const JARGON_RE = /(^|[^a-z])(b2b|b2c|leads?|outreach|pipeline|crm|roi|kpi|funnel)([^a-z]|$)/i;
const JARGON_AR = ['بي تو بي', 'ليدز', 'ليد '];
const DAYTIME_AR = ['صباح', 'مساء'];
const WEAK_CTA = ['ممكن نتكلم', 'نتكلم اكتر', 'نتناقش', 'ممكن نتحدث', 'ممكن نتواصل', 'نتواصل معاكم'];
// Generic benefit phrases the writer likes to invent; allowed only if the seller's own offer text says so.
const BENEFIT_FLUFF = ['رضا العملاء', 'رضاهم', 'رضاكم', 'تعزيز التواصل', 'تقويه التواصل', 'يقوي التواصل', 'تحسين تجربه', 'يزود رضا', 'زياده رضا', 'جوده العمل', 'تركزوا علي شغلكم', 'تركز علي شغلها', 'تركزوا في شغلكم', 'شغلكم الاساسي', 'شغلها الاساسي', 'توفرو وقتكم', 'توفر وقتكم', 'تقلقوا', 'تقلق '];
// The sender has not seen their work: no own praise, and a first message promises no guarantee.
// Praise words are allowed only when the message attributes them to the customers ("عملاءكم بيشكروا في ..."); the sender's own praise is rejected.
const PRAISE_AR = ['مميز', 'ممتاز', 'رائع', 'شاطر', 'عظيم', 'متميز', 'تميز', 'احتراف', 'محترف', 'مختلف', 'متطور', 'ابداع', 'مبدع', 'خبره عاليه', 'باين عليكم', 'باين ان'];
const ATTRIBUTION = ['عملاءكم', 'عملاؤكم', 'عملائكم', 'بيشكروا', 'بيتكلموا', 'بيمدحوا', 'بيقولوا', 'بيحبوا'];
// Claims about the lead's own needs: "شغلكم ... بيحتاج/محتاج ...", "أكيد ...". Needs of the companies we would bring them ("شركات محتاجة خدماتكم") are fine.
const ASSUMES = /((^| )(اكيد|واضح انكم|باين انكم|واضح ان|باين ان)( |$))|(((انتم|انكم|بيخليكم)( \S+){0,2}|(^| )(شغلكم|نشاطكم|مجالكم|عملكم|خدمتكم|تخصصكم|شركتكم|وكالتكم)( \S+){0,6}) (بيحتاج|بتحتاج|يحتاج|محتاج|محتاجه|محتاجين|بيتطلب|بتتطلب)( |$))/;
// "always" is an overclaim about their customers or their work.
const OVERCLAIM_AR = ['دايما', 'دائما', 'طول الوقت', 'كل الناس'];
const GUARANTEE_AR = ['نضمن', 'بنضمن', 'هنضمن', 'مضمون', 'ضمان', 'guarantee'];
const STOP = new Set(['من', 'في', 'علي', 'عن', 'الي', 'مع', 'ده', 'دي', 'كده', 'لو', 'او', 'ان', 'انت', 'انتم', 'احنا', 'هو', 'هي']);

const wordList = (s) => String(s || '').trim().split(/\s+/).filter(Boolean);
const contentTokens = (s) => catTokens(s).filter((t) => t.length >= 2 && !STOP.has(t));

/**
 * Does the message copy a run of `n` or more consecutive words from one of the organization's style examples? Runs that also occur in the
 * seller's own offer text (its description and its call to action) are allowed: those words come from the offer, not from the example.
 */
function copiedRun(message, examples, allowedText = '', n = 8) {
  const toks = (t) => norm(t).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter(Boolean);
  const grams = (arr) => { const out = []; for (let i = 0; i + n <= arr.length; i++) out.push(arr.slice(i, i + n).join(' ')); return out; };
  const allowed = new Set(grams(toks(allowedText)));
  const mine = grams(toks(message)).filter((g) => !allowed.has(g));
  if (!mine.length) return false;
  const theirs = new Set((examples || []).flatMap((e) => grams(toks(e))));
  return mine.some((g) => theirs.has(g));
}

/** First five words of a message (normalized): two messages of one campaign must not share them. */
function openingKey(message) {
  return norm(message).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter(Boolean).slice(0, 5).join(' ');
}

/** Word-set overlap (Jaccard, 0..1) of two messages: two messages of one campaign above SIMILAR_LIMIT read like the same template. */
const SIMILAR_LIMIT = 0.6;
function messageSimilarity(a, b) {
  const t = (s) => new Set(norm(s).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter((w) => w.length > 2));
  const x = t(a);
  const y = t(b);
  const inter = [...x].filter((w) => y.has(w)).length;
  const uni = new Set([...x, ...y]).size;
  return uni ? inter / uni : 0;
}

/** Does the quoted phrase come from the seller's offer text? Exact (normalized) match, or at least 85% of its words, for 3+ words. */
function quoteInOffer(quote, offerText) {
  const q = norm(quote).replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\s+/g, ' ').trim();
  const o = norm(offerText).replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\s+/g, ' ').trim();
  if (q.split(' ').length < 3 || !o) return false;
  if (o.includes(q)) return true;
  const have = new Set(catTokens(o));
  const qt = catTokens(q);
  return qt.length >= 3 && qt.filter((t) => have.has(t)).length / qt.length >= 0.85;
}

/**
 * Style and honesty checks on one first message.
 * @param {string} message
 * @param {{channel?:string, areas?:string[], city?:string|null, offerText?:string, offerQuote?:string|null, ctaOffer?:string|null, senderName?:string|null}} ctx
 * @returns {{ok:boolean, reasons:string[]}}
 */
function checkMessage(message, ctx = {}) {
  const m = norm(message);
  const reasons = [];
  const chat = ctx.channel !== 'email';
  const n = wordList(message).length;
  if (chat && (n < 35 || n > 70)) reasons.push(`word_count_${n}`);
  for (const w of RATING_WORDS) if (m.includes(norm(w))) { reasons.push('mentions_rating'); break; }
  if (/[⭐★☆]/.test(message)) reasons.push('mentions_rating');
  if (JARGON_RE.test(m) || JARGON_AR.some((w) => m.includes(norm(w)))) reasons.push('jargon');
  if (DAYTIME_AR.some((w) => new RegExp(`(^| )${norm(w)}`).test(m)) || /good (morning|evening|afternoon)/.test(m)) reasons.push('time_greeting');
  // micro-districts: the lead's own district / neighborhood names are never used; the city (at most) is fine
  const city = norm(ctx.city || '');
  for (const a of ctx.areas || []) {
    const t = norm(a);
    if (t.length >= 3 && t !== city && !(city && city.includes(t)) && m.includes(t)) { reasons.push(`micro_district:${a}`); break; }
  }
  if (/(المنطقه|الحي|حي) (ال)?(اولي|ثانيه|ثالثه|رابعه|خامسه|سادسه|سابعه|ثامنه|تاسعه|عاشره|اول|ثاني|ثالث|رابع|خامس|سادس|سابع|ثامن|تاسع|عاشر)/.test(m)) reasons.push('micro_district:ordinal');
  if (WEAK_CTA.some((w) => m.includes(norm(w)))) reasons.push('weak_cta');
  {
    const ws = m.split(/\s+/);
    const own = ws.some((w, i) => PRAISE_AR.some((p) => w.includes(norm(p))) && !ws.slice(Math.max(0, i - 7), i).some((b) => ATTRIBUTION.some((a) => b.includes(norm(a)))));
    if (own) reasons.push('own_praise');
    if (ASSUMES.test(m)) reasons.push('assumes_need');
    if (OVERCLAIM_AR.some((w) => new RegExp(`(^| )${norm(w)}( |$)`).test(m))) reasons.push('overclaim_always');
  }
  if (GUARANTEE_AR.some((w) => m.includes(norm(w)))) reasons.push('guarantee');
  const offerN = norm(ctx.offerText || '');
  for (const f of BENEFIT_FLUFF) if (m.includes(norm(f)) && !offerN.includes(norm(f))) { reasons.push(`invented_benefit:${f}`); break; }
  if (ctx.offerText) {
    if (!ctx.offerQuote) reasons.push('offer_quote_missing');
    else if (!quoteInOffer(ctx.offerQuote, ctx.offerText)) reasons.push('offer_quote_not_in_offer');
  }
  if (ctx.ctaOffer) {
    const have = new Set(contentTokens(message));
    const hit = contentTokens(ctx.ctaOffer).filter((t) => have.has(t)).length;
    if (hit < 2) reasons.push('cta_offer_missing');
  }
  if (ctx.senderName && chat) {
    const tail = m.slice(-60);
    if (!tail.includes(norm(ctx.senderName))) reasons.push('missing_signature');
    // the sender's name appears once, in the signature at the end (never also as an introduction at the start)
    if (m.split(norm(ctx.senderName)).length - 1 > 1) reasons.push('double_signature');
  }
  if ((ctx.styleExamples || []).length && copiedRun(message, ctx.styleExamples, ctx.offerText || ctx.ctaOffer || '')) reasons.push('copies_style_example');
  return { ok: reasons.length === 0, reasons: [...new Set(reasons)] };
}

const REASON_HELP = {
  own_praise: 'you praised their work yourself (praise is allowed only as what their customers say)',
  assumes_need: 'you claimed something about what the lead itself needs',
  copies_style_example: 'you copied 8 or more consecutive words from a style example: write your own sentences',
  double_signature: 'the sender name appears more than once: it belongs only in the signature at the end',
  overclaim_always: 'you used "always" (دايما / دائما)',
  mentions_rating: 'you mentioned the rating, stars or reviews',
  jargon: 'you used jargon (B2B, leads...)',
  time_greeting: 'you used a time-of-day greeting',
  weak_cta: 'the ending was a weak "can we talk" question',
  guarantee: 'you promised or guaranteed something',
  invented_benefit: 'you promised a benefit that is not in the offer',
  offer_quote_missing: 'offer_quote was missing',
  offer_quote_not_in_offer: 'offer_quote was not copied word for word from sender_offer',
  cta_offer_missing: 'the concrete cta_offer was not in the ending',
  missing_signature: 'the signature was missing at the end',
  duplicate_opening: 'the opening is the same as another message',
  too_similar_to_another_message: 'the text is too close to another message',
  too_similar: 'the text is too close to another message',
};
function explainReason(reason) {
  const parts = String(reason).replace(/^style:/, '').split(/[,:]/).map((x) => x.trim()).filter(Boolean);
  const out = [];
  for (const p of parts) {
    if (REASON_HELP[p]) out.push(REASON_HELP[p]);
    else if (/^word_count_(\d+)$/.test(p)) out.push(`the text had ${p.slice(11)} words (it must be 35 to 70)`);
    else if (p === 'tact') out.push('you mentioned something negative (a problem, complaint or weakness) about the business or used a word like "problem"');
    else if (p === 'micro_district') out.push('you named a district or neighborhood');
  }
  return [...new Set(out)];
}

/** The single automatic retry of a rejected first message: same request plus the rejected reply and the reason as feedback. */
function retryRequestBody(requestBody, raw, reason) {
  const req = JSON.parse(requestBody);
  req.messages = [...req.messages, { role: 'assistant', content: raw || '{}' }, { role: 'user', content: `Your reply was rejected (${reason}). Rewrite it and return the JSON again. Remember: 35 to 70 words, no rating or stars or reviews, no district or neighborhood names, no jargon (no B2B), no time-of-day greeting, no "ممكن نتكلم", no praise of their work, no guarantees, no "focus on your core work" lines, address them as a team in the plural, end with the concrete offer (cta_offer) worded differently from the usual and the signature, offer_quote must be copied word for word from sender_offer, never invent benefits, never mention complaints or weaknesses, start differently from avoid_openings and use different sentences from the other messages of this campaign.` }];
  const why = explainReason(reason);
  if (why.length) req.messages[req.messages.length - 1].content += ` Specifically: ${why.join('; ')}.`;
  const wc = /word_count_(\d+)/.exec(String(reason));
  if (wc) req.messages[req.messages.length - 1].content += ` The text had ${wc[1]} words. Write between 45 and 60 words: ${Number(wc[1]) < 35 ? 'add one more concrete sentence about what the offer does (use the wording of offer_quote)' : 'cut the weakest sentence'}.`;
  req.temperature = 0.5;
  return JSON.stringify(req);
}

// ───────────────────────── LLM helpers (OpenRouter request/response) ─────────────────────────
/** OpenRouter chat request body (string). `fallback` = fallback model ids tried on provider failure. */
function llmRequest({ system, user, model, fallback = [], temperature = 0, extraMessages = [] }) {
  const req = {
    messages: [{ role: 'system', content: system }, { role: 'user', content: typeof user === 'string' ? user : JSON.stringify(user) }, ...extraMessages],
    response_format: { type: 'json_object' },
    temperature,
    usage: { include: true },
  };
  const fb = (fallback || []).filter(Boolean);
  if (fb.length) req.models = [model, ...fb]; else req.model = model;
  return JSON.stringify(req);
}

/** Parse an OpenRouter full-response item. @returns {{data:any|null, usage:{in:number,out:number,cost:number,model:string|null}, status:number|null}} */
function parseLlm(res) {
  const r = res || {};
  const u = (r.body && r.body.usage) || {};
  const usage = { in: u.prompt_tokens || 0, out: u.completion_tokens || 0, cost: Number(u.cost) || 0, model: (r.body && r.body.model) || null };
  let data = null;
  if (r.statusCode >= 200 && r.statusCode < 300 && r.body && r.body.choices) {
    try { data = JSON.parse((r.body.choices[0]?.message?.content || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch { data = null; }
  }
  return { data, usage, status: typeof r.statusCode === 'number' ? r.statusCode : null };
}

/** System prompt of the fit check (spec 6.0 step 3 and 4). Offer-agnostic: the ideal prospect text is the only criterion. */
function fitSystemPrompt({ ideal, offerText, negatives = [] }) {
  return `You judge whether Google Maps places are potential CUSTOMERS (prospects) for a seller.
Ideal prospect: ${ideal || '(not stated; judge from the seller offer)'}
Seller offer: ${String(offerText || '').slice(0, 500)}
For each place decide: "fit" (clearly the kind of business described), "maybe" (possibly, adjacent or unclear), "not_fit" (a different kind of business even if its NAME contains similar words, a public or government body, a competitor of the seller, or unrelated).
EVIDENCE RULES:
- Judge ONLY from the place's categories, its description and its website address. The business NAME is context only: words inside a name (including words that also appear in the ideal prospect text or the seller offer) are NOT evidence of what the business does or sells.
- When a word naming an industry, a product or a customer group sits next to the word that names the kind of business (in the name or in a category), it says what the business SELLS or serves, so the business belongs to THAT sector: answer "not_fit" (not "maybe"), unless the ideal prospect text itself asks for that sector.
- Return "evidence": the source that supports your label, one of "category", "description", "website", "name_only" (nothing but the name supports it) or "none". Use "fit" only when the evidence is category, description or website.
Give a SHORT reason (max 12 words, in the same language as the ideal prospect text).${negatives.length ? `\nThe seller already rejected businesses like these (treat similar ones as not_fit):\n${negatives.slice(0, 15).map((n) => `- ${n.business_name || ''} (${n.category || ''}): ${n.reason || ''}`).join('\n')}` : ''}
Return ONE JSON object only: {"results":[{"i": number, "fit": "fit"|"maybe"|"not_fit", "evidence": "category"|"description"|"website"|"name_only"|"none", "reason": string}]} covering every i.`;
}

const hostOf = (u) => { try { return new URL(/^[a-z]+:\/\//i.test(u) ? u : `https://${u}`).hostname.replace(/^www\./, '').toLowerCase(); } catch { return ''; } };

/** Social and messaging pages people use instead of a website. A business that only has one of these has no real website. */
const SOCIAL_HOSTS = ['facebook.com', 'fb.com', 'fb.me', 'instagram.com', 'linktr.ee', 'beacons.ai', 'tiktok.com', 'twitter.com', 'x.com', 'linkedin.com', 'wa.me', 'whatsapp.com', 'youtube.com', 'youtu.be', 't.me', 'behance.net'];
function isSocialUrl(u) {
  const h = hostOf(String(u || ''));
  return !!h && SOCIAL_HOSTS.some((s) => h === s || h.endsWith(`.${s}`));
}

/** The compact description of one place sent to the fit check: categories, description and website address are evidence; the name is context. */
function fitAsk(rawPlace, area) {
  const cats = [rawPlace.categoryName, ...(Array.isArray(rawPlace.categories) ? rawPlace.categories : [])].filter(Boolean);
  const desc = stripInvisible(rawPlace.description || rawPlace.ownerDescription || rawPlace.subTitle || '').slice(0, 240);
  return {
    name: stripInvisible(rawPlace.title), categories: [...new Set(cats)].slice(0, 8), description: desc || null,
    website: rawPlace.website ? hostOf(String(rawPlace.website)) || 'yes' : 'no', area: area || '', rating: rawPlace.totalScore ?? null, reviews: rawPlace.reviewsCount ?? null,
  };
}

/**
 * Keep or remove one place after the fit check (spec 6.0 step 4, round 2 fixes).
 * Inside the allowed categories: fit or maybe is kept (the category itself is evidence), not_fit removed.
 * Outside them: kept ONLY when the check said "fit" with evidence from the categories, description or website; never from the name,
 * never for "maybe". Nothing is learned from the model: a category joins the allowed list only through a user action.
 * @returns {{keep:boolean, fit?:'fit'|'maybe', why?:string}}
 */
function decideFit({ label, inside }) {
  const l = label || { fit: 'maybe', reason: 'unchecked' };
  if (l.fit === 'not_fit') return { keep: false, why: 'not_fit' };
  const ev = l.evidence;
  const real = ev === 'category' || ev === 'description' || ev === 'website';
  if (inside) return { keep: true, fit: l.fit === 'fit' && ev !== 'name_only' ? 'fit' : 'maybe' };
  if (l.fit === 'fit' && real) return { keep: true, fit: 'fit' };
  return { keep: false, why: l.fit === 'fit' ? 'name_only_evidence' : 'outside_categories' };
}

// ───────────────────────── search rounds (spec 6.2) ─────────────────────────
/** Search area of a location: the most specific name and a clean geocoder string (no repeated parts, no hidden characters). */
function areaOf(l) {
  // Unique parts; a part already contained in a more specific one is dropped ("القاهرة" inside "التجمع الخامس القاهرة").
  const parts = [cleanPlace(l.district), cleanPlace(l.city), cleanPlace(l.governorate)].filter(Boolean);
  const kept = parts.filter((p, i) => !parts.some((q, j) => j !== i && norm(q) !== norm(p) && norm(q).includes(norm(p))) && parts.findIndex((q) => norm(q) === norm(p)) === i);
  return { area: cleanPlace(l.district || l.city || l.governorate || ''), locationQuery: kept.concat('Egypt').join(', ') };
}

/**
 * Plan the Apify searches for a round. Rounds: 1 base queries at real depth; 2 same queries deeper (only the ones that hit
 * their cap); 3 synonyms; 4 nearby districts; 5 broad fallback (city level, simplest keyword) used for zero results.
 * @returns {{round:number, searches:{query:string, area:string, locationQuery:string, depth:number}[]}|null} null = exhausted
 */
function planRound({ round, target, keywords, synonyms = [], locations, nearby = [], done = [], saturated = [], avoid = [], minDepth = 20, maxDepth = 120 }) {
  const doneSet = new Set(done.map((d) => norm(d)));
  const loc = areaOf;
  const mk = (kws, locs, depthMul = 1) => {
    const base = Math.min(maxDepth, Math.max(minDepth, Math.ceil((target * 2.5) / Math.max(1, kws.length * locs.length))));
    const depth = Math.min(maxDepth, Math.ceil(base * depthMul));
    const s = [];
    for (const l of locs) {
      const { area, locationQuery } = loc(l);
      for (const k of kws) {
        const query = `${cleanPlace(k)} ${area}`.trim();
        s.push({ query, area, locationQuery, depth, key: norm(`${depthMul}|${query}`) });
      }
    }
    return s;
  };
  let searches = [];
  if (round === 1) searches = mk(keywords, locations);
  else if (round === 2) {
    const sat = new Set(saturated.map(norm));
    searches = mk(keywords, locations, 2.5).filter((s) => sat.has(norm(s.query)));
  } else if (round === 3) searches = mk(synonyms, locations);
  else if (round === 4) searches = mk(keywords.concat(synonyms).slice(0, 4), nearby);
  else if (round === 5) {
    // Broad fallback: simplest keyword, city level (or governorate), no district polygon.
    const broad = locations.map((l) => ({ governorate: l.governorate, city: l.city || l.governorate, district: '' }));
    searches = mk(keywords.slice(0, 2), broad.length ? broad : locations);
  } else return null;
  // `avoid` = searches this organization already ran in earlier campaigns: the same companies would come back, so prefer new ones.
  const avoidSet = new Set(avoid.map(norm));
  searches = searches.filter((s) => s.query && !doneSet.has(norm(s.query) + '|' + round) && !avoidSet.has(norm(s.query)));
  return searches.length ? { round, searches } : null;
}

/**
 * After a round: which round next (null = stop). Normal order 1..5; if round 1 found no places at all the engine jumps to the
 * broad fallback first (city level, simplest keywords), then synonyms and nearby districts.
 * @returns {{next:number|null, mode:'normal'|'zero'}}
 */
function decideNext({ round, mode = 'normal', delivered, target, rawTotal }) {
  if (delivered >= target) return { next: null, mode };
  if (round === 1 && rawTotal === 0) return { next: 5, mode: 'zero' };
  if (mode === 'zero') return { next: round === 5 ? 3 : round === 3 ? 4 : null, mode };
  return { next: round < 5 ? round + 1 : null, mode };
}

/** Why a campaign delivered nothing (plain code, mapped to a user message with concrete suggestions in the UI). */
function emptyReason(f) {
  if (!f.raw_places) return 'no_places';
  if (f.removed_not_fit >= (f.raw_places - f.removed_category - f.removed_global - f.removed_closed) && f.removed_not_fit > 0) return 'all_not_fit';
  if (f.removed_category + f.removed_global >= f.raw_places * 0.8) return 'all_category';
  if (f.previously_found > 0 && f.previously_found >= f.raw_places * 0.5) return 'all_previously_found';
  if (f.cooldown > 0 && f.cooldown >= f.raw_places * 0.5) return 'all_cooldown';
  return 'all_filtered';
}

/** Funnel keys shown on the campaign page, in order (spec 6.2). */
const FUNNEL_KEYS = ['queries', 'raw_places', 'removed_category', 'removed_global', 'removed_closed', 'removed_landline', 'removed_filters', 'removed_not_fit', 'duplicates', 'previously_found', 'opted_out', 'cooldown', 'delivered'];

const body = $('Webhook').first().json.body;
const job = $('Claim job').first().json;
const campaign = $('Get campaign').first().json;
const org = $('Get org').first().json;
const links = $('Get campaign leads').all().map((i) => i.json).filter((r) => r.leads);
const messages = $('Get messages').all().map((i) => i.json);
const insightsByLead = new Map($('Get insights').all().map((i) => i.json).filter((r) => r && r.lead_id).map((r) => [r.lead_id, r]));
const cooling = new Set($('Get cooldown').all().map((i) => i.json.lead_id).filter(Boolean));

const p = campaign.parameters || {};
const channel = p.channel || 'whatsapp';
const tone = p.tone || 'friendly';
const TONES = {
  friendly: 'ودود وخفيف، زي زميل بيكلم زميل',
  professional: 'مهذب ومحترم وجاد من غير تكلف',
  direct: 'مباشر وواضح وقصير من غير لف ودوران',
};
const profile = org.offer_profile || {};
const offer = (p.offer_override && String(p.offer_override).trim())
  ? { what_we_sell: String(p.offer_override).trim(), problems_we_solve: profile.problems_we_solve || '', proof_points: profile.proof_points || '', cta_offer: profile.cta_offer || '' }
  : { what_we_sell: profile.what_we_sell || '', problems_we_solve: profile.problems_we_solve || '', proof_points: profile.proof_points || '', cta_offer: profile.cta_offer || '' };
const senderName = String(profile.sender_name || '').trim() || null;
const signature = senderName ? (org.name ? `${senderName} من ${org.name}` : senderName) : null;
const offerText = [offer.what_we_sell, offer.problems_we_solve, offer.proof_points, offer.cta_offer].filter(Boolean).join('. ');
const generalAngle = p.angle && typeof p.angle === 'object' ? p.angle : null;
const oppMap = new Map(((p.opportunities) || []).map((o) => [o.type, o]));

// Style examples are NOT part of this global prompt: they belong to the organization (offer_profile.style_examples, optional, empty by default).
const styleExamples = (Array.isArray(profile.style_examples) ? profile.style_examples : []).map((x) => String(x || '').trim()).filter(Boolean).slice(0, 3).map((x) => x.slice(0, 700));

const SYSTEM = `You write the FIRST outreach message that one company sends to another business, in natural Egyptian colloquial Arabic. A busy owner reads it on their phone: it must sound like one real person wrote it for THIS business, never like a template or an ad.
Return ONE JSON object only: ${channel === 'email' ? '{"subject": string, "message": string, "angle": string, "offer_quote": string}' : '{"message": string, "angle": string, "offer_quote": string}'}.
- "angle": a short Arabic note (max 80 chars) naming the hook you used.
- "offer_quote": an EXACT phrase of 3 to 12 words copied word for word from sender_offer (what_we_sell, problems_we_solve, proof_points or cta_offer) that states the benefit your message promises. The message may promise NOTHING that this phrase does not support.
Rules:
1. Length: ${channel === 'email' ? 'email body 60 to 120 words, plain text, subject up to 70 characters.' : 'aim for 50 to 60 words (never fewer than 35, never more than 70; count them, short drafts are rejected). Use four short sentences: the opening, what the offer does, why that fits them, then the call to action; the signature comes after. No links, no URLs, no phone numbers.'}
2. NEVER mention the business's rating, stars or number of reviews. NEVER mention any district, neighborhood or street. You may name the city at most once, or not at all.
3. NEVER use jargon or English business words (no "B2B", "leads", "outreach", "pipeline", "CRM"). Use plain Egyptian words (شركات، عملاء جداد، رسايل).
4. No time-of-day greeting (no صباح الخير, مساء الخير, صباح الفل or similar): you do not know when it will be read. Start directly or with a short "أهلا".
5. At most ONE personal detail, and only from personal_hook (the business's specialty, or what its customers praise), phrased naturally, for example "عملاءكم بيشكروا في ..." (never write "دايما" or "دائما": that overclaims) or "شغلكم في ...". If personal_hook is empty or weak, open with the offer in a clean general way. Never invent a detail. You have NOT seen their work: never say you heard about them, liked their work, followed them, or that they are great.
6. NEVER invent benefits, numbers, results, prices or clients. Promise only what your offer_quote supports. Do not add lines about customer satisfaction, better communication, growth or quality unless the offer itself says so.
7. Ending: a concrete, low-friction call to action. If sender_offer.cta_offer exists, offer exactly that in your own words. Otherwise end with ONE short question about how they find clients today (or how they handle the thing the offer is about). NEVER end with "ممكن نتكلم؟" or any "can we talk / meet / connect" question.
8. If required_signature is given, the message ends with exactly those words (the last words of the text). The sender's name appears ONLY there: never introduce yourself by name at the start or in the middle.
9. No emoji (zero by default).
10. TACT: never mention complaints, low ratings, missing things or any weakness of the business, not even politely. help_angle (when present) is what OUR offer does; present it as a capability of the offer, never as a gap of theirs.
11. Variety: follow opening_style. Do NOT start with any of avoid_openings. Never use the skeleton "greeting + I saw you in X + we help companies like you + can we talk".
12. Address them as a team in the plural (انتم، شغلكم، تحبوا), never in the singular. Short sentences, natural Egyptian words (إزاي، دلوقتي، كده، ممكن), not formal Arabic.
13. Never praise their work yourself (no مميز، ممتاز، رائع، شاطرين، احترافي، متميز), and never assume what they need or want (no "أكيد محتاجين", "أكيد بتدوروا", "واضح إنكم"). Praise may appear only as what THEIR CUSTOMERS say, taken from personal_hook.customers_praise. Never promise or guarantee anything (no نضمن، مضمون). Never add benefits such as saving their time or letting them focus on their core work: only what offer_quote says.
14. Word the concrete call to action in a fresh way each time (keep the substance of cta_offer: what, how many, that it is free); do not reuse one fixed sentence.
15. If style_examples is present, they are messages this seller likes: match their tone and length, NOT their sentences. Never reuse a run of 8 or more consecutive words from them, and do not follow their sentence-by-sentence skeleton; their offer and numbers come from sender_offer only.`;

// One opening per lead, rotating, so the messages of one campaign do not share a skeleton (the validator also rejects shared openings and near-copies).
const STYLES = [
  'Begin with "أهلا يا فريق" and their business name, then the single personal detail from personal_hook (if there is none, one plain line about their field), then the offer, then the call to action.',
  'Begin with the words "سؤال سريع:" and one short question about how they handle the thing the offer is about today, then the offer, then the call to action.',
  'Begin with the words "لو بتدوروا على" and finish the thought with what the offer gives them, then who you are, then the call to action.',
  'Begin with the name of the sender company as the subject of one plain sentence about what its tool does; no greeting; then why it fits a business like theirs; then the call to action.',
  'Begin with the words "فكرة سريعة:" followed by what the offer would do for a business like theirs, then the call to action.',
  'Begin with the personal detail from personal_hook as a short remark (if there is none, a remark about the kind of work they do), then "عشان كده" and the offer, then the call to action.',
  'Begin with the words "بعد إذنكم،" then what the tool of the sender does in one sentence (do not say your name here: the name appears only in the signature), then the call to action.',
  'Begin with one short honest sentence saying you are writing because their field is the one the offer is built for, then the offer, then the call to action.',
];

// Targets: explicit lead ids, a regeneration, or every eligible lead that has no message yet.
const failedRows = new Map(messages.filter((m) => m.channel === channel && m.review_status === 'failed').map((m) => [m.lead_id, m]));
const haveMsg = new Set(messages.filter((m) => m.channel === channel && m.review_status !== 'failed').map((m) => m.lead_id));
let chosen;
let regen = null;
let skippedCooldown = 0;
if (body.regenerate && body.regenerate.message_id) {
  regen = messages.find((m) => m.id === body.regenerate.message_id);
  chosen = regen ? links.filter((r) => r.leads.id === regen.lead_id) : [];
} else {
  const ids = Array.isArray(body.lead_ids) && body.lead_ids.length ? new Set(body.lead_ids) : null;
  chosen = links.filter((r) => {
    const l = r.leads;
    if (ids && !ids.has(l.id)) return false;
    if (haveMsg.has(l.id)) return false;
    if (l.status === 'opted_out') return false;
    if (cooling.has(l.id)) { skippedCooldown++; return false; } // 30-day contact cooldown (also enforced by a DB trigger)
    if (channel === 'whatsapp' && !l.whatsapp_eligible) return false;
    return true;
  });
}
chosen = chosen.slice(0, Math.max(0, job.credits_reserved));

if (!chosen.length) return [{ json: { noop: true, skippedCooldown } }];

// Openings already used in this campaign: a new message may not start the same way (first five words).
const usedOpenings = [...new Set(messages.map((m) => m.edited_text || m.generated_text).filter(Boolean).map(openingKey).filter(Boolean))].slice(-40);

return chosen.map((r, idx) => {
  const l = r.leads;
  const ins = insightsByLead.get(l.id) || {};
  const analysis = ins.analysis && !ins.analysis.skipped ? ins.analysis : null;
  const confident = analysis && analysis.confidence && analysis.confidence !== 'low';

  // The opportunity the message is built on: the one chosen on the lead (user can switch it), only if the planner tied it to the offer.
  const opps = Array.isArray(r.opportunities) ? r.opportunities : [];
  // dormant_activity at strength 1 (about 4 to 8 months without a review) is too weak to be an angle; it stays visible in the brief.
  const angleOpps = opps.filter((o) => !(o.type === 'dormant_activity' && Number(o.strength) < 2));
  const sel = angleOpps.find((o) => o.type === r.selected_opportunity) || angleOpps[0] || null;
  const mapped = sel ? oppMap.get(sel.type) : null;
  const linked = !!(sel && mapped && (mapped.why_it_means_they_need_the_offer || mapped.angle_ar || mapped.angle));
  const helpAngle = linked ? (mapped.angle_ar || mapped.angle || sel.angle || null) : null;
  const usable = linked && !(sel.type === 'review_theme' && !confident);

  // Personal hook (only neutral or positive, true things): the lead's other Maps categories (its specialty) and what its customers praise.
  const rawCats = Array.isArray(l.raw_categories) ? l.raw_categories : (l.raw && Array.isArray(l.raw.categories) ? l.raw.categories : []);
  const factCats = ins.facts && Array.isArray(ins.facts.categories) ? ins.facts.categories : [];
  const main = norm(l.category || '');
  const specialty = [...new Set([...rawCats, ...factCats].map((c) => String(c || '').trim()).filter((c) => c && norm(c) !== main))].slice(0, 3);
  const description = String(l.raw_description || (l.raw && (l.raw.description || l.raw.ownerDescription)) || '').trim().slice(0, 160) || null;
  const hook = {};
  if (specialty.length) hook.specialty = specialty;
  const praised = confident && analysis.praised ? analysis.praised.filter((x) => Number(x.count) >= 2) : []; // one review is an anecdote, not a pattern
  if (praised.length) hook.customers_praise = praised.slice(0, 2).map((x) => x.theme);
  if (description) hook.description = description;

  const areas = [l.district, l.raw_neighborhood, l.raw && l.raw.neighborhood, l.raw && l.raw.street ? String(l.raw.street).split(',')[0] : null].filter(Boolean);
  const user = {
    tone: TONES[tone] || TONES.friendly,
    channel,
    opening_style: STYLES[idx % STYLES.length],
    avoid_openings: usedOpenings,
    business_name: l.business_name,
    business_type: l.category || null,
    city: l.city || null,
    personal_hook: hook,
    sender_company_name: org.name || null,
    sender_name: senderName,
    required_signature: signature,
    sender_offer: offer,
    ...(styleExamples.length ? { style_examples: styleExamples } : {}),
    help_angle: usable ? helpAngle : null,
    help_angle_reason: usable && mapped ? (mapped.why_it_means_they_need_the_offer || null) : null,
    general_angle: generalAngle,
    extra_instruction: regen ? (body.regenerate.instruction || null) : null,
  };
  const req = {
    messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: JSON.stringify(user) }],
    response_format: { type: 'json_object' },
    temperature: 0.8,
    usage: { include: true },
  };
  const fb = Array.isArray(body.fallback_models) ? body.fallback_models.filter(Boolean) : [];
  if (fb.length) req.models = [body.model, ...fb]; else req.model = body.model;
  return {
    json: {
      lead_id: l.id,
      message_id: regen ? regen.id : (failedRows.get(l.id) ? failedRows.get(l.id).id : null),
      regen_count: regen ? (regen.regen_count || 0) + 1 : (failedRows.get(l.id) ? (failedRows.get(l.id).regen_count || 0) + 1 : 0),
      channel,
      organization_id: body.organization_id,
      campaign_id: body.campaign_id,
      job_id: body.job_id,
      requestBody: JSON.stringify(req),
      // kept ONLY for validation and the learning loop; never sent to the model
      complaints: analysis ? (analysis.complaints || []).map((c) => c.theme) : [],
      opportunity_type: usable && sel ? sel.type : null,
      offer_text: offerText,
      cta_offer: offer.cta_offer || null,
      sender_name: senderName,
      style_examples: styleExamples,
      signature,
      areas,
      city: l.city || null,
      used_openings: usedOpenings,
      total: chosen.length,
      skippedCooldown,
    },
  };
});

// WF3 "Validate message": parse the LLM JSON and enforce the message rules (spec 6.4, 6.3b step 5 and the round 2 style rules). Runs once per item.
// Used by two nodes: "Validate message" (first attempt) and "Validate retry" (the single automatic retry, with feedback).
// Lead insights core (spec 6.2, 6.3a, 6.3b). Plain ESM JS with no imports so the SAME source is inlined into n8n Code
// nodes (marker /*__INSIGHTS__*/) and used by unit tests and the fixture runner. Nothing here knows any industry,
// segment or offer: relevance always comes from the campaign (allowed categories, signal weights, opportunity map).

// ───────────────────────── text helpers ─────────────────────────
const INVISIBLE = new RegExp('[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]', 'g');
const DIACRITICS = new RegExp('[\u064B-\u065F\u0670\u0640]', 'g');

/** Lowercase, strip invisible/bidi marks and Arabic diacritics, unify alef/yaa/taa-marbuta, collapse spaces. */
function norm(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(INVISIBLE, '')
    .replace(DIACRITICS, '')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Invisible/bidi marks removed, whitespace collapsed. */
function stripInvisible(s) {
  return String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
}

/** Clean one location part for Apify: no invisible marks, no repeated words ("التجمع الخامس القاهرة القاهرة"). */
function cleanPlace(s) {
  const t = String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
  const out = [];
  for (const w of t.split(' ')) if (!out.length || norm(out[out.length - 1]) !== norm(w)) out.push(w);
  return out.join(' ');
}

// ───────────────────────── global exclusions (spec 6.3a) ─────────────────────────
// Always on, for every campaign. Matched against Google Maps CATEGORIES (Arabic and English), never against the name alone.
// Hospitals only for health: clinics, labs and pharmacies are legitimate prospects for many offers.
const GLOBAL_EXCLUSIONS = {
  government: ['مكتب حكومي', 'جهه حكوميه', 'هيئه حكوميه', 'مبني حكومي', 'وزاره', 'محافظه', 'مجلس مدينه', 'قسم شرطه', 'مركز شرطه', 'محكمه', 'نيابه', 'مصلحه', 'سجل مدني', 'government office', 'government organization', 'government agency', 'local government', 'city government', 'county government', 'municipality', 'ministry', 'police', 'courthouse', 'public administration'],
  utility: ['محطه كهرباء', 'محطه توليد', 'محطه مياه', 'محطه معالجه', 'محطه تحويل', 'محطه صرف', 'شركه كهرباء', 'شركه مياه', 'شركه غاز', 'سنترال', 'مرفق عام', 'power station', 'power plant', 'electric utility', 'electricity', 'water utility', 'water treatment', 'water works', 'sewage', 'telephone exchange', 'substation', 'gas utility', 'public utility'],
  education: ['جامعه', 'كليه', 'مدرسه', 'روضه اطفال', 'ثانويه', 'اعداديه', 'ابتدائيه', 'university', 'college', 'school', 'kindergarten', 'academy of', 'faculty'],
  health: ['مستشفي', 'hospital'],
  worship: ['مسجد', 'جامع', 'كنيسه', 'دير', 'معبد', 'مكان عباده', 'mosque', 'church', 'temple', 'synagogue', 'place of worship', 'cathedral', 'monastery'],
  embassy: ['سفاره', 'قنصليه', 'embassy', 'consulate'],
  military: ['موقع عسكري', 'قاعده عسكريه', 'معسكر', 'عسكري', 'military', 'army base', 'air force', 'naval'],
};

const hasEn = (p) => /^[a-z ]+$/.test(p);
const catMatches = (c, p) => (hasEn(p) ? new RegExp(`(^| )${p}( |$|s\\b)`).test(c) : c.includes(p));

/** @returns {{group:string, match:string, category:string}|null} */
function globalExclusion(categories) {
  for (const raw of categories || []) {
    const c = norm(raw);
    if (!c) continue;
    for (const [group, pats] of Object.entries(GLOBAL_EXCLUSIONS)) {
      for (const p of pats) if (catMatches(c, norm(p))) return { group, match: p, category: String(raw) };
    }
  }
  return null;
}

/** Brand part of a business name ("X - Nasr City" and "X (Maadi)" are the same brand), normalized. */
function brandKey(name) {
  return norm(String(name || '').split(/\s[-–|]\s|\(|\|/)[0]).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

/**
 * Branches of one business: listings of the organization with the same normalized brand name AND the same website or the same phone
 * (a Facebook/Instagram page is not a shared website). Name similarity alone never counts: it is what made unrelated places look like chains.
 * @param {{business_name?:string, website?:string, phone_e164?:string}} self
 * @param {{business_name?:string, website?:string, phone_e164?:string}[]} all every listing of the organization (the business itself included)
 */
function countBranches(self, all) {
  const key = brandKey(self.business_name);
  if (!key) return 1;
  const site = (u) => (u && !isSocialUrl(u) ? hostOf(String(u)) : '');
  const mySite = site(self.website);
  const myPhone = self.phone_e164 || '';
  let n = 0;
  for (const o of all || []) {
    if (brandKey(o.business_name) !== key) continue;
    if ((mySite && site(o.website) === mySite) || (myPhone && o.phone_e164 === myPhone)) n++;
  }
  return Math.max(1, n);
}

/** Light stemmer so "وكالات" matches "وكالة" and "Agencies" matches "agency" (no dictionary, no segment knowledge). */
function stemToken(raw) {
  let t = norm(raw);
  if (/^[a-z0-9]+$/.test(t)) {
    if (t.length > 4 && t.endsWith('ies')) return t.slice(0, -3) + 'y';
    if (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) return t.slice(0, -1);
    return t;
  }
  if (t.length > 4) t = t.replace(/^(وال|بال|لل|ال)/, '');
  if (t.length > 3) t = t.replace(/(ات|ون|ين|ان)$/, '');
  if (t.length > 3) t = t.replace(/ه$/, '');
  if (t.length > 3) t = t.replace(/ي$/, '');
  return t;
}
const catTokens = (s) => norm(s).split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(stemToken);

/**
 * Does any Maps category match the campaign's allowed categories (Arabic and English)? Done by us, never by the actor.
 * Singular/plural and the Arabic article are ignored. An allowed entry matches a place category when all its words occur in the
 * category, or the category is a (parent) subset of the entry. An empty allow-list means "no category restriction" (old campaigns).
 * @returns {{ok:boolean, matched:string|null}}
 */
function categoryMatch(placeCategories, allowed) {
  const list = (allowed || []).map((a) => ({ a, tokens: catTokens(a) })).filter((x) => x.tokens.length && norm(x.a).length >= 3);
  if (!list.length) return { ok: true, matched: null };
  for (const raw of placeCategories || []) {
    const c = catTokens(raw);
    if (!c.length) continue;
    const cs = new Set(c);
    for (const { a, tokens } of list) {
      const as = new Set(tokens);
      if (tokens.every((t) => cs.has(t))) return { ok: true, matched: a };
      if (c.every((t) => as.has(t)) && (c.length >= 2 || c[0].length >= 4)) return { ok: true, matched: a };
    }
  }
  return { ok: false, matched: null };
}

// ───────────────────────── deterministic facts (spec 6.3b step 1) ─────────────────────────
const DAY = 86400000;
const MONTH = 30.44 * DAY;
const r1 = (x) => Math.round(x * 10) / 10;

/**
 * @param {any} place raw Google Maps place (compass/crawler-google-places)
 * @param {any[]} reviews raw reviews for that place (compass/google-maps-reviews-scraper), newest first or any order
 * @param {{now?:number, branches?:number}} [opt]
 */
function computeFacts(place, reviews = [], opt = {}) {
  const now = opt.now ?? Date.now();
  const seen = new Set();
  const rev = [];
  for (const r of reviews || []) {
    if (!r) continue;
    const id = r.reviewId || `${r.publishedAtDate}|${r.stars}|${r.text}`;
    if (seen.has(id)) continue;
    seen.add(id);
    rev.push(r);
  }
  const dates = rev.map((r) => Date.parse(r.publishedAtDate)).filter(Number.isFinite).sort((a, b) => a - b);
  const n = rev.length;
  const total = Number(place.reviewsCount) || n;
  const overall = Number(place.totalScore) || null;
  const last = dates.length ? dates[dates.length - 1] : null;
  const oldest = dates.length ? dates[0] : null;
  const sinceLast = last == null ? null : (now - last) / DAY;
  const activity_label = last == null ? 'unknown' : sinceLast <= 90 ? 'active' : sinceLast <= 365 ? 'slowing' : 'dormant';
  const spanMonths = oldest == null ? null : Math.max(0.25, (now - oldest) / MONTH);
  const replies = rev.filter((r) => r.responseFromOwnerText && String(r.responseFromOwnerText).trim()).length;
  const low = rev.filter((r) => Number(r.stars) <= 2);
  const stars = rev.map((r) => Number(r.stars)).filter(Number.isFinite);
  const recent_avg = stars.length ? stars.reduce((a, b) => a + b, 0) / stars.length : null;
  const texts = rev.filter((r) => (r.text || r.textTranslated || '').toString().trim());
  const images = Number(place.imagesCount) || 0;
  return {
    n_reviews_fetched: n,
    n_texts: texts.length,
    total_reviews: total,
    overall_rating: overall,
    last_review_at: last == null ? null : new Date(last).toISOString(),
    days_since_last_review: sinceLast == null ? null : Math.round(sinceLast),
    reviews_per_month: spanMonths == null || n < 2 ? null : r1(n / spanMonths),
    activity_label,
    // Only claim "new" when the fetched window provably covers the whole history and it started within a year.
    is_new_business: oldest != null && now - oldest <= 365 * DAY && total <= n ? true : null,
    owner_reply_rate: n ? Math.round((replies / n) * 100) / 100 : null,
    low_reviews: low.length,
    unanswered_low_reviews: low.filter((r) => !(r.responseFromOwnerText && String(r.responseFromOwnerText).trim())).length,
    recent_avg_rating: recent_avg == null ? null : r1(recent_avg),
    rating_delta: recent_avg == null || overall == null ? null : r1(recent_avg - overall),
    unclaimed_listing: place.claimThisBusiness === true,
    images_count: images,
    has_hours: Array.isArray(place.openingHours) && place.openingHours.length > 0,
    has_description: !!(place.description || place.ownerDescription || place.subTitle),
    // A Facebook/Instagram/link page used as the "website" is not a real website.
    has_website: !!(place.website && String(place.website).trim()) && !isSocialUrl(place.website),
    website_social: !!(place.website && isSocialUrl(place.website)),
    search_rank: Number.isFinite(Number(place.rank)) && Number(place.rank) > 0 ? Number(place.rank) : null,
    categories: [...new Set([place.categoryName, ...(Array.isArray(place.categories) ? place.categories : [])].filter(Boolean))].slice(0, 8),
    low_star_share: (() => { const d = place.reviewsDistribution; if (!d) return null; const t = ['oneStar', 'twoStar', 'threeStar', 'fourStar', 'fiveStar'].reduce((x, k) => x + (Number(d[k]) || 0), 0); return t ? Math.round((((Number(d.oneStar) || 0) + (Number(d.twoStar) || 0)) / t) * 100) / 100 : null; })(),
    permanently_closed: !!place.permanentlyClosed,
    temporarily_closed: !!place.temporarilyClosed,
    branches: opt.branches ?? 1,
  };
}

const clamp01 = (v) => Math.max(0, Math.min(1, v));
const round3 = (v) => Math.round(clamp01(v) * 1000) / 1000;

/** Normalized signal values (0..1, 1 = the signal's HIGH state) from facts. Unknown stays absent (never guessed). */
function signalValues(f) {
  const out = {};
  out.has_website = f.has_website ? 1 : 0;
  const rc = Math.min(1, Math.log10(1 + (f.total_reviews || 0)) / 3.3);
  const rt = clamp01(((f.overall_rating || 0) - 3) / 2);
  out.size_proxy = round3(0.6 * rc + 0.15 * rt + 0.25 * Math.min(1, ((f.branches || 1) - 1) / 3));
  out.unclaimed_listing = f.unclaimed_listing ? 1 : 0;
  out.profile_completeness = round3(0.7 * Math.min(1, (f.images_count || 0) / 15) + 0.3 * (f.has_hours ? 1 : 0));
  if (f.activity_label !== 'unknown') out.activity = f.activity_label === 'active' ? 1 : f.activity_label === 'slowing' ? 0.5 : 0;
  if (f.n_reviews_fetched >= 3) out.owner_engagement = round3(f.owner_reply_rate ?? 0);
  if (f.n_reviews_fetched >= 1) out.unanswered_low_reviews = round3((f.unanswered_low_reviews || 0) / 3);
  if (f.n_reviews_fetched >= 5 && f.rating_delta != null) out.rating_trend = round3(0.5 + Math.max(-0.5, Math.min(0.5, f.rating_delta / 1.0)));
  if (f.is_new_business === true) out.new_business = 1;
  return out;
}

/**
 * Value of the review_insights signal: how much of what customers complain about the seller's offer can help with (0..1).
 * Complaints the offer cannot help with count for nothing (spec 6.3b step 5). Undefined when there is no analysis.
 */
function reviewInsightValue(analysis) {
  if (!analysis || analysis.skipped) return undefined;
  const rel = (analysis.complaints || []).filter((c) => c && c.offer_can_help);
  const n = rel.reduce((a, c) => a + (Number(c.count) || 1), 0);
  const top = rel.slice().sort((a, b) => (b.count || 0) - (a.count || 0))[0];
  return { value: Math.min(1, n / 3), theme: top ? top.theme : null };
}

// ───────────────────────── opportunities (spec 6.3b step 3) ─────────────────────────
// Generic insight types computed from facts. WHICH ones matter, and the angle sentence for each, comes from the
// campaign's opportunity_map (planner output for this offer). Nothing is tied to a segment.
const OPPORTUNITY_TYPES = ['unclaimed_listing', 'no_website', 'thin_profile', 'unanswered_low_reviews', 'dormant_activity', 'declining_rating', 'low_owner_engagement', 'new_business', 'multi_branch', 'review_theme', 'weak_search_rank'];

function evalOpportunity(type, f, analysis) {
  switch (type) {
    case 'unclaimed_listing':
      return f.unclaimed_listing ? { strength: 2, evidence: { reviews: f.total_reviews } } : null;
    case 'no_website':
      return !f.has_website ? { strength: f.total_reviews >= 30 ? 3 : 2, evidence: { reviews: f.total_reviews, rating: f.overall_rating } } : null;
    case 'thin_profile':
      return f.images_count <= 5 || !f.has_hours ? { strength: f.images_count === 0 ? 3 : f.images_count <= 2 ? 2 : 1, evidence: { photos: f.images_count, hours: f.has_hours } } : null;
    case 'unanswered_low_reviews':
      return f.unanswered_low_reviews >= 1 ? { strength: Math.min(3, f.unanswered_low_reviews), evidence: { count: f.unanswered_low_reviews, of: f.n_reviews_fetched } } : null;
    case 'dormant_activity':
      return f.activity_label === 'dormant' ? { strength: 3, evidence: { days: f.days_since_last_review, last: f.last_review_at } }
        : f.activity_label === 'slowing' ? { strength: 1, evidence: { days: f.days_since_last_review, last: f.last_review_at } } : null;
    case 'declining_rating':
      return f.n_reviews_fetched >= 5 && f.rating_delta != null && f.rating_delta <= -0.3
        ? { strength: f.rating_delta <= -0.6 ? 3 : 2, evidence: { recent: f.recent_avg_rating, overall: f.overall_rating } } : null;
    case 'low_owner_engagement':
      return f.n_reviews_fetched >= 5 && f.owner_reply_rate != null && f.owner_reply_rate < 0.2
        ? { strength: f.owner_reply_rate === 0 && f.n_reviews_fetched >= 8 ? 3 : 2, evidence: { rate: f.owner_reply_rate, of: f.n_reviews_fetched } } : null;
    case 'new_business':
      return f.is_new_business === true ? { strength: 2, evidence: { reviews: f.total_reviews } } : null;
    case 'multi_branch':
      return f.branches >= 2 ? { strength: Math.min(3, f.branches), evidence: { branches: f.branches } } : null;
    case 'weak_search_rank':
      // Rank of the place inside the Maps result list of its search: the lower it appears, the less customers find it.
      return f.search_rank != null && f.search_rank >= 5 ? { strength: f.search_rank >= 10 ? 3 : f.search_rank >= 7 ? 2 : 1, evidence: { rank: f.search_rank } } : null;
    case 'review_theme': {
      // Complaint themes become an opportunity ONLY when the analysis says this offer can help, and confidence is not low.
      if (!analysis || analysis.confidence === 'low') return null;
      const hit = (analysis.complaints || []).filter((c) => c && c.offer_can_help).sort((a, b) => (b.count || 0) - (a.count || 0))[0];
      return hit ? { strength: Math.min(3, Math.max(1, hit.count || 1)), evidence: { theme: hit.theme, count: hit.count || 1 } } : null;
    }
    default:
      return null;
  }
}

/**
 * Top opportunities for one lead in one campaign.
 * @param {any} facts
 * @param {any} analysis review analysis (may be null)
 * @param {{type:string, angle:string}[]} oppMap campaign opportunity map, in the planner's priority order
 */
function buildOpportunities(facts, analysis, oppMap, max = 3) {
  const out = [];
  (oppMap || []).forEach((m, idx) => {
    if (!m || !OPPORTUNITY_TYPES.includes(m.type)) return;
    const e = evalOpportunity(m.type, facts, analysis);
    if (e) out.push({ type: m.type, strength: e.strength, evidence: e.evidence, angle: String(m.angle || '').slice(0, 200), _p: idx });
  });
  out.sort((a, b) => b.strength - a.strength || a._p - b._p);
  return out.slice(0, max).map((o) => ({ type: o.type, strength: o.strength, evidence: o.evidence, angle: o.angle }));
}

// ───────────────────────── score (spec 6.3a) ─────────────────────────
// Mirrors public.recompute_campaign_scores in SQL (same constants). Signed weights: w>0 rewards the HIGH state, w<0 the LOW state.
const SCORE = {
  favorable: 0.66, // a signal counts as "above zero" for the two-signal rule when its favorable state is this strong
  noBaseCap: 69, // fewer than two relevant non-baseline signals => score cannot exceed 69 (never "high" alone)
  maybeCap: 60,
  reasonMinWeight: 15, // a reason is shown only if its signal weighs MORE than this in the campaign (unless nothing stronger exists)
  baselineMaxWeight: 25, // baseline facts (e.g. has a website) are clamped unless the planner marked the signal as emphasized
};

/**
 * @param {{fit?:'fit'|'maybe'|'not_fit'|null, signals:{key:string, weight:number, value:number, baseline?:boolean, emphasis?:boolean}[]}} x
 * @returns {{score:number|null, relevant:number, capped_by:string|null, favorable:{key:string, side:'high'|'low', contribution:number}[]}}
 */
function scoreLead({ fit, signals }) {
  if (fit === 'not_fit') return { score: null, relevant: 0, capped_by: 'not_fit', favorable: [] };
  let sum = 0;
  let den = 0;
  let relevant = 0;
  const favorable = [];
  for (const s of signals) {
    let w = Number(s.weight);
    if (!w) continue;
    if (s.baseline && !s.emphasis) w = Math.sign(w) * Math.min(Math.abs(w), SCORE.baselineMaxWeight);
    const v = clamp01(Number(s.value));
    const c = w * v - Math.min(w, 0);
    sum += c;
    den += Math.abs(w);
    const fav = (w > 0 && v >= SCORE.favorable) || (w < 0 && v <= 1 - SCORE.favorable);
    if (fav) {
      favorable.push({ key: s.key, side: w > 0 ? 'high' : 'low', contribution: c, weight: Math.abs(Number(s.weight)) });
      if (!s.baseline || s.emphasis) relevant++;
    }
  }
  if (!den) return { score: null, relevant, capped_by: null, favorable };
  let score = Math.round((100 * sum) / den);
  let capped_by = null;
  if (relevant < 2 && score > SCORE.noBaseCap) { score = SCORE.noBaseCap; capped_by = 'needs_two_signals'; }
  if (fit === 'maybe' && score > SCORE.maybeCap) { score = SCORE.maybeCap; capped_by = 'maybe_fit'; }
  favorable.sort((a, b) => b.contribution - a.contribution);
  // Reasons from a signal weighing 15 or less in the campaign say little ("has a website"): hidden unless nothing stronger exists (mirrors the SQL).
  const strong = favorable.filter((f) => f.weight > SCORE.reasonMinWeight);
  return { score, relevant, capped_by, favorable: strong.length ? strong : favorable };
}

// ───────────────────────── message tact (spec 6.3b step 5) ─────────────────────────
// Safety net on top of the prompt: the first message never mentions complaints, low ratings or any weakness of the lead.
const NEGATIVE_AR = ['شكوي', 'شكاوي', 'شكوه', 'شتك', 'مشكله', 'مشاكل', 'سيء', 'سيئ', 'وحش', 'ضعيف', 'ضعف', 'تاخير', 'متاخر', 'اهمال', 'مهمل', 'قصور', 'فشل', 'بطيء', 'بطئ', 'غير راضي', 'مش راضي', 'تقييم سيء', 'تقييم منخفض', 'تقييم قليل', 'تقييمات منخفضه', 'تقييمات سلبيه', 'سلبي', 'نجمه واحده', 'نجمتين', 'ريفيوهات وحشه', 'عيب', 'عيوب', 'نقطه ضعف', 'نقاط ضعف', 'مفيش رد', 'بدون رد', 'مرددتوش', 'ما ردتوش', 'مردتوش', 'مش بتردو', 'مبتردوش'];
const NEGATIVE_EN = ['complain', 'bad review', 'low rating', 'poor rating', 'negative', 'weakness', 'problem with', 'unanswered'];

// Unsupported first-person claims about the lead (the sender has not seen their work): hearsay, own opinions, visits.
const CLAIMS_AR = ['سمعت', 'سمعنا', 'عاجبني', 'عجبني', 'عاجبنا', 'عجبنا', 'شايف ان شغل', 'شايف انكم', 'متابع شغل', 'تابعت', 'زرت', 'جربت', 'اتعاملت معاكم', 'شغلكم رائع', 'شغلكم ممتاز', 'شغلكم حلو', 'شغلكم تحفه', 'بتعملوا شغل رائع', 'بتقدموا شغل حلو', 'من افضل'];

/** @returns {{ok:boolean, reasons:string[]}} */
function checkTact(message, complaints = []) {
  const m = norm(message);
  const reasons = [];
  for (const w of NEGATIVE_AR.concat(NEGATIVE_EN)) if (m.includes(norm(w))) reasons.push(`word:${w}`);
  for (const w of CLAIMS_AR) if (m.includes(norm(w))) reasons.push(`claim:${w}`);
  // "your rating/reviews are low/bad" in any phrasing
  if (/(تقييم|ريفيو|نجوم|rating|review)\S*\s+(\S+\s+){0,2}(منخفض|قليل|ضعيف|سلبي|وحش|سيء|واطي|low|poor|bad)/.test(m)) reasons.push('rating_negative');
  for (const c of complaints || []) {
    const theme = typeof c === 'string' ? c : c && c.theme;
    for (const tok of norm(theme).split(' ')) if (tok.length >= 5 && m.includes(tok)) reasons.push(`theme:${tok}`);
  }
  return { ok: reasons.length === 0, reasons: [...new Set(reasons)] };
}


// ───────────────────────── message style rules (round 2) ─────────────────────────
// When the seller's product writes messages, the first message IS the demo: it must not read like a template. These are the
// checks that can be made in code; the prompt carries the rest. Nothing here depends on an industry or an offer.
const RATING_WORDS = ['تقييم', 'تقيم', 'نجمه', 'نجوم', 'ريفيو', 'rating', 'star', 'review'];
const JARGON_RE = /(^|[^a-z])(b2b|b2c|leads?|outreach|pipeline|crm|roi|kpi|funnel)([^a-z]|$)/i;
const JARGON_AR = ['بي تو بي', 'ليدز', 'ليد '];
const DAYTIME_AR = ['صباح', 'مساء'];
const WEAK_CTA = ['ممكن نتكلم', 'نتكلم اكتر', 'نتناقش', 'ممكن نتحدث', 'ممكن نتواصل', 'نتواصل معاكم'];
// Generic benefit phrases the writer likes to invent; allowed only if the seller's own offer text says so.
const BENEFIT_FLUFF = ['رضا العملاء', 'رضاهم', 'رضاكم', 'تعزيز التواصل', 'تقويه التواصل', 'يقوي التواصل', 'تحسين تجربه', 'يزود رضا', 'زياده رضا', 'جوده العمل', 'تركزوا علي شغلكم', 'تركز علي شغلها', 'تركزوا في شغلكم', 'شغلكم الاساسي', 'شغلها الاساسي', 'توفرو وقتكم', 'توفر وقتكم', 'تقلقوا', 'تقلق '];
// The sender has not seen their work: no own praise, and a first message promises no guarantee.
// Praise words are allowed only when the message attributes them to the customers ("عملاءكم بيشكروا في ..."); the sender's own praise is rejected.
const PRAISE_AR = ['مميز', 'ممتاز', 'رائع', 'شاطر', 'عظيم', 'متميز', 'تميز', 'احتراف', 'محترف', 'مختلف', 'متطور', 'ابداع', 'مبدع', 'خبره عاليه', 'باين عليكم', 'باين ان'];
const ATTRIBUTION = ['عملاءكم', 'عملاؤكم', 'عملائكم', 'بيشكروا', 'بيتكلموا', 'بيمدحوا', 'بيقولوا', 'بيحبوا'];
// Claims about the lead's own needs: "شغلكم ... بيحتاج/محتاج ...", "أكيد ...". Needs of the companies we would bring them ("شركات محتاجة خدماتكم") are fine.
const ASSUMES = /((^| )(اكيد|واضح انكم|باين انكم|واضح ان|باين ان)( |$))|(((انتم|انكم|بيخليكم)( \S+){0,2}|(^| )(شغلكم|نشاطكم|مجالكم|عملكم|خدمتكم|تخصصكم|شركتكم|وكالتكم)( \S+){0,6}) (بيحتاج|بتحتاج|يحتاج|محتاج|محتاجه|محتاجين|بيتطلب|بتتطلب)( |$))/;
// "always" is an overclaim about their customers or their work.
const OVERCLAIM_AR = ['دايما', 'دائما', 'طول الوقت', 'كل الناس'];
const GUARANTEE_AR = ['نضمن', 'بنضمن', 'هنضمن', 'مضمون', 'ضمان', 'guarantee'];
const STOP = new Set(['من', 'في', 'علي', 'عن', 'الي', 'مع', 'ده', 'دي', 'كده', 'لو', 'او', 'ان', 'انت', 'انتم', 'احنا', 'هو', 'هي']);

const wordList = (s) => String(s || '').trim().split(/\s+/).filter(Boolean);
const contentTokens = (s) => catTokens(s).filter((t) => t.length >= 2 && !STOP.has(t));

/**
 * Does the message copy a run of `n` or more consecutive words from one of the organization's style examples? Runs that also occur in the
 * seller's own offer text (its description and its call to action) are allowed: those words come from the offer, not from the example.
 */
function copiedRun(message, examples, allowedText = '', n = 8) {
  const toks = (t) => norm(t).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter(Boolean);
  const grams = (arr) => { const out = []; for (let i = 0; i + n <= arr.length; i++) out.push(arr.slice(i, i + n).join(' ')); return out; };
  const allowed = new Set(grams(toks(allowedText)));
  const mine = grams(toks(message)).filter((g) => !allowed.has(g));
  if (!mine.length) return false;
  const theirs = new Set((examples || []).flatMap((e) => grams(toks(e))));
  return mine.some((g) => theirs.has(g));
}

/** First five words of a message (normalized): two messages of one campaign must not share them. */
function openingKey(message) {
  return norm(message).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter(Boolean).slice(0, 5).join(' ');
}

/** Word-set overlap (Jaccard, 0..1) of two messages: two messages of one campaign above SIMILAR_LIMIT read like the same template. */
const SIMILAR_LIMIT = 0.6;
function messageSimilarity(a, b) {
  const t = (s) => new Set(norm(s).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter((w) => w.length > 2));
  const x = t(a);
  const y = t(b);
  const inter = [...x].filter((w) => y.has(w)).length;
  const uni = new Set([...x, ...y]).size;
  return uni ? inter / uni : 0;
}

/** Does the quoted phrase come from the seller's offer text? Exact (normalized) match, or at least 85% of its words, for 3+ words. */
function quoteInOffer(quote, offerText) {
  const q = norm(quote).replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\s+/g, ' ').trim();
  const o = norm(offerText).replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\s+/g, ' ').trim();
  if (q.split(' ').length < 3 || !o) return false;
  if (o.includes(q)) return true;
  const have = new Set(catTokens(o));
  const qt = catTokens(q);
  return qt.length >= 3 && qt.filter((t) => have.has(t)).length / qt.length >= 0.85;
}

/**
 * Style and honesty checks on one first message.
 * @param {string} message
 * @param {{channel?:string, areas?:string[], city?:string|null, offerText?:string, offerQuote?:string|null, ctaOffer?:string|null, senderName?:string|null}} ctx
 * @returns {{ok:boolean, reasons:string[]}}
 */
function checkMessage(message, ctx = {}) {
  const m = norm(message);
  const reasons = [];
  const chat = ctx.channel !== 'email';
  const n = wordList(message).length;
  if (chat && (n < 35 || n > 70)) reasons.push(`word_count_${n}`);
  for (const w of RATING_WORDS) if (m.includes(norm(w))) { reasons.push('mentions_rating'); break; }
  if (/[⭐★☆]/.test(message)) reasons.push('mentions_rating');
  if (JARGON_RE.test(m) || JARGON_AR.some((w) => m.includes(norm(w)))) reasons.push('jargon');
  if (DAYTIME_AR.some((w) => new RegExp(`(^| )${norm(w)}`).test(m)) || /good (morning|evening|afternoon)/.test(m)) reasons.push('time_greeting');
  // micro-districts: the lead's own district / neighborhood names are never used; the city (at most) is fine
  const city = norm(ctx.city || '');
  for (const a of ctx.areas || []) {
    const t = norm(a);
    if (t.length >= 3 && t !== city && !(city && city.includes(t)) && m.includes(t)) { reasons.push(`micro_district:${a}`); break; }
  }
  if (/(المنطقه|الحي|حي) (ال)?(اولي|ثانيه|ثالثه|رابعه|خامسه|سادسه|سابعه|ثامنه|تاسعه|عاشره|اول|ثاني|ثالث|رابع|خامس|سادس|سابع|ثامن|تاسع|عاشر)/.test(m)) reasons.push('micro_district:ordinal');
  if (WEAK_CTA.some((w) => m.includes(norm(w)))) reasons.push('weak_cta');
  {
    const ws = m.split(/\s+/);
    const own = ws.some((w, i) => PRAISE_AR.some((p) => w.includes(norm(p))) && !ws.slice(Math.max(0, i - 7), i).some((b) => ATTRIBUTION.some((a) => b.includes(norm(a)))));
    if (own) reasons.push('own_praise');
    if (ASSUMES.test(m)) reasons.push('assumes_need');
    if (OVERCLAIM_AR.some((w) => new RegExp(`(^| )${norm(w)}( |$)`).test(m))) reasons.push('overclaim_always');
  }
  if (GUARANTEE_AR.some((w) => m.includes(norm(w)))) reasons.push('guarantee');
  const offerN = norm(ctx.offerText || '');
  for (const f of BENEFIT_FLUFF) if (m.includes(norm(f)) && !offerN.includes(norm(f))) { reasons.push(`invented_benefit:${f}`); break; }
  if (ctx.offerText) {
    if (!ctx.offerQuote) reasons.push('offer_quote_missing');
    else if (!quoteInOffer(ctx.offerQuote, ctx.offerText)) reasons.push('offer_quote_not_in_offer');
  }
  if (ctx.ctaOffer) {
    const have = new Set(contentTokens(message));
    const hit = contentTokens(ctx.ctaOffer).filter((t) => have.has(t)).length;
    if (hit < 2) reasons.push('cta_offer_missing');
  }
  if (ctx.senderName && chat) {
    const tail = m.slice(-60);
    if (!tail.includes(norm(ctx.senderName))) reasons.push('missing_signature');
    // the sender's name appears once, in the signature at the end (never also as an introduction at the start)
    if (m.split(norm(ctx.senderName)).length - 1 > 1) reasons.push('double_signature');
  }
  if ((ctx.styleExamples || []).length && copiedRun(message, ctx.styleExamples, ctx.offerText || ctx.ctaOffer || '')) reasons.push('copies_style_example');
  return { ok: reasons.length === 0, reasons: [...new Set(reasons)] };
}

const REASON_HELP = {
  own_praise: 'you praised their work yourself (praise is allowed only as what their customers say)',
  assumes_need: 'you claimed something about what the lead itself needs',
  copies_style_example: 'you copied 8 or more consecutive words from a style example: write your own sentences',
  double_signature: 'the sender name appears more than once: it belongs only in the signature at the end',
  overclaim_always: 'you used "always" (دايما / دائما)',
  mentions_rating: 'you mentioned the rating, stars or reviews',
  jargon: 'you used jargon (B2B, leads...)',
  time_greeting: 'you used a time-of-day greeting',
  weak_cta: 'the ending was a weak "can we talk" question',
  guarantee: 'you promised or guaranteed something',
  invented_benefit: 'you promised a benefit that is not in the offer',
  offer_quote_missing: 'offer_quote was missing',
  offer_quote_not_in_offer: 'offer_quote was not copied word for word from sender_offer',
  cta_offer_missing: 'the concrete cta_offer was not in the ending',
  missing_signature: 'the signature was missing at the end',
  duplicate_opening: 'the opening is the same as another message',
  too_similar_to_another_message: 'the text is too close to another message',
  too_similar: 'the text is too close to another message',
};
function explainReason(reason) {
  const parts = String(reason).replace(/^style:/, '').split(/[,:]/).map((x) => x.trim()).filter(Boolean);
  const out = [];
  for (const p of parts) {
    if (REASON_HELP[p]) out.push(REASON_HELP[p]);
    else if (/^word_count_(\d+)$/.test(p)) out.push(`the text had ${p.slice(11)} words (it must be 35 to 70)`);
    else if (p === 'tact') out.push('you mentioned something negative (a problem, complaint or weakness) about the business or used a word like "problem"');
    else if (p === 'micro_district') out.push('you named a district or neighborhood');
  }
  return [...new Set(out)];
}

/** The single automatic retry of a rejected first message: same request plus the rejected reply and the reason as feedback. */
function retryRequestBody(requestBody, raw, reason) {
  const req = JSON.parse(requestBody);
  req.messages = [...req.messages, { role: 'assistant', content: raw || '{}' }, { role: 'user', content: `Your reply was rejected (${reason}). Rewrite it and return the JSON again. Remember: 35 to 70 words, no rating or stars or reviews, no district or neighborhood names, no jargon (no B2B), no time-of-day greeting, no "ممكن نتكلم", no praise of their work, no guarantees, no "focus on your core work" lines, address them as a team in the plural, end with the concrete offer (cta_offer) worded differently from the usual and the signature, offer_quote must be copied word for word from sender_offer, never invent benefits, never mention complaints or weaknesses, start differently from avoid_openings and use different sentences from the other messages of this campaign.` }];
  const why = explainReason(reason);
  if (why.length) req.messages[req.messages.length - 1].content += ` Specifically: ${why.join('; ')}.`;
  const wc = /word_count_(\d+)/.exec(String(reason));
  if (wc) req.messages[req.messages.length - 1].content += ` The text had ${wc[1]} words. Write between 45 and 60 words: ${Number(wc[1]) < 35 ? 'add one more concrete sentence about what the offer does (use the wording of offer_quote)' : 'cut the weakest sentence'}.`;
  req.temperature = 0.5;
  return JSON.stringify(req);
}

// ───────────────────────── LLM helpers (OpenRouter request/response) ─────────────────────────
/** OpenRouter chat request body (string). `fallback` = fallback model ids tried on provider failure. */
function llmRequest({ system, user, model, fallback = [], temperature = 0, extraMessages = [] }) {
  const req = {
    messages: [{ role: 'system', content: system }, { role: 'user', content: typeof user === 'string' ? user : JSON.stringify(user) }, ...extraMessages],
    response_format: { type: 'json_object' },
    temperature,
    usage: { include: true },
  };
  const fb = (fallback || []).filter(Boolean);
  if (fb.length) req.models = [model, ...fb]; else req.model = model;
  return JSON.stringify(req);
}

/** Parse an OpenRouter full-response item. @returns {{data:any|null, usage:{in:number,out:number,cost:number,model:string|null}, status:number|null}} */
function parseLlm(res) {
  const r = res || {};
  const u = (r.body && r.body.usage) || {};
  const usage = { in: u.prompt_tokens || 0, out: u.completion_tokens || 0, cost: Number(u.cost) || 0, model: (r.body && r.body.model) || null };
  let data = null;
  if (r.statusCode >= 200 && r.statusCode < 300 && r.body && r.body.choices) {
    try { data = JSON.parse((r.body.choices[0]?.message?.content || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch { data = null; }
  }
  return { data, usage, status: typeof r.statusCode === 'number' ? r.statusCode : null };
}

/** System prompt of the fit check (spec 6.0 step 3 and 4). Offer-agnostic: the ideal prospect text is the only criterion. */
function fitSystemPrompt({ ideal, offerText, negatives = [] }) {
  return `You judge whether Google Maps places are potential CUSTOMERS (prospects) for a seller.
Ideal prospect: ${ideal || '(not stated; judge from the seller offer)'}
Seller offer: ${String(offerText || '').slice(0, 500)}
For each place decide: "fit" (clearly the kind of business described), "maybe" (possibly, adjacent or unclear), "not_fit" (a different kind of business even if its NAME contains similar words, a public or government body, a competitor of the seller, or unrelated).
EVIDENCE RULES:
- Judge ONLY from the place's categories, its description and its website address. The business NAME is context only: words inside a name (including words that also appear in the ideal prospect text or the seller offer) are NOT evidence of what the business does or sells.
- When a word naming an industry, a product or a customer group sits next to the word that names the kind of business (in the name or in a category), it says what the business SELLS or serves, so the business belongs to THAT sector: answer "not_fit" (not "maybe"), unless the ideal prospect text itself asks for that sector.
- Return "evidence": the source that supports your label, one of "category", "description", "website", "name_only" (nothing but the name supports it) or "none". Use "fit" only when the evidence is category, description or website.
Give a SHORT reason (max 12 words, in the same language as the ideal prospect text).${negatives.length ? `\nThe seller already rejected businesses like these (treat similar ones as not_fit):\n${negatives.slice(0, 15).map((n) => `- ${n.business_name || ''} (${n.category || ''}): ${n.reason || ''}`).join('\n')}` : ''}
Return ONE JSON object only: {"results":[{"i": number, "fit": "fit"|"maybe"|"not_fit", "evidence": "category"|"description"|"website"|"name_only"|"none", "reason": string}]} covering every i.`;
}

const hostOf = (u) => { try { return new URL(/^[a-z]+:\/\//i.test(u) ? u : `https://${u}`).hostname.replace(/^www\./, '').toLowerCase(); } catch { return ''; } };

/** Social and messaging pages people use instead of a website. A business that only has one of these has no real website. */
const SOCIAL_HOSTS = ['facebook.com', 'fb.com', 'fb.me', 'instagram.com', 'linktr.ee', 'beacons.ai', 'tiktok.com', 'twitter.com', 'x.com', 'linkedin.com', 'wa.me', 'whatsapp.com', 'youtube.com', 'youtu.be', 't.me', 'behance.net'];
function isSocialUrl(u) {
  const h = hostOf(String(u || ''));
  return !!h && SOCIAL_HOSTS.some((s) => h === s || h.endsWith(`.${s}`));
}

/** The compact description of one place sent to the fit check: categories, description and website address are evidence; the name is context. */
function fitAsk(rawPlace, area) {
  const cats = [rawPlace.categoryName, ...(Array.isArray(rawPlace.categories) ? rawPlace.categories : [])].filter(Boolean);
  const desc = stripInvisible(rawPlace.description || rawPlace.ownerDescription || rawPlace.subTitle || '').slice(0, 240);
  return {
    name: stripInvisible(rawPlace.title), categories: [...new Set(cats)].slice(0, 8), description: desc || null,
    website: rawPlace.website ? hostOf(String(rawPlace.website)) || 'yes' : 'no', area: area || '', rating: rawPlace.totalScore ?? null, reviews: rawPlace.reviewsCount ?? null,
  };
}

/**
 * Keep or remove one place after the fit check (spec 6.0 step 4, round 2 fixes).
 * Inside the allowed categories: fit or maybe is kept (the category itself is evidence), not_fit removed.
 * Outside them: kept ONLY when the check said "fit" with evidence from the categories, description or website; never from the name,
 * never for "maybe". Nothing is learned from the model: a category joins the allowed list only through a user action.
 * @returns {{keep:boolean, fit?:'fit'|'maybe', why?:string}}
 */
function decideFit({ label, inside }) {
  const l = label || { fit: 'maybe', reason: 'unchecked' };
  if (l.fit === 'not_fit') return { keep: false, why: 'not_fit' };
  const ev = l.evidence;
  const real = ev === 'category' || ev === 'description' || ev === 'website';
  if (inside) return { keep: true, fit: l.fit === 'fit' && ev !== 'name_only' ? 'fit' : 'maybe' };
  if (l.fit === 'fit' && real) return { keep: true, fit: 'fit' };
  return { keep: false, why: l.fit === 'fit' ? 'name_only_evidence' : 'outside_categories' };
}

// ───────────────────────── search rounds (spec 6.2) ─────────────────────────
/** Search area of a location: the most specific name and a clean geocoder string (no repeated parts, no hidden characters). */
function areaOf(l) {
  // Unique parts; a part already contained in a more specific one is dropped ("القاهرة" inside "التجمع الخامس القاهرة").
  const parts = [cleanPlace(l.district), cleanPlace(l.city), cleanPlace(l.governorate)].filter(Boolean);
  const kept = parts.filter((p, i) => !parts.some((q, j) => j !== i && norm(q) !== norm(p) && norm(q).includes(norm(p))) && parts.findIndex((q) => norm(q) === norm(p)) === i);
  return { area: cleanPlace(l.district || l.city || l.governorate || ''), locationQuery: kept.concat('Egypt').join(', ') };
}

/**
 * Plan the Apify searches for a round. Rounds: 1 base queries at real depth; 2 same queries deeper (only the ones that hit
 * their cap); 3 synonyms; 4 nearby districts; 5 broad fallback (city level, simplest keyword) used for zero results.
 * @returns {{round:number, searches:{query:string, area:string, locationQuery:string, depth:number}[]}|null} null = exhausted
 */
function planRound({ round, target, keywords, synonyms = [], locations, nearby = [], done = [], saturated = [], avoid = [], minDepth = 20, maxDepth = 120 }) {
  const doneSet = new Set(done.map((d) => norm(d)));
  const loc = areaOf;
  const mk = (kws, locs, depthMul = 1) => {
    const base = Math.min(maxDepth, Math.max(minDepth, Math.ceil((target * 2.5) / Math.max(1, kws.length * locs.length))));
    const depth = Math.min(maxDepth, Math.ceil(base * depthMul));
    const s = [];
    for (const l of locs) {
      const { area, locationQuery } = loc(l);
      for (const k of kws) {
        const query = `${cleanPlace(k)} ${area}`.trim();
        s.push({ query, area, locationQuery, depth, key: norm(`${depthMul}|${query}`) });
      }
    }
    return s;
  };
  let searches = [];
  if (round === 1) searches = mk(keywords, locations);
  else if (round === 2) {
    const sat = new Set(saturated.map(norm));
    searches = mk(keywords, locations, 2.5).filter((s) => sat.has(norm(s.query)));
  } else if (round === 3) searches = mk(synonyms, locations);
  else if (round === 4) searches = mk(keywords.concat(synonyms).slice(0, 4), nearby);
  else if (round === 5) {
    // Broad fallback: simplest keyword, city level (or governorate), no district polygon.
    const broad = locations.map((l) => ({ governorate: l.governorate, city: l.city || l.governorate, district: '' }));
    searches = mk(keywords.slice(0, 2), broad.length ? broad : locations);
  } else return null;
  // `avoid` = searches this organization already ran in earlier campaigns: the same companies would come back, so prefer new ones.
  const avoidSet = new Set(avoid.map(norm));
  searches = searches.filter((s) => s.query && !doneSet.has(norm(s.query) + '|' + round) && !avoidSet.has(norm(s.query)));
  return searches.length ? { round, searches } : null;
}

/**
 * After a round: which round next (null = stop). Normal order 1..5; if round 1 found no places at all the engine jumps to the
 * broad fallback first (city level, simplest keywords), then synonyms and nearby districts.
 * @returns {{next:number|null, mode:'normal'|'zero'}}
 */
function decideNext({ round, mode = 'normal', delivered, target, rawTotal }) {
  if (delivered >= target) return { next: null, mode };
  if (round === 1 && rawTotal === 0) return { next: 5, mode: 'zero' };
  if (mode === 'zero') return { next: round === 5 ? 3 : round === 3 ? 4 : null, mode };
  return { next: round < 5 ? round + 1 : null, mode };
}

/** Why a campaign delivered nothing (plain code, mapped to a user message with concrete suggestions in the UI). */
function emptyReason(f) {
  if (!f.raw_places) return 'no_places';
  if (f.removed_not_fit >= (f.raw_places - f.removed_category - f.removed_global - f.removed_closed) && f.removed_not_fit > 0) return 'all_not_fit';
  if (f.removed_category + f.removed_global >= f.raw_places * 0.8) return 'all_category';
  if (f.previously_found > 0 && f.previously_found >= f.raw_places * 0.5) return 'all_previously_found';
  if (f.cooldown > 0 && f.cooldown >= f.raw_places * 0.5) return 'all_cooldown';
  return 'all_filtered';
}

/** Funnel keys shown on the campaign page, in order (spec 6.2). */
const FUNNEL_KEYS = ['queries', 'raw_places', 'removed_category', 'removed_global', 'removed_closed', 'removed_landline', 'removed_filters', 'removed_not_fit', 'duplicates', 'previously_found', 'opted_out', 'cooldown', 'delivered'];

const meta = $('Select and build').item.json;
const res = $input.item.json;
const attempt = $prevNode.name === 'OpenRouter retry' ? 2 : 1;
const first = attempt === 2 ? $('Validate message').item.json : null;

const base = { lead_id: meta.lead_id, message_id: meta.message_id, regen_count: meta.regen_count, channel: meta.channel,
  organization_id: meta.organization_id, campaign_id: meta.campaign_id, job_id: meta.job_id, total: meta.total };
const body = res && res.body;
const u = (body && body.usage) || {};
const prevU = first || { tokens_in: 0, tokens_out: 0, cost: 0 };
const usage = { tokens_in: (u.prompt_tokens || 0) + prevU.tokens_in, tokens_out: (u.completion_tokens || 0) + prevU.tokens_out,
  cost: (Number(u.cost) || 0) + prevU.cost, model: (body && body.model) || (first && first.model) || null };
// Save instruction for the single "Save message" HTTP node: invalid items become a harmless no-op PATCH (matches no row).
// A final failure is stored as a visible 'failed' row (no text, never charged) so the review queue can show it with a regenerate button.
const failSave = (reason) => (meta.message_id
  ? { method: 'PATCH', path: `messages?id=eq.${meta.message_id}&review_status=neq.sent`, prefer: 'return=minimal', body: { review_status: 'failed', fail_reason: String(reason).slice(0, 120), job_id: meta.job_id } }
  : { method: 'POST', path: 'messages?on_conflict=lead_id,campaign_id,channel', prefer: 'resolution=ignore-duplicates,return=minimal',
      body: { organization_id: meta.organization_id, lead_id: meta.lead_id, campaign_id: meta.campaign_id, job_id: meta.job_id, channel: meta.channel, generated_text: '', review_status: 'failed', fail_reason: String(reason).slice(0, 120) } });

// A failed first attempt is retried ONCE with the reasons as feedback; a failed retry is final.
const bad = (reason, raw) => {
  const retryable = attempt === 1 && !/^http_/.test(reason);
  let retryBody = '{}';
  if (retryable) retryBody = retryRequestBody(meta.requestBody, raw, reason);
  return { json: { ...base, ...usage, ok: false, reason, retry: retryable, requestBody: retryBody, save: failSave(reason) } };
};

if (!res || res.statusCode < 200 || res.statusCode >= 300 || !body || !body.choices) return bad(`http_${res && res.statusCode}`);
const content = body.choices[0]?.message?.content || '';
let d;
try { d = JSON.parse(content.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { return bad('bad_json', content); }
let message = typeof d.message === 'string' ? d.message.trim() : '';
if (!message) return bad('empty', content);

const words = message.split(/\s+/).filter(Boolean).length;
const chat = meta.channel !== 'email';
if (!chat && (words < 50 || words > 150)) return bad(`word_count_${words}`, content);
if (chat && /https?:|www\.|\.com\b|\.net\b|\.eg\b|wa\.me/i.test(message)) return bad('contains_link', content);
// The signature is a fixed string: when the model leaves it out we add it (everything else still has to pass).
if (chat && meta.signature && meta.sender_name && !norm(message.slice(-60)).includes(norm(meta.sender_name))) message = `${message} ${meta.signature}`;
// Tact: no complaints, low ratings or weaknesses in the first message (this lead's own complaint themes are checked too).
const tact = checkTact(message, meta.complaints || []);
if (!tact.ok) return bad(`tact:${tact.reasons.slice(0, 3).join(',')}`, content);
// Style and honesty rules (round 2): no rating, micro-district, jargon or time greeting; benefits only from the offer; a concrete call to action; a signature.
const style = checkMessage(message, { channel: meta.channel, areas: meta.areas, city: meta.city, offerText: meta.offer_text, offerQuote: typeof d.offer_quote === 'string' ? d.offer_quote : null, ctaOffer: meta.cta_offer, senderName: meta.sender_name, styleExamples: meta.style_examples });
if (!style.ok) return bad(`style:${style.reasons.slice(0, 3).join(',')}`, content);
// The opening (first five words) must differ from every earlier message of the campaign.
const opening = openingKey(message);
if (opening && (meta.used_openings || []).includes(opening)) return bad('duplicate_opening', content);
if (attempt === 2 && opening) {
  // The retry is final, so it also has to differ from the openings already accepted in this run (kept by "Dedupe openings").
  const sd = $getWorkflowStaticData('global');
  const seenNow = sd[`open_${meta.job_id}`] || [];
  const textsNow = sd[`open_${meta.job_id}_t`] || [];
  if (seenNow.includes(opening) || textsNow.some((t) => messageSimilarity(t, message) >= SIMILAR_LIMIT)) return bad('duplicate_opening', content);
  sd[`open_${meta.job_id}`] = [...seenNow, opening];
  sd[`open_${meta.job_id}_t`] = [...textsNow, message].slice(-60);
}
// At most ONE emoji (spec 6.4): keep the first, drop the rest instead of wasting the generation.
let seenEmoji = 0;
message = message.replace(/\p{Extended_Pictographic}️?/gu, (m) => (seenEmoji++ === 0 ? m : '')).replace(/[ \t]{2,}/g, ' ').trim();

const angle = typeof d.angle === 'string' ? d.angle.trim().slice(0, 120) : null;
const subject = typeof d.subject === 'string' ? d.subject.trim().slice(0, 100) : null;
const save = meta.message_id
  ? { method: 'PATCH', path: `messages?id=eq.${meta.message_id}&review_status=neq.sent`, prefer: 'return=minimal',
      body: { generated_text: message, edited_text: null, fail_reason: null, angle, subject, opportunity_type: meta.opportunity_type, review_status: 'pending', regen_count: meta.regen_count, llm_model: usage.model, job_id: meta.job_id } }
  : { method: 'POST', path: 'messages?on_conflict=lead_id,campaign_id,channel', prefer: 'resolution=ignore-duplicates,return=minimal',
      body: { organization_id: meta.organization_id, lead_id: meta.lead_id, campaign_id: meta.campaign_id, job_id: meta.job_id, channel: meta.channel,
        subject, generated_text: message, angle, opportunity_type: meta.opportunity_type, llm_model: usage.model } };
return { json: { ...base, ...usage, ok: true, retry: false, retried: attempt === 2, message, angle, subject, opening, save, raw_content: content } };

// WF3 "Dedupe openings": no two messages of one run may start with the same five words (round 2: the batch must not read like one template).
// The first message keeps its opening; a later duplicate is sent back for its single automatic retry with the reason as feedback.
// The accepted openings are kept in workflow static data per job, so the check also holds across the loop's batches.
// Lead insights core (spec 6.2, 6.3a, 6.3b). Plain ESM JS with no imports so the SAME source is inlined into n8n Code
// nodes (marker /*__INSIGHTS__*/) and used by unit tests and the fixture runner. Nothing here knows any industry,
// segment or offer: relevance always comes from the campaign (allowed categories, signal weights, opportunity map).

// ───────────────────────── text helpers ─────────────────────────
const INVISIBLE = new RegExp('[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]', 'g');
const DIACRITICS = new RegExp('[\u064B-\u065F\u0670\u0640]', 'g');

/** Lowercase, strip invisible/bidi marks and Arabic diacritics, unify alef/yaa/taa-marbuta, collapse spaces. */
function norm(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(INVISIBLE, '')
    .replace(DIACRITICS, '')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Invisible/bidi marks removed, whitespace collapsed. */
function stripInvisible(s) {
  return String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
}

/** Clean one location part for Apify: no invisible marks, no repeated words ("التجمع الخامس القاهرة القاهرة"). */
function cleanPlace(s) {
  const t = String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
  const out = [];
  for (const w of t.split(' ')) if (!out.length || norm(out[out.length - 1]) !== norm(w)) out.push(w);
  return out.join(' ');
}

// ───────────────────────── global exclusions (spec 6.3a) ─────────────────────────
// Always on, for every campaign. Matched against Google Maps CATEGORIES (Arabic and English), never against the name alone.
// Hospitals only for health: clinics, labs and pharmacies are legitimate prospects for many offers.
const GLOBAL_EXCLUSIONS = {
  government: ['مكتب حكومي', 'جهه حكوميه', 'هيئه حكوميه', 'مبني حكومي', 'وزاره', 'محافظه', 'مجلس مدينه', 'قسم شرطه', 'مركز شرطه', 'محكمه', 'نيابه', 'مصلحه', 'سجل مدني', 'government office', 'government organization', 'government agency', 'local government', 'city government', 'county government', 'municipality', 'ministry', 'police', 'courthouse', 'public administration'],
  utility: ['محطه كهرباء', 'محطه توليد', 'محطه مياه', 'محطه معالجه', 'محطه تحويل', 'محطه صرف', 'شركه كهرباء', 'شركه مياه', 'شركه غاز', 'سنترال', 'مرفق عام', 'power station', 'power plant', 'electric utility', 'electricity', 'water utility', 'water treatment', 'water works', 'sewage', 'telephone exchange', 'substation', 'gas utility', 'public utility'],
  education: ['جامعه', 'كليه', 'مدرسه', 'روضه اطفال', 'ثانويه', 'اعداديه', 'ابتدائيه', 'university', 'college', 'school', 'kindergarten', 'academy of', 'faculty'],
  health: ['مستشفي', 'hospital'],
  worship: ['مسجد', 'جامع', 'كنيسه', 'دير', 'معبد', 'مكان عباده', 'mosque', 'church', 'temple', 'synagogue', 'place of worship', 'cathedral', 'monastery'],
  embassy: ['سفاره', 'قنصليه', 'embassy', 'consulate'],
  military: ['موقع عسكري', 'قاعده عسكريه', 'معسكر', 'عسكري', 'military', 'army base', 'air force', 'naval'],
};

const hasEn = (p) => /^[a-z ]+$/.test(p);
const catMatches = (c, p) => (hasEn(p) ? new RegExp(`(^| )${p}( |$|s\\b)`).test(c) : c.includes(p));

/** @returns {{group:string, match:string, category:string}|null} */
function globalExclusion(categories) {
  for (const raw of categories || []) {
    const c = norm(raw);
    if (!c) continue;
    for (const [group, pats] of Object.entries(GLOBAL_EXCLUSIONS)) {
      for (const p of pats) if (catMatches(c, norm(p))) return { group, match: p, category: String(raw) };
    }
  }
  return null;
}

/** Brand part of a business name ("X - Nasr City" and "X (Maadi)" are the same brand), normalized. */
function brandKey(name) {
  return norm(String(name || '').split(/\s[-–|]\s|\(|\|/)[0]).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

/**
 * Branches of one business: listings of the organization with the same normalized brand name AND the same website or the same phone
 * (a Facebook/Instagram page is not a shared website). Name similarity alone never counts: it is what made unrelated places look like chains.
 * @param {{business_name?:string, website?:string, phone_e164?:string}} self
 * @param {{business_name?:string, website?:string, phone_e164?:string}[]} all every listing of the organization (the business itself included)
 */
function countBranches(self, all) {
  const key = brandKey(self.business_name);
  if (!key) return 1;
  const site = (u) => (u && !isSocialUrl(u) ? hostOf(String(u)) : '');
  const mySite = site(self.website);
  const myPhone = self.phone_e164 || '';
  let n = 0;
  for (const o of all || []) {
    if (brandKey(o.business_name) !== key) continue;
    if ((mySite && site(o.website) === mySite) || (myPhone && o.phone_e164 === myPhone)) n++;
  }
  return Math.max(1, n);
}

/** Light stemmer so "وكالات" matches "وكالة" and "Agencies" matches "agency" (no dictionary, no segment knowledge). */
function stemToken(raw) {
  let t = norm(raw);
  if (/^[a-z0-9]+$/.test(t)) {
    if (t.length > 4 && t.endsWith('ies')) return t.slice(0, -3) + 'y';
    if (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) return t.slice(0, -1);
    return t;
  }
  if (t.length > 4) t = t.replace(/^(وال|بال|لل|ال)/, '');
  if (t.length > 3) t = t.replace(/(ات|ون|ين|ان)$/, '');
  if (t.length > 3) t = t.replace(/ه$/, '');
  if (t.length > 3) t = t.replace(/ي$/, '');
  return t;
}
const catTokens = (s) => norm(s).split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(stemToken);

/**
 * Does any Maps category match the campaign's allowed categories (Arabic and English)? Done by us, never by the actor.
 * Singular/plural and the Arabic article are ignored. An allowed entry matches a place category when all its words occur in the
 * category, or the category is a (parent) subset of the entry. An empty allow-list means "no category restriction" (old campaigns).
 * @returns {{ok:boolean, matched:string|null}}
 */
function categoryMatch(placeCategories, allowed) {
  const list = (allowed || []).map((a) => ({ a, tokens: catTokens(a) })).filter((x) => x.tokens.length && norm(x.a).length >= 3);
  if (!list.length) return { ok: true, matched: null };
  for (const raw of placeCategories || []) {
    const c = catTokens(raw);
    if (!c.length) continue;
    const cs = new Set(c);
    for (const { a, tokens } of list) {
      const as = new Set(tokens);
      if (tokens.every((t) => cs.has(t))) return { ok: true, matched: a };
      if (c.every((t) => as.has(t)) && (c.length >= 2 || c[0].length >= 4)) return { ok: true, matched: a };
    }
  }
  return { ok: false, matched: null };
}

// ───────────────────────── deterministic facts (spec 6.3b step 1) ─────────────────────────
const DAY = 86400000;
const MONTH = 30.44 * DAY;
const r1 = (x) => Math.round(x * 10) / 10;

/**
 * @param {any} place raw Google Maps place (compass/crawler-google-places)
 * @param {any[]} reviews raw reviews for that place (compass/google-maps-reviews-scraper), newest first or any order
 * @param {{now?:number, branches?:number}} [opt]
 */
function computeFacts(place, reviews = [], opt = {}) {
  const now = opt.now ?? Date.now();
  const seen = new Set();
  const rev = [];
  for (const r of reviews || []) {
    if (!r) continue;
    const id = r.reviewId || `${r.publishedAtDate}|${r.stars}|${r.text}`;
    if (seen.has(id)) continue;
    seen.add(id);
    rev.push(r);
  }
  const dates = rev.map((r) => Date.parse(r.publishedAtDate)).filter(Number.isFinite).sort((a, b) => a - b);
  const n = rev.length;
  const total = Number(place.reviewsCount) || n;
  const overall = Number(place.totalScore) || null;
  const last = dates.length ? dates[dates.length - 1] : null;
  const oldest = dates.length ? dates[0] : null;
  const sinceLast = last == null ? null : (now - last) / DAY;
  const activity_label = last == null ? 'unknown' : sinceLast <= 90 ? 'active' : sinceLast <= 365 ? 'slowing' : 'dormant';
  const spanMonths = oldest == null ? null : Math.max(0.25, (now - oldest) / MONTH);
  const replies = rev.filter((r) => r.responseFromOwnerText && String(r.responseFromOwnerText).trim()).length;
  const low = rev.filter((r) => Number(r.stars) <= 2);
  const stars = rev.map((r) => Number(r.stars)).filter(Number.isFinite);
  const recent_avg = stars.length ? stars.reduce((a, b) => a + b, 0) / stars.length : null;
  const texts = rev.filter((r) => (r.text || r.textTranslated || '').toString().trim());
  const images = Number(place.imagesCount) || 0;
  return {
    n_reviews_fetched: n,
    n_texts: texts.length,
    total_reviews: total,
    overall_rating: overall,
    last_review_at: last == null ? null : new Date(last).toISOString(),
    days_since_last_review: sinceLast == null ? null : Math.round(sinceLast),
    reviews_per_month: spanMonths == null || n < 2 ? null : r1(n / spanMonths),
    activity_label,
    // Only claim "new" when the fetched window provably covers the whole history and it started within a year.
    is_new_business: oldest != null && now - oldest <= 365 * DAY && total <= n ? true : null,
    owner_reply_rate: n ? Math.round((replies / n) * 100) / 100 : null,
    low_reviews: low.length,
    unanswered_low_reviews: low.filter((r) => !(r.responseFromOwnerText && String(r.responseFromOwnerText).trim())).length,
    recent_avg_rating: recent_avg == null ? null : r1(recent_avg),
    rating_delta: recent_avg == null || overall == null ? null : r1(recent_avg - overall),
    unclaimed_listing: place.claimThisBusiness === true,
    images_count: images,
    has_hours: Array.isArray(place.openingHours) && place.openingHours.length > 0,
    has_description: !!(place.description || place.ownerDescription || place.subTitle),
    // A Facebook/Instagram/link page used as the "website" is not a real website.
    has_website: !!(place.website && String(place.website).trim()) && !isSocialUrl(place.website),
    website_social: !!(place.website && isSocialUrl(place.website)),
    search_rank: Number.isFinite(Number(place.rank)) && Number(place.rank) > 0 ? Number(place.rank) : null,
    categories: [...new Set([place.categoryName, ...(Array.isArray(place.categories) ? place.categories : [])].filter(Boolean))].slice(0, 8),
    low_star_share: (() => { const d = place.reviewsDistribution; if (!d) return null; const t = ['oneStar', 'twoStar', 'threeStar', 'fourStar', 'fiveStar'].reduce((x, k) => x + (Number(d[k]) || 0), 0); return t ? Math.round((((Number(d.oneStar) || 0) + (Number(d.twoStar) || 0)) / t) * 100) / 100 : null; })(),
    permanently_closed: !!place.permanentlyClosed,
    temporarily_closed: !!place.temporarilyClosed,
    branches: opt.branches ?? 1,
  };
}

const clamp01 = (v) => Math.max(0, Math.min(1, v));
const round3 = (v) => Math.round(clamp01(v) * 1000) / 1000;

/** Normalized signal values (0..1, 1 = the signal's HIGH state) from facts. Unknown stays absent (never guessed). */
function signalValues(f) {
  const out = {};
  out.has_website = f.has_website ? 1 : 0;
  const rc = Math.min(1, Math.log10(1 + (f.total_reviews || 0)) / 3.3);
  const rt = clamp01(((f.overall_rating || 0) - 3) / 2);
  out.size_proxy = round3(0.6 * rc + 0.15 * rt + 0.25 * Math.min(1, ((f.branches || 1) - 1) / 3));
  out.unclaimed_listing = f.unclaimed_listing ? 1 : 0;
  out.profile_completeness = round3(0.7 * Math.min(1, (f.images_count || 0) / 15) + 0.3 * (f.has_hours ? 1 : 0));
  if (f.activity_label !== 'unknown') out.activity = f.activity_label === 'active' ? 1 : f.activity_label === 'slowing' ? 0.5 : 0;
  if (f.n_reviews_fetched >= 3) out.owner_engagement = round3(f.owner_reply_rate ?? 0);
  if (f.n_reviews_fetched >= 1) out.unanswered_low_reviews = round3((f.unanswered_low_reviews || 0) / 3);
  if (f.n_reviews_fetched >= 5 && f.rating_delta != null) out.rating_trend = round3(0.5 + Math.max(-0.5, Math.min(0.5, f.rating_delta / 1.0)));
  if (f.is_new_business === true) out.new_business = 1;
  return out;
}

/**
 * Value of the review_insights signal: how much of what customers complain about the seller's offer can help with (0..1).
 * Complaints the offer cannot help with count for nothing (spec 6.3b step 5). Undefined when there is no analysis.
 */
function reviewInsightValue(analysis) {
  if (!analysis || analysis.skipped) return undefined;
  const rel = (analysis.complaints || []).filter((c) => c && c.offer_can_help);
  const n = rel.reduce((a, c) => a + (Number(c.count) || 1), 0);
  const top = rel.slice().sort((a, b) => (b.count || 0) - (a.count || 0))[0];
  return { value: Math.min(1, n / 3), theme: top ? top.theme : null };
}

// ───────────────────────── opportunities (spec 6.3b step 3) ─────────────────────────
// Generic insight types computed from facts. WHICH ones matter, and the angle sentence for each, comes from the
// campaign's opportunity_map (planner output for this offer). Nothing is tied to a segment.
const OPPORTUNITY_TYPES = ['unclaimed_listing', 'no_website', 'thin_profile', 'unanswered_low_reviews', 'dormant_activity', 'declining_rating', 'low_owner_engagement', 'new_business', 'multi_branch', 'review_theme', 'weak_search_rank'];

function evalOpportunity(type, f, analysis) {
  switch (type) {
    case 'unclaimed_listing':
      return f.unclaimed_listing ? { strength: 2, evidence: { reviews: f.total_reviews } } : null;
    case 'no_website':
      return !f.has_website ? { strength: f.total_reviews >= 30 ? 3 : 2, evidence: { reviews: f.total_reviews, rating: f.overall_rating } } : null;
    case 'thin_profile':
      return f.images_count <= 5 || !f.has_hours ? { strength: f.images_count === 0 ? 3 : f.images_count <= 2 ? 2 : 1, evidence: { photos: f.images_count, hours: f.has_hours } } : null;
    case 'unanswered_low_reviews':
      return f.unanswered_low_reviews >= 1 ? { strength: Math.min(3, f.unanswered_low_reviews), evidence: { count: f.unanswered_low_reviews, of: f.n_reviews_fetched } } : null;
    case 'dormant_activity':
      return f.activity_label === 'dormant' ? { strength: 3, evidence: { days: f.days_since_last_review, last: f.last_review_at } }
        : f.activity_label === 'slowing' ? { strength: 1, evidence: { days: f.days_since_last_review, last: f.last_review_at } } : null;
    case 'declining_rating':
      return f.n_reviews_fetched >= 5 && f.rating_delta != null && f.rating_delta <= -0.3
        ? { strength: f.rating_delta <= -0.6 ? 3 : 2, evidence: { recent: f.recent_avg_rating, overall: f.overall_rating } } : null;
    case 'low_owner_engagement':
      return f.n_reviews_fetched >= 5 && f.owner_reply_rate != null && f.owner_reply_rate < 0.2
        ? { strength: f.owner_reply_rate === 0 && f.n_reviews_fetched >= 8 ? 3 : 2, evidence: { rate: f.owner_reply_rate, of: f.n_reviews_fetched } } : null;
    case 'new_business':
      return f.is_new_business === true ? { strength: 2, evidence: { reviews: f.total_reviews } } : null;
    case 'multi_branch':
      return f.branches >= 2 ? { strength: Math.min(3, f.branches), evidence: { branches: f.branches } } : null;
    case 'weak_search_rank':
      // Rank of the place inside the Maps result list of its search: the lower it appears, the less customers find it.
      return f.search_rank != null && f.search_rank >= 5 ? { strength: f.search_rank >= 10 ? 3 : f.search_rank >= 7 ? 2 : 1, evidence: { rank: f.search_rank } } : null;
    case 'review_theme': {
      // Complaint themes become an opportunity ONLY when the analysis says this offer can help, and confidence is not low.
      if (!analysis || analysis.confidence === 'low') return null;
      const hit = (analysis.complaints || []).filter((c) => c && c.offer_can_help).sort((a, b) => (b.count || 0) - (a.count || 0))[0];
      return hit ? { strength: Math.min(3, Math.max(1, hit.count || 1)), evidence: { theme: hit.theme, count: hit.count || 1 } } : null;
    }
    default:
      return null;
  }
}

/**
 * Top opportunities for one lead in one campaign.
 * @param {any} facts
 * @param {any} analysis review analysis (may be null)
 * @param {{type:string, angle:string}[]} oppMap campaign opportunity map, in the planner's priority order
 */
function buildOpportunities(facts, analysis, oppMap, max = 3) {
  const out = [];
  (oppMap || []).forEach((m, idx) => {
    if (!m || !OPPORTUNITY_TYPES.includes(m.type)) return;
    const e = evalOpportunity(m.type, facts, analysis);
    if (e) out.push({ type: m.type, strength: e.strength, evidence: e.evidence, angle: String(m.angle || '').slice(0, 200), _p: idx });
  });
  out.sort((a, b) => b.strength - a.strength || a._p - b._p);
  return out.slice(0, max).map((o) => ({ type: o.type, strength: o.strength, evidence: o.evidence, angle: o.angle }));
}

// ───────────────────────── score (spec 6.3a) ─────────────────────────
// Mirrors public.recompute_campaign_scores in SQL (same constants). Signed weights: w>0 rewards the HIGH state, w<0 the LOW state.
const SCORE = {
  favorable: 0.66, // a signal counts as "above zero" for the two-signal rule when its favorable state is this strong
  noBaseCap: 69, // fewer than two relevant non-baseline signals => score cannot exceed 69 (never "high" alone)
  maybeCap: 60,
  reasonMinWeight: 15, // a reason is shown only if its signal weighs MORE than this in the campaign (unless nothing stronger exists)
  baselineMaxWeight: 25, // baseline facts (e.g. has a website) are clamped unless the planner marked the signal as emphasized
};

/**
 * @param {{fit?:'fit'|'maybe'|'not_fit'|null, signals:{key:string, weight:number, value:number, baseline?:boolean, emphasis?:boolean}[]}} x
 * @returns {{score:number|null, relevant:number, capped_by:string|null, favorable:{key:string, side:'high'|'low', contribution:number}[]}}
 */
function scoreLead({ fit, signals }) {
  if (fit === 'not_fit') return { score: null, relevant: 0, capped_by: 'not_fit', favorable: [] };
  let sum = 0;
  let den = 0;
  let relevant = 0;
  const favorable = [];
  for (const s of signals) {
    let w = Number(s.weight);
    if (!w) continue;
    if (s.baseline && !s.emphasis) w = Math.sign(w) * Math.min(Math.abs(w), SCORE.baselineMaxWeight);
    const v = clamp01(Number(s.value));
    const c = w * v - Math.min(w, 0);
    sum += c;
    den += Math.abs(w);
    const fav = (w > 0 && v >= SCORE.favorable) || (w < 0 && v <= 1 - SCORE.favorable);
    if (fav) {
      favorable.push({ key: s.key, side: w > 0 ? 'high' : 'low', contribution: c, weight: Math.abs(Number(s.weight)) });
      if (!s.baseline || s.emphasis) relevant++;
    }
  }
  if (!den) return { score: null, relevant, capped_by: null, favorable };
  let score = Math.round((100 * sum) / den);
  let capped_by = null;
  if (relevant < 2 && score > SCORE.noBaseCap) { score = SCORE.noBaseCap; capped_by = 'needs_two_signals'; }
  if (fit === 'maybe' && score > SCORE.maybeCap) { score = SCORE.maybeCap; capped_by = 'maybe_fit'; }
  favorable.sort((a, b) => b.contribution - a.contribution);
  // Reasons from a signal weighing 15 or less in the campaign say little ("has a website"): hidden unless nothing stronger exists (mirrors the SQL).
  const strong = favorable.filter((f) => f.weight > SCORE.reasonMinWeight);
  return { score, relevant, capped_by, favorable: strong.length ? strong : favorable };
}

// ───────────────────────── message tact (spec 6.3b step 5) ─────────────────────────
// Safety net on top of the prompt: the first message never mentions complaints, low ratings or any weakness of the lead.
const NEGATIVE_AR = ['شكوي', 'شكاوي', 'شكوه', 'شتك', 'مشكله', 'مشاكل', 'سيء', 'سيئ', 'وحش', 'ضعيف', 'ضعف', 'تاخير', 'متاخر', 'اهمال', 'مهمل', 'قصور', 'فشل', 'بطيء', 'بطئ', 'غير راضي', 'مش راضي', 'تقييم سيء', 'تقييم منخفض', 'تقييم قليل', 'تقييمات منخفضه', 'تقييمات سلبيه', 'سلبي', 'نجمه واحده', 'نجمتين', 'ريفيوهات وحشه', 'عيب', 'عيوب', 'نقطه ضعف', 'نقاط ضعف', 'مفيش رد', 'بدون رد', 'مرددتوش', 'ما ردتوش', 'مردتوش', 'مش بتردو', 'مبتردوش'];
const NEGATIVE_EN = ['complain', 'bad review', 'low rating', 'poor rating', 'negative', 'weakness', 'problem with', 'unanswered'];

// Unsupported first-person claims about the lead (the sender has not seen their work): hearsay, own opinions, visits.
const CLAIMS_AR = ['سمعت', 'سمعنا', 'عاجبني', 'عجبني', 'عاجبنا', 'عجبنا', 'شايف ان شغل', 'شايف انكم', 'متابع شغل', 'تابعت', 'زرت', 'جربت', 'اتعاملت معاكم', 'شغلكم رائع', 'شغلكم ممتاز', 'شغلكم حلو', 'شغلكم تحفه', 'بتعملوا شغل رائع', 'بتقدموا شغل حلو', 'من افضل'];

/** @returns {{ok:boolean, reasons:string[]}} */
function checkTact(message, complaints = []) {
  const m = norm(message);
  const reasons = [];
  for (const w of NEGATIVE_AR.concat(NEGATIVE_EN)) if (m.includes(norm(w))) reasons.push(`word:${w}`);
  for (const w of CLAIMS_AR) if (m.includes(norm(w))) reasons.push(`claim:${w}`);
  // "your rating/reviews are low/bad" in any phrasing
  if (/(تقييم|ريفيو|نجوم|rating|review)\S*\s+(\S+\s+){0,2}(منخفض|قليل|ضعيف|سلبي|وحش|سيء|واطي|low|poor|bad)/.test(m)) reasons.push('rating_negative');
  for (const c of complaints || []) {
    const theme = typeof c === 'string' ? c : c && c.theme;
    for (const tok of norm(theme).split(' ')) if (tok.length >= 5 && m.includes(tok)) reasons.push(`theme:${tok}`);
  }
  return { ok: reasons.length === 0, reasons: [...new Set(reasons)] };
}


// ───────────────────────── message style rules (round 2) ─────────────────────────
// When the seller's product writes messages, the first message IS the demo: it must not read like a template. These are the
// checks that can be made in code; the prompt carries the rest. Nothing here depends on an industry or an offer.
const RATING_WORDS = ['تقييم', 'تقيم', 'نجمه', 'نجوم', 'ريفيو', 'rating', 'star', 'review'];
const JARGON_RE = /(^|[^a-z])(b2b|b2c|leads?|outreach|pipeline|crm|roi|kpi|funnel)([^a-z]|$)/i;
const JARGON_AR = ['بي تو بي', 'ليدز', 'ليد '];
const DAYTIME_AR = ['صباح', 'مساء'];
const WEAK_CTA = ['ممكن نتكلم', 'نتكلم اكتر', 'نتناقش', 'ممكن نتحدث', 'ممكن نتواصل', 'نتواصل معاكم'];
// Generic benefit phrases the writer likes to invent; allowed only if the seller's own offer text says so.
const BENEFIT_FLUFF = ['رضا العملاء', 'رضاهم', 'رضاكم', 'تعزيز التواصل', 'تقويه التواصل', 'يقوي التواصل', 'تحسين تجربه', 'يزود رضا', 'زياده رضا', 'جوده العمل', 'تركزوا علي شغلكم', 'تركز علي شغلها', 'تركزوا في شغلكم', 'شغلكم الاساسي', 'شغلها الاساسي', 'توفرو وقتكم', 'توفر وقتكم', 'تقلقوا', 'تقلق '];
// The sender has not seen their work: no own praise, and a first message promises no guarantee.
// Praise words are allowed only when the message attributes them to the customers ("عملاءكم بيشكروا في ..."); the sender's own praise is rejected.
const PRAISE_AR = ['مميز', 'ممتاز', 'رائع', 'شاطر', 'عظيم', 'متميز', 'تميز', 'احتراف', 'محترف', 'مختلف', 'متطور', 'ابداع', 'مبدع', 'خبره عاليه', 'باين عليكم', 'باين ان'];
const ATTRIBUTION = ['عملاءكم', 'عملاؤكم', 'عملائكم', 'بيشكروا', 'بيتكلموا', 'بيمدحوا', 'بيقولوا', 'بيحبوا'];
// Claims about the lead's own needs: "شغلكم ... بيحتاج/محتاج ...", "أكيد ...". Needs of the companies we would bring them ("شركات محتاجة خدماتكم") are fine.
const ASSUMES = /((^| )(اكيد|واضح انكم|باين انكم|واضح ان|باين ان)( |$))|(((انتم|انكم|بيخليكم)( \S+){0,2}|(^| )(شغلكم|نشاطكم|مجالكم|عملكم|خدمتكم|تخصصكم|شركتكم|وكالتكم)( \S+){0,6}) (بيحتاج|بتحتاج|يحتاج|محتاج|محتاجه|محتاجين|بيتطلب|بتتطلب)( |$))/;
// "always" is an overclaim about their customers or their work.
const OVERCLAIM_AR = ['دايما', 'دائما', 'طول الوقت', 'كل الناس'];
const GUARANTEE_AR = ['نضمن', 'بنضمن', 'هنضمن', 'مضمون', 'ضمان', 'guarantee'];
const STOP = new Set(['من', 'في', 'علي', 'عن', 'الي', 'مع', 'ده', 'دي', 'كده', 'لو', 'او', 'ان', 'انت', 'انتم', 'احنا', 'هو', 'هي']);

const wordList = (s) => String(s || '').trim().split(/\s+/).filter(Boolean);
const contentTokens = (s) => catTokens(s).filter((t) => t.length >= 2 && !STOP.has(t));

/**
 * Does the message copy a run of `n` or more consecutive words from one of the organization's style examples? Runs that also occur in the
 * seller's own offer text (its description and its call to action) are allowed: those words come from the offer, not from the example.
 */
function copiedRun(message, examples, allowedText = '', n = 8) {
  const toks = (t) => norm(t).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter(Boolean);
  const grams = (arr) => { const out = []; for (let i = 0; i + n <= arr.length; i++) out.push(arr.slice(i, i + n).join(' ')); return out; };
  const allowed = new Set(grams(toks(allowedText)));
  const mine = grams(toks(message)).filter((g) => !allowed.has(g));
  if (!mine.length) return false;
  const theirs = new Set((examples || []).flatMap((e) => grams(toks(e))));
  return mine.some((g) => theirs.has(g));
}

/** First five words of a message (normalized): two messages of one campaign must not share them. */
function openingKey(message) {
  return norm(message).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter(Boolean).slice(0, 5).join(' ');
}

/** Word-set overlap (Jaccard, 0..1) of two messages: two messages of one campaign above SIMILAR_LIMIT read like the same template. */
const SIMILAR_LIMIT = 0.6;
function messageSimilarity(a, b) {
  const t = (s) => new Set(norm(s).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter((w) => w.length > 2));
  const x = t(a);
  const y = t(b);
  const inter = [...x].filter((w) => y.has(w)).length;
  const uni = new Set([...x, ...y]).size;
  return uni ? inter / uni : 0;
}

/** Does the quoted phrase come from the seller's offer text? Exact (normalized) match, or at least 85% of its words, for 3+ words. */
function quoteInOffer(quote, offerText) {
  const q = norm(quote).replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\s+/g, ' ').trim();
  const o = norm(offerText).replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\s+/g, ' ').trim();
  if (q.split(' ').length < 3 || !o) return false;
  if (o.includes(q)) return true;
  const have = new Set(catTokens(o));
  const qt = catTokens(q);
  return qt.length >= 3 && qt.filter((t) => have.has(t)).length / qt.length >= 0.85;
}

/**
 * Style and honesty checks on one first message.
 * @param {string} message
 * @param {{channel?:string, areas?:string[], city?:string|null, offerText?:string, offerQuote?:string|null, ctaOffer?:string|null, senderName?:string|null}} ctx
 * @returns {{ok:boolean, reasons:string[]}}
 */
function checkMessage(message, ctx = {}) {
  const m = norm(message);
  const reasons = [];
  const chat = ctx.channel !== 'email';
  const n = wordList(message).length;
  if (chat && (n < 35 || n > 70)) reasons.push(`word_count_${n}`);
  for (const w of RATING_WORDS) if (m.includes(norm(w))) { reasons.push('mentions_rating'); break; }
  if (/[⭐★☆]/.test(message)) reasons.push('mentions_rating');
  if (JARGON_RE.test(m) || JARGON_AR.some((w) => m.includes(norm(w)))) reasons.push('jargon');
  if (DAYTIME_AR.some((w) => new RegExp(`(^| )${norm(w)}`).test(m)) || /good (morning|evening|afternoon)/.test(m)) reasons.push('time_greeting');
  // micro-districts: the lead's own district / neighborhood names are never used; the city (at most) is fine
  const city = norm(ctx.city || '');
  for (const a of ctx.areas || []) {
    const t = norm(a);
    if (t.length >= 3 && t !== city && !(city && city.includes(t)) && m.includes(t)) { reasons.push(`micro_district:${a}`); break; }
  }
  if (/(المنطقه|الحي|حي) (ال)?(اولي|ثانيه|ثالثه|رابعه|خامسه|سادسه|سابعه|ثامنه|تاسعه|عاشره|اول|ثاني|ثالث|رابع|خامس|سادس|سابع|ثامن|تاسع|عاشر)/.test(m)) reasons.push('micro_district:ordinal');
  if (WEAK_CTA.some((w) => m.includes(norm(w)))) reasons.push('weak_cta');
  {
    const ws = m.split(/\s+/);
    const own = ws.some((w, i) => PRAISE_AR.some((p) => w.includes(norm(p))) && !ws.slice(Math.max(0, i - 7), i).some((b) => ATTRIBUTION.some((a) => b.includes(norm(a)))));
    if (own) reasons.push('own_praise');
    if (ASSUMES.test(m)) reasons.push('assumes_need');
    if (OVERCLAIM_AR.some((w) => new RegExp(`(^| )${norm(w)}( |$)`).test(m))) reasons.push('overclaim_always');
  }
  if (GUARANTEE_AR.some((w) => m.includes(norm(w)))) reasons.push('guarantee');
  const offerN = norm(ctx.offerText || '');
  for (const f of BENEFIT_FLUFF) if (m.includes(norm(f)) && !offerN.includes(norm(f))) { reasons.push(`invented_benefit:${f}`); break; }
  if (ctx.offerText) {
    if (!ctx.offerQuote) reasons.push('offer_quote_missing');
    else if (!quoteInOffer(ctx.offerQuote, ctx.offerText)) reasons.push('offer_quote_not_in_offer');
  }
  if (ctx.ctaOffer) {
    const have = new Set(contentTokens(message));
    const hit = contentTokens(ctx.ctaOffer).filter((t) => have.has(t)).length;
    if (hit < 2) reasons.push('cta_offer_missing');
  }
  if (ctx.senderName && chat) {
    const tail = m.slice(-60);
    if (!tail.includes(norm(ctx.senderName))) reasons.push('missing_signature');
    // the sender's name appears once, in the signature at the end (never also as an introduction at the start)
    if (m.split(norm(ctx.senderName)).length - 1 > 1) reasons.push('double_signature');
  }
  if ((ctx.styleExamples || []).length && copiedRun(message, ctx.styleExamples, ctx.offerText || ctx.ctaOffer || '')) reasons.push('copies_style_example');
  return { ok: reasons.length === 0, reasons: [...new Set(reasons)] };
}

const REASON_HELP = {
  own_praise: 'you praised their work yourself (praise is allowed only as what their customers say)',
  assumes_need: 'you claimed something about what the lead itself needs',
  copies_style_example: 'you copied 8 or more consecutive words from a style example: write your own sentences',
  double_signature: 'the sender name appears more than once: it belongs only in the signature at the end',
  overclaim_always: 'you used "always" (دايما / دائما)',
  mentions_rating: 'you mentioned the rating, stars or reviews',
  jargon: 'you used jargon (B2B, leads...)',
  time_greeting: 'you used a time-of-day greeting',
  weak_cta: 'the ending was a weak "can we talk" question',
  guarantee: 'you promised or guaranteed something',
  invented_benefit: 'you promised a benefit that is not in the offer',
  offer_quote_missing: 'offer_quote was missing',
  offer_quote_not_in_offer: 'offer_quote was not copied word for word from sender_offer',
  cta_offer_missing: 'the concrete cta_offer was not in the ending',
  missing_signature: 'the signature was missing at the end',
  duplicate_opening: 'the opening is the same as another message',
  too_similar_to_another_message: 'the text is too close to another message',
  too_similar: 'the text is too close to another message',
};
function explainReason(reason) {
  const parts = String(reason).replace(/^style:/, '').split(/[,:]/).map((x) => x.trim()).filter(Boolean);
  const out = [];
  for (const p of parts) {
    if (REASON_HELP[p]) out.push(REASON_HELP[p]);
    else if (/^word_count_(\d+)$/.test(p)) out.push(`the text had ${p.slice(11)} words (it must be 35 to 70)`);
    else if (p === 'tact') out.push('you mentioned something negative (a problem, complaint or weakness) about the business or used a word like "problem"');
    else if (p === 'micro_district') out.push('you named a district or neighborhood');
  }
  return [...new Set(out)];
}

/** The single automatic retry of a rejected first message: same request plus the rejected reply and the reason as feedback. */
function retryRequestBody(requestBody, raw, reason) {
  const req = JSON.parse(requestBody);
  req.messages = [...req.messages, { role: 'assistant', content: raw || '{}' }, { role: 'user', content: `Your reply was rejected (${reason}). Rewrite it and return the JSON again. Remember: 35 to 70 words, no rating or stars or reviews, no district or neighborhood names, no jargon (no B2B), no time-of-day greeting, no "ممكن نتكلم", no praise of their work, no guarantees, no "focus on your core work" lines, address them as a team in the plural, end with the concrete offer (cta_offer) worded differently from the usual and the signature, offer_quote must be copied word for word from sender_offer, never invent benefits, never mention complaints or weaknesses, start differently from avoid_openings and use different sentences from the other messages of this campaign.` }];
  const why = explainReason(reason);
  if (why.length) req.messages[req.messages.length - 1].content += ` Specifically: ${why.join('; ')}.`;
  const wc = /word_count_(\d+)/.exec(String(reason));
  if (wc) req.messages[req.messages.length - 1].content += ` The text had ${wc[1]} words. Write between 45 and 60 words: ${Number(wc[1]) < 35 ? 'add one more concrete sentence about what the offer does (use the wording of offer_quote)' : 'cut the weakest sentence'}.`;
  req.temperature = 0.5;
  return JSON.stringify(req);
}

// ───────────────────────── LLM helpers (OpenRouter request/response) ─────────────────────────
/** OpenRouter chat request body (string). `fallback` = fallback model ids tried on provider failure. */
function llmRequest({ system, user, model, fallback = [], temperature = 0, extraMessages = [] }) {
  const req = {
    messages: [{ role: 'system', content: system }, { role: 'user', content: typeof user === 'string' ? user : JSON.stringify(user) }, ...extraMessages],
    response_format: { type: 'json_object' },
    temperature,
    usage: { include: true },
  };
  const fb = (fallback || []).filter(Boolean);
  if (fb.length) req.models = [model, ...fb]; else req.model = model;
  return JSON.stringify(req);
}

/** Parse an OpenRouter full-response item. @returns {{data:any|null, usage:{in:number,out:number,cost:number,model:string|null}, status:number|null}} */
function parseLlm(res) {
  const r = res || {};
  const u = (r.body && r.body.usage) || {};
  const usage = { in: u.prompt_tokens || 0, out: u.completion_tokens || 0, cost: Number(u.cost) || 0, model: (r.body && r.body.model) || null };
  let data = null;
  if (r.statusCode >= 200 && r.statusCode < 300 && r.body && r.body.choices) {
    try { data = JSON.parse((r.body.choices[0]?.message?.content || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch { data = null; }
  }
  return { data, usage, status: typeof r.statusCode === 'number' ? r.statusCode : null };
}

/** System prompt of the fit check (spec 6.0 step 3 and 4). Offer-agnostic: the ideal prospect text is the only criterion. */
function fitSystemPrompt({ ideal, offerText, negatives = [] }) {
  return `You judge whether Google Maps places are potential CUSTOMERS (prospects) for a seller.
Ideal prospect: ${ideal || '(not stated; judge from the seller offer)'}
Seller offer: ${String(offerText || '').slice(0, 500)}
For each place decide: "fit" (clearly the kind of business described), "maybe" (possibly, adjacent or unclear), "not_fit" (a different kind of business even if its NAME contains similar words, a public or government body, a competitor of the seller, or unrelated).
EVIDENCE RULES:
- Judge ONLY from the place's categories, its description and its website address. The business NAME is context only: words inside a name (including words that also appear in the ideal prospect text or the seller offer) are NOT evidence of what the business does or sells.
- When a word naming an industry, a product or a customer group sits next to the word that names the kind of business (in the name or in a category), it says what the business SELLS or serves, so the business belongs to THAT sector: answer "not_fit" (not "maybe"), unless the ideal prospect text itself asks for that sector.
- Return "evidence": the source that supports your label, one of "category", "description", "website", "name_only" (nothing but the name supports it) or "none". Use "fit" only when the evidence is category, description or website.
Give a SHORT reason (max 12 words, in the same language as the ideal prospect text).${negatives.length ? `\nThe seller already rejected businesses like these (treat similar ones as not_fit):\n${negatives.slice(0, 15).map((n) => `- ${n.business_name || ''} (${n.category || ''}): ${n.reason || ''}`).join('\n')}` : ''}
Return ONE JSON object only: {"results":[{"i": number, "fit": "fit"|"maybe"|"not_fit", "evidence": "category"|"description"|"website"|"name_only"|"none", "reason": string}]} covering every i.`;
}

const hostOf = (u) => { try { return new URL(/^[a-z]+:\/\//i.test(u) ? u : `https://${u}`).hostname.replace(/^www\./, '').toLowerCase(); } catch { return ''; } };

/** Social and messaging pages people use instead of a website. A business that only has one of these has no real website. */
const SOCIAL_HOSTS = ['facebook.com', 'fb.com', 'fb.me', 'instagram.com', 'linktr.ee', 'beacons.ai', 'tiktok.com', 'twitter.com', 'x.com', 'linkedin.com', 'wa.me', 'whatsapp.com', 'youtube.com', 'youtu.be', 't.me', 'behance.net'];
function isSocialUrl(u) {
  const h = hostOf(String(u || ''));
  return !!h && SOCIAL_HOSTS.some((s) => h === s || h.endsWith(`.${s}`));
}

/** The compact description of one place sent to the fit check: categories, description and website address are evidence; the name is context. */
function fitAsk(rawPlace, area) {
  const cats = [rawPlace.categoryName, ...(Array.isArray(rawPlace.categories) ? rawPlace.categories : [])].filter(Boolean);
  const desc = stripInvisible(rawPlace.description || rawPlace.ownerDescription || rawPlace.subTitle || '').slice(0, 240);
  return {
    name: stripInvisible(rawPlace.title), categories: [...new Set(cats)].slice(0, 8), description: desc || null,
    website: rawPlace.website ? hostOf(String(rawPlace.website)) || 'yes' : 'no', area: area || '', rating: rawPlace.totalScore ?? null, reviews: rawPlace.reviewsCount ?? null,
  };
}

/**
 * Keep or remove one place after the fit check (spec 6.0 step 4, round 2 fixes).
 * Inside the allowed categories: fit or maybe is kept (the category itself is evidence), not_fit removed.
 * Outside them: kept ONLY when the check said "fit" with evidence from the categories, description or website; never from the name,
 * never for "maybe". Nothing is learned from the model: a category joins the allowed list only through a user action.
 * @returns {{keep:boolean, fit?:'fit'|'maybe', why?:string}}
 */
function decideFit({ label, inside }) {
  const l = label || { fit: 'maybe', reason: 'unchecked' };
  if (l.fit === 'not_fit') return { keep: false, why: 'not_fit' };
  const ev = l.evidence;
  const real = ev === 'category' || ev === 'description' || ev === 'website';
  if (inside) return { keep: true, fit: l.fit === 'fit' && ev !== 'name_only' ? 'fit' : 'maybe' };
  if (l.fit === 'fit' && real) return { keep: true, fit: 'fit' };
  return { keep: false, why: l.fit === 'fit' ? 'name_only_evidence' : 'outside_categories' };
}

// ───────────────────────── search rounds (spec 6.2) ─────────────────────────
/** Search area of a location: the most specific name and a clean geocoder string (no repeated parts, no hidden characters). */
function areaOf(l) {
  // Unique parts; a part already contained in a more specific one is dropped ("القاهرة" inside "التجمع الخامس القاهرة").
  const parts = [cleanPlace(l.district), cleanPlace(l.city), cleanPlace(l.governorate)].filter(Boolean);
  const kept = parts.filter((p, i) => !parts.some((q, j) => j !== i && norm(q) !== norm(p) && norm(q).includes(norm(p))) && parts.findIndex((q) => norm(q) === norm(p)) === i);
  return { area: cleanPlace(l.district || l.city || l.governorate || ''), locationQuery: kept.concat('Egypt').join(', ') };
}

/**
 * Plan the Apify searches for a round. Rounds: 1 base queries at real depth; 2 same queries deeper (only the ones that hit
 * their cap); 3 synonyms; 4 nearby districts; 5 broad fallback (city level, simplest keyword) used for zero results.
 * @returns {{round:number, searches:{query:string, area:string, locationQuery:string, depth:number}[]}|null} null = exhausted
 */
function planRound({ round, target, keywords, synonyms = [], locations, nearby = [], done = [], saturated = [], avoid = [], minDepth = 20, maxDepth = 120 }) {
  const doneSet = new Set(done.map((d) => norm(d)));
  const loc = areaOf;
  const mk = (kws, locs, depthMul = 1) => {
    const base = Math.min(maxDepth, Math.max(minDepth, Math.ceil((target * 2.5) / Math.max(1, kws.length * locs.length))));
    const depth = Math.min(maxDepth, Math.ceil(base * depthMul));
    const s = [];
    for (const l of locs) {
      const { area, locationQuery } = loc(l);
      for (const k of kws) {
        const query = `${cleanPlace(k)} ${area}`.trim();
        s.push({ query, area, locationQuery, depth, key: norm(`${depthMul}|${query}`) });
      }
    }
    return s;
  };
  let searches = [];
  if (round === 1) searches = mk(keywords, locations);
  else if (round === 2) {
    const sat = new Set(saturated.map(norm));
    searches = mk(keywords, locations, 2.5).filter((s) => sat.has(norm(s.query)));
  } else if (round === 3) searches = mk(synonyms, locations);
  else if (round === 4) searches = mk(keywords.concat(synonyms).slice(0, 4), nearby);
  else if (round === 5) {
    // Broad fallback: simplest keyword, city level (or governorate), no district polygon.
    const broad = locations.map((l) => ({ governorate: l.governorate, city: l.city || l.governorate, district: '' }));
    searches = mk(keywords.slice(0, 2), broad.length ? broad : locations);
  } else return null;
  // `avoid` = searches this organization already ran in earlier campaigns: the same companies would come back, so prefer new ones.
  const avoidSet = new Set(avoid.map(norm));
  searches = searches.filter((s) => s.query && !doneSet.has(norm(s.query) + '|' + round) && !avoidSet.has(norm(s.query)));
  return searches.length ? { round, searches } : null;
}

/**
 * After a round: which round next (null = stop). Normal order 1..5; if round 1 found no places at all the engine jumps to the
 * broad fallback first (city level, simplest keywords), then synonyms and nearby districts.
 * @returns {{next:number|null, mode:'normal'|'zero'}}
 */
function decideNext({ round, mode = 'normal', delivered, target, rawTotal }) {
  if (delivered >= target) return { next: null, mode };
  if (round === 1 && rawTotal === 0) return { next: 5, mode: 'zero' };
  if (mode === 'zero') return { next: round === 5 ? 3 : round === 3 ? 4 : null, mode };
  return { next: round < 5 ? round + 1 : null, mode };
}

/** Why a campaign delivered nothing (plain code, mapped to a user message with concrete suggestions in the UI). */
function emptyReason(f) {
  if (!f.raw_places) return 'no_places';
  if (f.removed_not_fit >= (f.raw_places - f.removed_category - f.removed_global - f.removed_closed) && f.removed_not_fit > 0) return 'all_not_fit';
  if (f.removed_category + f.removed_global >= f.raw_places * 0.8) return 'all_category';
  if (f.previously_found > 0 && f.previously_found >= f.raw_places * 0.5) return 'all_previously_found';
  if (f.cooldown > 0 && f.cooldown >= f.raw_places * 0.5) return 'all_cooldown';
  return 'all_filtered';
}

/** Funnel keys shown on the campaign page, in order (spec 6.2). */
const FUNNEL_KEYS = ['queries', 'raw_places', 'removed_category', 'removed_global', 'removed_closed', 'removed_landline', 'removed_filters', 'removed_not_fit', 'duplicates', 'previously_found', 'opted_out', 'cooldown', 'delivered'];

const body = $('Webhook').first().json.body;
const sd = $getWorkflowStaticData('global');
const key = `open_${body.job_id}`;
for (const k of Object.keys(sd)) if (k.startsWith('open_') && k !== key && k !== `${key}_t`) delete sd[k];
const seen = new Set(sd[key] || []);
const texts = sd[`${key}_t`] || [];
const metaByLead = new Map($('Select and build').all().map((i) => [i.json.lead_id, i.json]));

const out = $input.all().map((it, idx) => {
  const r = it.json;
  if (r && r.ok && r.opening) {
    const similar = texts.some((t) => messageSimilarity(t, r.message) >= SIMILAR_LIMIT);
    if (seen.has(r.opening) || similar) {
      const meta = metaByLead.get(r.lead_id);
      const retryable = !!meta;
      return {
        json: { ...r, ok: false, reason: similar && !seen.has(r.opening) ? 'too_similar' : 'duplicate_opening', retry: retryable, requestBody: retryable ? retryRequestBody(meta.requestBody, r.raw_content, similar && !seen.has(r.opening) ? 'too_similar_to_another_message' : 'duplicate_opening') : '{}',
          save: meta && meta.message_id
            ? { method: 'PATCH', path: `messages?id=eq.${meta.message_id}&review_status=neq.sent`, prefer: 'return=minimal', body: { review_status: 'failed', fail_reason: 'duplicate_opening', job_id: meta.job_id } }
            : { method: 'POST', path: 'messages?on_conflict=lead_id,campaign_id,channel', prefer: 'resolution=ignore-duplicates,return=minimal', body: { organization_id: r.organization_id, lead_id: r.lead_id, campaign_id: r.campaign_id, job_id: r.job_id, channel: r.channel, generated_text: '', review_status: 'failed', fail_reason: 'duplicate_opening' } } },
        pairedItem: { item: idx },
      };
    }
    seen.add(r.opening);
    texts.push(r.message);
  }
  return { json: r, pairedItem: { item: idx } };
});
sd[key] = [...seen];
sd[`${key}_t`] = texts.slice(-60);
return out;

// WF3 "Validate message": parse the LLM JSON and enforce the message rules (spec 6.4, 6.3b step 5 and the round 2 style rules). Runs once per item.
// Used by two nodes: "Validate message" (first attempt) and "Validate retry" (the single automatic retry, with feedback).
// Lead insights core (spec 6.2, 6.3a, 6.3b). Plain ESM JS with no imports so the SAME source is inlined into n8n Code
// nodes (marker /*__INSIGHTS__*/) and used by unit tests and the fixture runner. Nothing here knows any industry,
// segment or offer: relevance always comes from the campaign (allowed categories, signal weights, opportunity map).

// ───────────────────────── text helpers ─────────────────────────
const INVISIBLE = new RegExp('[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]', 'g');
const DIACRITICS = new RegExp('[\u064B-\u065F\u0670\u0640]', 'g');

/** Lowercase, strip invisible/bidi marks and Arabic diacritics, unify alef/yaa/taa-marbuta, collapse spaces. */
function norm(s) {
  return String(s ?? '')
    .toLowerCase()
    .replace(INVISIBLE, '')
    .replace(DIACRITICS, '')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Invisible/bidi marks removed, whitespace collapsed. */
function stripInvisible(s) {
  return String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
}

/** Clean one location part for Apify: no invisible marks, no repeated words ("التجمع الخامس القاهرة القاهرة"). */
function cleanPlace(s) {
  const t = String(s ?? '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
  const out = [];
  for (const w of t.split(' ')) if (!out.length || norm(out[out.length - 1]) !== norm(w)) out.push(w);
  return out.join(' ');
}

// ───────────────────────── global exclusions (spec 6.3a) ─────────────────────────
// Always on, for every campaign. Matched against Google Maps CATEGORIES (Arabic and English), never against the name alone.
// Hospitals only for health: clinics, labs and pharmacies are legitimate prospects for many offers.
const GLOBAL_EXCLUSIONS = {
  government: ['مكتب حكومي', 'جهه حكوميه', 'هيئه حكوميه', 'مبني حكومي', 'وزاره', 'محافظه', 'مجلس مدينه', 'قسم شرطه', 'مركز شرطه', 'محكمه', 'نيابه', 'مصلحه', 'سجل مدني', 'government office', 'government organization', 'government agency', 'local government', 'city government', 'county government', 'municipality', 'ministry', 'police', 'courthouse', 'public administration'],
  utility: ['محطه كهرباء', 'محطه توليد', 'محطه مياه', 'محطه معالجه', 'محطه تحويل', 'محطه صرف', 'شركه كهرباء', 'شركه مياه', 'شركه غاز', 'سنترال', 'مرفق عام', 'power station', 'power plant', 'electric utility', 'electricity', 'water utility', 'water treatment', 'water works', 'sewage', 'telephone exchange', 'substation', 'gas utility', 'public utility'],
  education: ['جامعه', 'كليه', 'مدرسه', 'روضه اطفال', 'ثانويه', 'اعداديه', 'ابتدائيه', 'university', 'college', 'school', 'kindergarten', 'academy of', 'faculty'],
  health: ['مستشفي', 'hospital'],
  worship: ['مسجد', 'جامع', 'كنيسه', 'دير', 'معبد', 'مكان عباده', 'mosque', 'church', 'temple', 'synagogue', 'place of worship', 'cathedral', 'monastery'],
  embassy: ['سفاره', 'قنصليه', 'embassy', 'consulate'],
  military: ['موقع عسكري', 'قاعده عسكريه', 'معسكر', 'عسكري', 'military', 'army base', 'air force', 'naval'],
};

const hasEn = (p) => /^[a-z ]+$/.test(p);
const catMatches = (c, p) => (hasEn(p) ? new RegExp(`(^| )${p}( |$|s\\b)`).test(c) : c.includes(p));

/** @returns {{group:string, match:string, category:string}|null} */
function globalExclusion(categories) {
  for (const raw of categories || []) {
    const c = norm(raw);
    if (!c) continue;
    for (const [group, pats] of Object.entries(GLOBAL_EXCLUSIONS)) {
      for (const p of pats) if (catMatches(c, norm(p))) return { group, match: p, category: String(raw) };
    }
  }
  return null;
}

/** Brand part of a business name ("X - Nasr City" and "X (Maadi)" are the same brand), normalized. */
function brandKey(name) {
  return norm(String(name || '').split(/\s[-–|]\s|\(|\|/)[0]).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

/**
 * Branches of one business: listings of the organization with the same normalized brand name AND the same website or the same phone
 * (a Facebook/Instagram page is not a shared website). Name similarity alone never counts: it is what made unrelated places look like chains.
 * @param {{business_name?:string, website?:string, phone_e164?:string}} self
 * @param {{business_name?:string, website?:string, phone_e164?:string}[]} all every listing of the organization (the business itself included)
 */
function countBranches(self, all) {
  const key = brandKey(self.business_name);
  if (!key) return 1;
  const site = (u) => (u && !isSocialUrl(u) ? hostOf(String(u)) : '');
  const mySite = site(self.website);
  const myPhone = self.phone_e164 || '';
  let n = 0;
  for (const o of all || []) {
    if (brandKey(o.business_name) !== key) continue;
    if ((mySite && site(o.website) === mySite) || (myPhone && o.phone_e164 === myPhone)) n++;
  }
  return Math.max(1, n);
}

/** Light stemmer so "وكالات" matches "وكالة" and "Agencies" matches "agency" (no dictionary, no segment knowledge). */
function stemToken(raw) {
  let t = norm(raw);
  if (/^[a-z0-9]+$/.test(t)) {
    if (t.length > 4 && t.endsWith('ies')) return t.slice(0, -3) + 'y';
    if (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) return t.slice(0, -1);
    return t;
  }
  if (t.length > 4) t = t.replace(/^(وال|بال|لل|ال)/, '');
  if (t.length > 3) t = t.replace(/(ات|ون|ين|ان)$/, '');
  if (t.length > 3) t = t.replace(/ه$/, '');
  if (t.length > 3) t = t.replace(/ي$/, '');
  return t;
}
const catTokens = (s) => norm(s).split(/[^\p{L}\p{N}]+/u).filter(Boolean).map(stemToken);

/**
 * Does any Maps category match the campaign's allowed categories (Arabic and English)? Done by us, never by the actor.
 * Singular/plural and the Arabic article are ignored. An allowed entry matches a place category when all its words occur in the
 * category, or the category is a (parent) subset of the entry. An empty allow-list means "no category restriction" (old campaigns).
 * @returns {{ok:boolean, matched:string|null}}
 */
function categoryMatch(placeCategories, allowed) {
  const list = (allowed || []).map((a) => ({ a, tokens: catTokens(a) })).filter((x) => x.tokens.length && norm(x.a).length >= 3);
  if (!list.length) return { ok: true, matched: null };
  for (const raw of placeCategories || []) {
    const c = catTokens(raw);
    if (!c.length) continue;
    const cs = new Set(c);
    for (const { a, tokens } of list) {
      const as = new Set(tokens);
      if (tokens.every((t) => cs.has(t))) return { ok: true, matched: a };
      if (c.every((t) => as.has(t)) && (c.length >= 2 || c[0].length >= 4)) return { ok: true, matched: a };
    }
  }
  return { ok: false, matched: null };
}

// ───────────────────────── deterministic facts (spec 6.3b step 1) ─────────────────────────
const DAY = 86400000;
const MONTH = 30.44 * DAY;
const r1 = (x) => Math.round(x * 10) / 10;

/**
 * @param {any} place raw Google Maps place (compass/crawler-google-places)
 * @param {any[]} reviews raw reviews for that place (compass/google-maps-reviews-scraper), newest first or any order
 * @param {{now?:number, branches?:number}} [opt]
 */
function computeFacts(place, reviews = [], opt = {}) {
  const now = opt.now ?? Date.now();
  const seen = new Set();
  const rev = [];
  for (const r of reviews || []) {
    if (!r) continue;
    const id = r.reviewId || `${r.publishedAtDate}|${r.stars}|${r.text}`;
    if (seen.has(id)) continue;
    seen.add(id);
    rev.push(r);
  }
  const dates = rev.map((r) => Date.parse(r.publishedAtDate)).filter(Number.isFinite).sort((a, b) => a - b);
  const n = rev.length;
  const total = Number(place.reviewsCount) || n;
  const overall = Number(place.totalScore) || null;
  const last = dates.length ? dates[dates.length - 1] : null;
  const oldest = dates.length ? dates[0] : null;
  const sinceLast = last == null ? null : (now - last) / DAY;
  const activity_label = last == null ? 'unknown' : sinceLast <= 90 ? 'active' : sinceLast <= 365 ? 'slowing' : 'dormant';
  const spanMonths = oldest == null ? null : Math.max(0.25, (now - oldest) / MONTH);
  const replies = rev.filter((r) => r.responseFromOwnerText && String(r.responseFromOwnerText).trim()).length;
  const low = rev.filter((r) => Number(r.stars) <= 2);
  const stars = rev.map((r) => Number(r.stars)).filter(Number.isFinite);
  const recent_avg = stars.length ? stars.reduce((a, b) => a + b, 0) / stars.length : null;
  const texts = rev.filter((r) => (r.text || r.textTranslated || '').toString().trim());
  const images = Number(place.imagesCount) || 0;
  return {
    n_reviews_fetched: n,
    n_texts: texts.length,
    total_reviews: total,
    overall_rating: overall,
    last_review_at: last == null ? null : new Date(last).toISOString(),
    days_since_last_review: sinceLast == null ? null : Math.round(sinceLast),
    reviews_per_month: spanMonths == null || n < 2 ? null : r1(n / spanMonths),
    activity_label,
    // Only claim "new" when the fetched window provably covers the whole history and it started within a year.
    is_new_business: oldest != null && now - oldest <= 365 * DAY && total <= n ? true : null,
    owner_reply_rate: n ? Math.round((replies / n) * 100) / 100 : null,
    low_reviews: low.length,
    unanswered_low_reviews: low.filter((r) => !(r.responseFromOwnerText && String(r.responseFromOwnerText).trim())).length,
    recent_avg_rating: recent_avg == null ? null : r1(recent_avg),
    rating_delta: recent_avg == null || overall == null ? null : r1(recent_avg - overall),
    unclaimed_listing: place.claimThisBusiness === true,
    images_count: images,
    has_hours: Array.isArray(place.openingHours) && place.openingHours.length > 0,
    has_description: !!(place.description || place.ownerDescription || place.subTitle),
    // A Facebook/Instagram/link page used as the "website" is not a real website.
    has_website: !!(place.website && String(place.website).trim()) && !isSocialUrl(place.website),
    website_social: !!(place.website && isSocialUrl(place.website)),
    search_rank: Number.isFinite(Number(place.rank)) && Number(place.rank) > 0 ? Number(place.rank) : null,
    categories: [...new Set([place.categoryName, ...(Array.isArray(place.categories) ? place.categories : [])].filter(Boolean))].slice(0, 8),
    low_star_share: (() => { const d = place.reviewsDistribution; if (!d) return null; const t = ['oneStar', 'twoStar', 'threeStar', 'fourStar', 'fiveStar'].reduce((x, k) => x + (Number(d[k]) || 0), 0); return t ? Math.round((((Number(d.oneStar) || 0) + (Number(d.twoStar) || 0)) / t) * 100) / 100 : null; })(),
    permanently_closed: !!place.permanentlyClosed,
    temporarily_closed: !!place.temporarilyClosed,
    branches: opt.branches ?? 1,
  };
}

const clamp01 = (v) => Math.max(0, Math.min(1, v));
const round3 = (v) => Math.round(clamp01(v) * 1000) / 1000;

/** Normalized signal values (0..1, 1 = the signal's HIGH state) from facts. Unknown stays absent (never guessed). */
function signalValues(f) {
  const out = {};
  out.has_website = f.has_website ? 1 : 0;
  const rc = Math.min(1, Math.log10(1 + (f.total_reviews || 0)) / 3.3);
  const rt = clamp01(((f.overall_rating || 0) - 3) / 2);
  out.size_proxy = round3(0.6 * rc + 0.15 * rt + 0.25 * Math.min(1, ((f.branches || 1) - 1) / 3));
  out.unclaimed_listing = f.unclaimed_listing ? 1 : 0;
  out.profile_completeness = round3(0.7 * Math.min(1, (f.images_count || 0) / 15) + 0.3 * (f.has_hours ? 1 : 0));
  if (f.activity_label !== 'unknown') out.activity = f.activity_label === 'active' ? 1 : f.activity_label === 'slowing' ? 0.5 : 0;
  if (f.n_reviews_fetched >= 3) out.owner_engagement = round3(f.owner_reply_rate ?? 0);
  if (f.n_reviews_fetched >= 1) out.unanswered_low_reviews = round3((f.unanswered_low_reviews || 0) / 3);
  if (f.n_reviews_fetched >= 5 && f.rating_delta != null) out.rating_trend = round3(0.5 + Math.max(-0.5, Math.min(0.5, f.rating_delta / 1.0)));
  if (f.is_new_business === true) out.new_business = 1;
  return out;
}

/**
 * Value of the review_insights signal: how much of what customers complain about the seller's offer can help with (0..1).
 * Complaints the offer cannot help with count for nothing (spec 6.3b step 5). Undefined when there is no analysis.
 */
function reviewInsightValue(analysis) {
  if (!analysis || analysis.skipped) return undefined;
  const rel = (analysis.complaints || []).filter((c) => c && c.offer_can_help);
  const n = rel.reduce((a, c) => a + (Number(c.count) || 1), 0);
  const top = rel.slice().sort((a, b) => (b.count || 0) - (a.count || 0))[0];
  return { value: Math.min(1, n / 3), theme: top ? top.theme : null };
}

// ───────────────────────── opportunities (spec 6.3b step 3) ─────────────────────────
// Generic insight types computed from facts. WHICH ones matter, and the angle sentence for each, comes from the
// campaign's opportunity_map (planner output for this offer). Nothing is tied to a segment.
const OPPORTUNITY_TYPES = ['unclaimed_listing', 'no_website', 'thin_profile', 'unanswered_low_reviews', 'dormant_activity', 'declining_rating', 'low_owner_engagement', 'new_business', 'multi_branch', 'review_theme', 'weak_search_rank'];

function evalOpportunity(type, f, analysis) {
  switch (type) {
    case 'unclaimed_listing':
      return f.unclaimed_listing ? { strength: 2, evidence: { reviews: f.total_reviews } } : null;
    case 'no_website':
      return !f.has_website ? { strength: f.total_reviews >= 30 ? 3 : 2, evidence: { reviews: f.total_reviews, rating: f.overall_rating } } : null;
    case 'thin_profile':
      return f.images_count <= 5 || !f.has_hours ? { strength: f.images_count === 0 ? 3 : f.images_count <= 2 ? 2 : 1, evidence: { photos: f.images_count, hours: f.has_hours } } : null;
    case 'unanswered_low_reviews':
      return f.unanswered_low_reviews >= 1 ? { strength: Math.min(3, f.unanswered_low_reviews), evidence: { count: f.unanswered_low_reviews, of: f.n_reviews_fetched } } : null;
    case 'dormant_activity':
      return f.activity_label === 'dormant' ? { strength: 3, evidence: { days: f.days_since_last_review, last: f.last_review_at } }
        : f.activity_label === 'slowing' ? { strength: 1, evidence: { days: f.days_since_last_review, last: f.last_review_at } } : null;
    case 'declining_rating':
      return f.n_reviews_fetched >= 5 && f.rating_delta != null && f.rating_delta <= -0.3
        ? { strength: f.rating_delta <= -0.6 ? 3 : 2, evidence: { recent: f.recent_avg_rating, overall: f.overall_rating } } : null;
    case 'low_owner_engagement':
      return f.n_reviews_fetched >= 5 && f.owner_reply_rate != null && f.owner_reply_rate < 0.2
        ? { strength: f.owner_reply_rate === 0 && f.n_reviews_fetched >= 8 ? 3 : 2, evidence: { rate: f.owner_reply_rate, of: f.n_reviews_fetched } } : null;
    case 'new_business':
      return f.is_new_business === true ? { strength: 2, evidence: { reviews: f.total_reviews } } : null;
    case 'multi_branch':
      return f.branches >= 2 ? { strength: Math.min(3, f.branches), evidence: { branches: f.branches } } : null;
    case 'weak_search_rank':
      // Rank of the place inside the Maps result list of its search: the lower it appears, the less customers find it.
      return f.search_rank != null && f.search_rank >= 5 ? { strength: f.search_rank >= 10 ? 3 : f.search_rank >= 7 ? 2 : 1, evidence: { rank: f.search_rank } } : null;
    case 'review_theme': {
      // Complaint themes become an opportunity ONLY when the analysis says this offer can help, and confidence is not low.
      if (!analysis || analysis.confidence === 'low') return null;
      const hit = (analysis.complaints || []).filter((c) => c && c.offer_can_help).sort((a, b) => (b.count || 0) - (a.count || 0))[0];
      return hit ? { strength: Math.min(3, Math.max(1, hit.count || 1)), evidence: { theme: hit.theme, count: hit.count || 1 } } : null;
    }
    default:
      return null;
  }
}

/**
 * Top opportunities for one lead in one campaign.
 * @param {any} facts
 * @param {any} analysis review analysis (may be null)
 * @param {{type:string, angle:string}[]} oppMap campaign opportunity map, in the planner's priority order
 */
function buildOpportunities(facts, analysis, oppMap, max = 3) {
  const out = [];
  (oppMap || []).forEach((m, idx) => {
    if (!m || !OPPORTUNITY_TYPES.includes(m.type)) return;
    const e = evalOpportunity(m.type, facts, analysis);
    if (e) out.push({ type: m.type, strength: e.strength, evidence: e.evidence, angle: String(m.angle || '').slice(0, 200), _p: idx });
  });
  out.sort((a, b) => b.strength - a.strength || a._p - b._p);
  return out.slice(0, max).map((o) => ({ type: o.type, strength: o.strength, evidence: o.evidence, angle: o.angle }));
}

// ───────────────────────── score (spec 6.3a) ─────────────────────────
// Mirrors public.recompute_campaign_scores in SQL (same constants). Signed weights: w>0 rewards the HIGH state, w<0 the LOW state.
const SCORE = {
  favorable: 0.66, // a signal counts as "above zero" for the two-signal rule when its favorable state is this strong
  noBaseCap: 69, // fewer than two relevant non-baseline signals => score cannot exceed 69 (never "high" alone)
  maybeCap: 60,
  reasonMinWeight: 15, // a reason is shown only if its signal weighs MORE than this in the campaign (unless nothing stronger exists)
  baselineMaxWeight: 25, // baseline facts (e.g. has a website) are clamped unless the planner marked the signal as emphasized
};

/**
 * @param {{fit?:'fit'|'maybe'|'not_fit'|null, signals:{key:string, weight:number, value:number, baseline?:boolean, emphasis?:boolean}[]}} x
 * @returns {{score:number|null, relevant:number, capped_by:string|null, favorable:{key:string, side:'high'|'low', contribution:number}[]}}
 */
function scoreLead({ fit, signals }) {
  if (fit === 'not_fit') return { score: null, relevant: 0, capped_by: 'not_fit', favorable: [] };
  let sum = 0;
  let den = 0;
  let relevant = 0;
  const favorable = [];
  for (const s of signals) {
    let w = Number(s.weight);
    if (!w) continue;
    if (s.baseline && !s.emphasis) w = Math.sign(w) * Math.min(Math.abs(w), SCORE.baselineMaxWeight);
    const v = clamp01(Number(s.value));
    const c = w * v - Math.min(w, 0);
    sum += c;
    den += Math.abs(w);
    const fav = (w > 0 && v >= SCORE.favorable) || (w < 0 && v <= 1 - SCORE.favorable);
    if (fav) {
      favorable.push({ key: s.key, side: w > 0 ? 'high' : 'low', contribution: c, weight: Math.abs(Number(s.weight)) });
      if (!s.baseline || s.emphasis) relevant++;
    }
  }
  if (!den) return { score: null, relevant, capped_by: null, favorable };
  let score = Math.round((100 * sum) / den);
  let capped_by = null;
  if (relevant < 2 && score > SCORE.noBaseCap) { score = SCORE.noBaseCap; capped_by = 'needs_two_signals'; }
  if (fit === 'maybe' && score > SCORE.maybeCap) { score = SCORE.maybeCap; capped_by = 'maybe_fit'; }
  favorable.sort((a, b) => b.contribution - a.contribution);
  // Reasons from a signal weighing 15 or less in the campaign say little ("has a website"): hidden unless nothing stronger exists (mirrors the SQL).
  const strong = favorable.filter((f) => f.weight > SCORE.reasonMinWeight);
  return { score, relevant, capped_by, favorable: strong.length ? strong : favorable };
}

// ───────────────────────── message tact (spec 6.3b step 5) ─────────────────────────
// Safety net on top of the prompt: the first message never mentions complaints, low ratings or any weakness of the lead.
const NEGATIVE_AR = ['شكوي', 'شكاوي', 'شكوه', 'شتك', 'مشكله', 'مشاكل', 'سيء', 'سيئ', 'وحش', 'ضعيف', 'ضعف', 'تاخير', 'متاخر', 'اهمال', 'مهمل', 'قصور', 'فشل', 'بطيء', 'بطئ', 'غير راضي', 'مش راضي', 'تقييم سيء', 'تقييم منخفض', 'تقييم قليل', 'تقييمات منخفضه', 'تقييمات سلبيه', 'سلبي', 'نجمه واحده', 'نجمتين', 'ريفيوهات وحشه', 'عيب', 'عيوب', 'نقطه ضعف', 'نقاط ضعف', 'مفيش رد', 'بدون رد', 'مرددتوش', 'ما ردتوش', 'مردتوش', 'مش بتردو', 'مبتردوش'];
const NEGATIVE_EN = ['complain', 'bad review', 'low rating', 'poor rating', 'negative', 'weakness', 'problem with', 'unanswered'];

// Unsupported first-person claims about the lead (the sender has not seen their work): hearsay, own opinions, visits.
const CLAIMS_AR = ['سمعت', 'سمعنا', 'عاجبني', 'عجبني', 'عاجبنا', 'عجبنا', 'شايف ان شغل', 'شايف انكم', 'متابع شغل', 'تابعت', 'زرت', 'جربت', 'اتعاملت معاكم', 'شغلكم رائع', 'شغلكم ممتاز', 'شغلكم حلو', 'شغلكم تحفه', 'بتعملوا شغل رائع', 'بتقدموا شغل حلو', 'من افضل'];

/** @returns {{ok:boolean, reasons:string[]}} */
function checkTact(message, complaints = []) {
  const m = norm(message);
  const reasons = [];
  for (const w of NEGATIVE_AR.concat(NEGATIVE_EN)) if (m.includes(norm(w))) reasons.push(`word:${w}`);
  for (const w of CLAIMS_AR) if (m.includes(norm(w))) reasons.push(`claim:${w}`);
  // "your rating/reviews are low/bad" in any phrasing
  if (/(تقييم|ريفيو|نجوم|rating|review)\S*\s+(\S+\s+){0,2}(منخفض|قليل|ضعيف|سلبي|وحش|سيء|واطي|low|poor|bad)/.test(m)) reasons.push('rating_negative');
  for (const c of complaints || []) {
    const theme = typeof c === 'string' ? c : c && c.theme;
    for (const tok of norm(theme).split(' ')) if (tok.length >= 5 && m.includes(tok)) reasons.push(`theme:${tok}`);
  }
  return { ok: reasons.length === 0, reasons: [...new Set(reasons)] };
}


// ───────────────────────── message style rules (round 2) ─────────────────────────
// When the seller's product writes messages, the first message IS the demo: it must not read like a template. These are the
// checks that can be made in code; the prompt carries the rest. Nothing here depends on an industry or an offer.
const RATING_WORDS = ['تقييم', 'تقيم', 'نجمه', 'نجوم', 'ريفيو', 'rating', 'star', 'review'];
const JARGON_RE = /(^|[^a-z])(b2b|b2c|leads?|outreach|pipeline|crm|roi|kpi|funnel)([^a-z]|$)/i;
const JARGON_AR = ['بي تو بي', 'ليدز', 'ليد '];
const DAYTIME_AR = ['صباح', 'مساء'];
const WEAK_CTA = ['ممكن نتكلم', 'نتكلم اكتر', 'نتناقش', 'ممكن نتحدث', 'ممكن نتواصل', 'نتواصل معاكم'];
// Generic benefit phrases the writer likes to invent; allowed only if the seller's own offer text says so.
const BENEFIT_FLUFF = ['رضا العملاء', 'رضاهم', 'رضاكم', 'تعزيز التواصل', 'تقويه التواصل', 'يقوي التواصل', 'تحسين تجربه', 'يزود رضا', 'زياده رضا', 'جوده العمل', 'تركزوا علي شغلكم', 'تركز علي شغلها', 'تركزوا في شغلكم', 'شغلكم الاساسي', 'شغلها الاساسي', 'توفرو وقتكم', 'توفر وقتكم', 'تقلقوا', 'تقلق '];
// The sender has not seen their work: no own praise, and a first message promises no guarantee.
// Praise words are allowed only when the message attributes them to the customers ("عملاءكم بيشكروا في ..."); the sender's own praise is rejected.
const PRAISE_AR = ['مميز', 'ممتاز', 'رائع', 'شاطر', 'عظيم', 'متميز', 'تميز', 'احتراف', 'محترف', 'مختلف', 'متطور', 'ابداع', 'مبدع', 'خبره عاليه', 'باين عليكم', 'باين ان'];
const ATTRIBUTION = ['عملاءكم', 'عملاؤكم', 'عملائكم', 'بيشكروا', 'بيتكلموا', 'بيمدحوا', 'بيقولوا', 'بيحبوا'];
// Claims about the lead's own needs: "شغلكم ... بيحتاج/محتاج ...", "أكيد ...". Needs of the companies we would bring them ("شركات محتاجة خدماتكم") are fine.
const ASSUMES = /((^| )(اكيد|واضح انكم|باين انكم|واضح ان|باين ان)( |$))|(((انتم|انكم|بيخليكم)( \S+){0,2}|(^| )(شغلكم|نشاطكم|مجالكم|عملكم|خدمتكم|تخصصكم|شركتكم|وكالتكم)( \S+){0,6}) (بيحتاج|بتحتاج|يحتاج|محتاج|محتاجه|محتاجين|بيتطلب|بتتطلب)( |$))/;
// "always" is an overclaim about their customers or their work.
const OVERCLAIM_AR = ['دايما', 'دائما', 'طول الوقت', 'كل الناس'];
const GUARANTEE_AR = ['نضمن', 'بنضمن', 'هنضمن', 'مضمون', 'ضمان', 'guarantee'];
const STOP = new Set(['من', 'في', 'علي', 'عن', 'الي', 'مع', 'ده', 'دي', 'كده', 'لو', 'او', 'ان', 'انت', 'انتم', 'احنا', 'هو', 'هي']);

const wordList = (s) => String(s || '').trim().split(/\s+/).filter(Boolean);
const contentTokens = (s) => catTokens(s).filter((t) => t.length >= 2 && !STOP.has(t));

/**
 * Does the message copy a run of `n` or more consecutive words from one of the organization's style examples? Runs that also occur in the
 * seller's own offer text (its description and its call to action) are allowed: those words come from the offer, not from the example.
 */
function copiedRun(message, examples, allowedText = '', n = 8) {
  const toks = (t) => norm(t).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter(Boolean);
  const grams = (arr) => { const out = []; for (let i = 0; i + n <= arr.length; i++) out.push(arr.slice(i, i + n).join(' ')); return out; };
  const allowed = new Set(grams(toks(allowedText)));
  const mine = grams(toks(message)).filter((g) => !allowed.has(g));
  if (!mine.length) return false;
  const theirs = new Set((examples || []).flatMap((e) => grams(toks(e))));
  return mine.some((g) => theirs.has(g));
}

/** First five words of a message (normalized): two messages of one campaign must not share them. */
function openingKey(message) {
  return norm(message).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter(Boolean).slice(0, 5).join(' ');
}

/** Word-set overlap (Jaccard, 0..1) of two messages: two messages of one campaign above SIMILAR_LIMIT read like the same template. */
const SIMILAR_LIMIT = 0.6;
function messageSimilarity(a, b) {
  const t = (s) => new Set(norm(s).replace(/[^\p{L}\p{N} ]/gu, ' ').split(/\s+/).filter((w) => w.length > 2));
  const x = t(a);
  const y = t(b);
  const inter = [...x].filter((w) => y.has(w)).length;
  const uni = new Set([...x, ...y]).size;
  return uni ? inter / uni : 0;
}

/** Does the quoted phrase come from the seller's offer text? Exact (normalized) match, or at least 85% of its words, for 3+ words. */
function quoteInOffer(quote, offerText) {
  const q = norm(quote).replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\s+/g, ' ').trim();
  const o = norm(offerText).replace(/[^\p{L}\p{N} ]/gu, ' ').replace(/\s+/g, ' ').trim();
  if (q.split(' ').length < 3 || !o) return false;
  if (o.includes(q)) return true;
  const have = new Set(catTokens(o));
  const qt = catTokens(q);
  return qt.length >= 3 && qt.filter((t) => have.has(t)).length / qt.length >= 0.85;
}

/**
 * Style and honesty checks on one first message.
 * @param {string} message
 * @param {{channel?:string, areas?:string[], city?:string|null, offerText?:string, offerQuote?:string|null, ctaOffer?:string|null, senderName?:string|null}} ctx
 * @returns {{ok:boolean, reasons:string[]}}
 */
function checkMessage(message, ctx = {}) {
  const m = norm(message);
  const reasons = [];
  const chat = ctx.channel !== 'email';
  const n = wordList(message).length;
  if (chat && (n < 35 || n > 70)) reasons.push(`word_count_${n}`);
  for (const w of RATING_WORDS) if (m.includes(norm(w))) { reasons.push('mentions_rating'); break; }
  if (/[⭐★☆]/.test(message)) reasons.push('mentions_rating');
  if (JARGON_RE.test(m) || JARGON_AR.some((w) => m.includes(norm(w)))) reasons.push('jargon');
  if (DAYTIME_AR.some((w) => new RegExp(`(^| )${norm(w)}`).test(m)) || /good (morning|evening|afternoon)/.test(m)) reasons.push('time_greeting');
  // micro-districts: the lead's own district / neighborhood names are never used; the city (at most) is fine
  const city = norm(ctx.city || '');
  for (const a of ctx.areas || []) {
    const t = norm(a);
    if (t.length >= 3 && t !== city && !(city && city.includes(t)) && m.includes(t)) { reasons.push(`micro_district:${a}`); break; }
  }
  if (/(المنطقه|الحي|حي) (ال)?(اولي|ثانيه|ثالثه|رابعه|خامسه|سادسه|سابعه|ثامنه|تاسعه|عاشره|اول|ثاني|ثالث|رابع|خامس|سادس|سابع|ثامن|تاسع|عاشر)/.test(m)) reasons.push('micro_district:ordinal');
  if (WEAK_CTA.some((w) => m.includes(norm(w)))) reasons.push('weak_cta');
  {
    const ws = m.split(/\s+/);
    const own = ws.some((w, i) => PRAISE_AR.some((p) => w.includes(norm(p))) && !ws.slice(Math.max(0, i - 7), i).some((b) => ATTRIBUTION.some((a) => b.includes(norm(a)))));
    if (own) reasons.push('own_praise');
    if (ASSUMES.test(m)) reasons.push('assumes_need');
    if (OVERCLAIM_AR.some((w) => new RegExp(`(^| )${norm(w)}( |$)`).test(m))) reasons.push('overclaim_always');
  }
  if (GUARANTEE_AR.some((w) => m.includes(norm(w)))) reasons.push('guarantee');
  const offerN = norm(ctx.offerText || '');
  for (const f of BENEFIT_FLUFF) if (m.includes(norm(f)) && !offerN.includes(norm(f))) { reasons.push(`invented_benefit:${f}`); break; }
  if (ctx.offerText) {
    if (!ctx.offerQuote) reasons.push('offer_quote_missing');
    else if (!quoteInOffer(ctx.offerQuote, ctx.offerText)) reasons.push('offer_quote_not_in_offer');
  }
  if (ctx.ctaOffer) {
    const have = new Set(contentTokens(message));
    const hit = contentTokens(ctx.ctaOffer).filter((t) => have.has(t)).length;
    if (hit < 2) reasons.push('cta_offer_missing');
  }
  if (ctx.senderName && chat) {
    const tail = m.slice(-60);
    if (!tail.includes(norm(ctx.senderName))) reasons.push('missing_signature');
    // the sender's name appears once, in the signature at the end (never also as an introduction at the start)
    if (m.split(norm(ctx.senderName)).length - 1 > 1) reasons.push('double_signature');
  }
  if ((ctx.styleExamples || []).length && copiedRun(message, ctx.styleExamples, ctx.offerText || ctx.ctaOffer || '')) reasons.push('copies_style_example');
  return { ok: reasons.length === 0, reasons: [...new Set(reasons)] };
}

const REASON_HELP = {
  own_praise: 'you praised their work yourself (praise is allowed only as what their customers say)',
  assumes_need: 'you claimed something about what the lead itself needs',
  copies_style_example: 'you copied 8 or more consecutive words from a style example: write your own sentences',
  double_signature: 'the sender name appears more than once: it belongs only in the signature at the end',
  overclaim_always: 'you used "always" (دايما / دائما)',
  mentions_rating: 'you mentioned the rating, stars or reviews',
  jargon: 'you used jargon (B2B, leads...)',
  time_greeting: 'you used a time-of-day greeting',
  weak_cta: 'the ending was a weak "can we talk" question',
  guarantee: 'you promised or guaranteed something',
  invented_benefit: 'you promised a benefit that is not in the offer',
  offer_quote_missing: 'offer_quote was missing',
  offer_quote_not_in_offer: 'offer_quote was not copied word for word from sender_offer',
  cta_offer_missing: 'the concrete cta_offer was not in the ending',
  missing_signature: 'the signature was missing at the end',
  duplicate_opening: 'the opening is the same as another message',
  too_similar_to_another_message: 'the text is too close to another message',
  too_similar: 'the text is too close to another message',
};
function explainReason(reason) {
  const parts = String(reason).replace(/^style:/, '').split(/[,:]/).map((x) => x.trim()).filter(Boolean);
  const out = [];
  for (const p of parts) {
    if (REASON_HELP[p]) out.push(REASON_HELP[p]);
    else if (/^word_count_(\d+)$/.test(p)) out.push(`the text had ${p.slice(11)} words (it must be 35 to 70)`);
    else if (p === 'tact') out.push('you mentioned something negative (a problem, complaint or weakness) about the business or used a word like "problem"');
    else if (p === 'micro_district') out.push('you named a district or neighborhood');
  }
  return [...new Set(out)];
}

/** The single automatic retry of a rejected first message: same request plus the rejected reply and the reason as feedback. */
function retryRequestBody(requestBody, raw, reason) {
  const req = JSON.parse(requestBody);
  req.messages = [...req.messages, { role: 'assistant', content: raw || '{}' }, { role: 'user', content: `Your reply was rejected (${reason}). Rewrite it and return the JSON again. Remember: 35 to 70 words, no rating or stars or reviews, no district or neighborhood names, no jargon (no B2B), no time-of-day greeting, no "ممكن نتكلم", no praise of their work, no guarantees, no "focus on your core work" lines, address them as a team in the plural, end with the concrete offer (cta_offer) worded differently from the usual and the signature, offer_quote must be copied word for word from sender_offer, never invent benefits, never mention complaints or weaknesses, start differently from avoid_openings and use different sentences from the other messages of this campaign.` }];
  const why = explainReason(reason);
  if (why.length) req.messages[req.messages.length - 1].content += ` Specifically: ${why.join('; ')}.`;
  const wc = /word_count_(\d+)/.exec(String(reason));
  if (wc) req.messages[req.messages.length - 1].content += ` The text had ${wc[1]} words. Write between 45 and 60 words: ${Number(wc[1]) < 35 ? 'add one more concrete sentence about what the offer does (use the wording of offer_quote)' : 'cut the weakest sentence'}.`;
  req.temperature = 0.5;
  return JSON.stringify(req);
}

// ───────────────────────── LLM helpers (OpenRouter request/response) ─────────────────────────
/** OpenRouter chat request body (string). `fallback` = fallback model ids tried on provider failure. */
function llmRequest({ system, user, model, fallback = [], temperature = 0, extraMessages = [] }) {
  const req = {
    messages: [{ role: 'system', content: system }, { role: 'user', content: typeof user === 'string' ? user : JSON.stringify(user) }, ...extraMessages],
    response_format: { type: 'json_object' },
    temperature,
    usage: { include: true },
  };
  const fb = (fallback || []).filter(Boolean);
  if (fb.length) req.models = [model, ...fb]; else req.model = model;
  return JSON.stringify(req);
}

/** Parse an OpenRouter full-response item. @returns {{data:any|null, usage:{in:number,out:number,cost:number,model:string|null}, status:number|null}} */
function parseLlm(res) {
  const r = res || {};
  const u = (r.body && r.body.usage) || {};
  const usage = { in: u.prompt_tokens || 0, out: u.completion_tokens || 0, cost: Number(u.cost) || 0, model: (r.body && r.body.model) || null };
  let data = null;
  if (r.statusCode >= 200 && r.statusCode < 300 && r.body && r.body.choices) {
    try { data = JSON.parse((r.body.choices[0]?.message?.content || '').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch { data = null; }
  }
  return { data, usage, status: typeof r.statusCode === 'number' ? r.statusCode : null };
}

/** System prompt of the fit check (spec 6.0 step 3 and 4). Offer-agnostic: the ideal prospect text is the only criterion. */
function fitSystemPrompt({ ideal, offerText, negatives = [] }) {
  return `You judge whether Google Maps places are potential CUSTOMERS (prospects) for a seller.
Ideal prospect: ${ideal || '(not stated; judge from the seller offer)'}
Seller offer: ${String(offerText || '').slice(0, 500)}
For each place decide: "fit" (clearly the kind of business described), "maybe" (possibly, adjacent or unclear), "not_fit" (a different kind of business even if its NAME contains similar words, a public or government body, a competitor of the seller, or unrelated).
EVIDENCE RULES:
- Judge ONLY from the place's categories, its description and its website address. The business NAME is context only: words inside a name (including words that also appear in the ideal prospect text or the seller offer) are NOT evidence of what the business does or sells.
- When a word naming an industry, a product or a customer group sits next to the word that names the kind of business (in the name or in a category), it says what the business SELLS or serves, so the business belongs to THAT sector: answer "not_fit" (not "maybe"), unless the ideal prospect text itself asks for that sector.
- Return "evidence": the source that supports your label, one of "category", "description", "website", "name_only" (nothing but the name supports it) or "none". Use "fit" only when the evidence is category, description or website.
Give a SHORT reason (max 12 words, in the same language as the ideal prospect text).${negatives.length ? `\nThe seller already rejected businesses like these (treat similar ones as not_fit):\n${negatives.slice(0, 15).map((n) => `- ${n.business_name || ''} (${n.category || ''}): ${n.reason || ''}`).join('\n')}` : ''}
Return ONE JSON object only: {"results":[{"i": number, "fit": "fit"|"maybe"|"not_fit", "evidence": "category"|"description"|"website"|"name_only"|"none", "reason": string}]} covering every i.`;
}

const hostOf = (u) => { try { return new URL(/^[a-z]+:\/\//i.test(u) ? u : `https://${u}`).hostname.replace(/^www\./, '').toLowerCase(); } catch { return ''; } };

/** Social and messaging pages people use instead of a website. A business that only has one of these has no real website. */
const SOCIAL_HOSTS = ['facebook.com', 'fb.com', 'fb.me', 'instagram.com', 'linktr.ee', 'beacons.ai', 'tiktok.com', 'twitter.com', 'x.com', 'linkedin.com', 'wa.me', 'whatsapp.com', 'youtube.com', 'youtu.be', 't.me', 'behance.net'];
function isSocialUrl(u) {
  const h = hostOf(String(u || ''));
  return !!h && SOCIAL_HOSTS.some((s) => h === s || h.endsWith(`.${s}`));
}

/** The compact description of one place sent to the fit check: categories, description and website address are evidence; the name is context. */
function fitAsk(rawPlace, area) {
  const cats = [rawPlace.categoryName, ...(Array.isArray(rawPlace.categories) ? rawPlace.categories : [])].filter(Boolean);
  const desc = stripInvisible(rawPlace.description || rawPlace.ownerDescription || rawPlace.subTitle || '').slice(0, 240);
  return {
    name: stripInvisible(rawPlace.title), categories: [...new Set(cats)].slice(0, 8), description: desc || null,
    website: rawPlace.website ? hostOf(String(rawPlace.website)) || 'yes' : 'no', area: area || '', rating: rawPlace.totalScore ?? null, reviews: rawPlace.reviewsCount ?? null,
  };
}

/**
 * Keep or remove one place after the fit check (spec 6.0 step 4, round 2 fixes).
 * Inside the allowed categories: fit or maybe is kept (the category itself is evidence), not_fit removed.
 * Outside them: kept ONLY when the check said "fit" with evidence from the categories, description or website; never from the name,
 * never for "maybe". Nothing is learned from the model: a category joins the allowed list only through a user action.
 * @returns {{keep:boolean, fit?:'fit'|'maybe', why?:string}}
 */
function decideFit({ label, inside }) {
  const l = label || { fit: 'maybe', reason: 'unchecked' };
  if (l.fit === 'not_fit') return { keep: false, why: 'not_fit' };
  const ev = l.evidence;
  const real = ev === 'category' || ev === 'description' || ev === 'website';
  if (inside) return { keep: true, fit: l.fit === 'fit' && ev !== 'name_only' ? 'fit' : 'maybe' };
  if (l.fit === 'fit' && real) return { keep: true, fit: 'fit' };
  return { keep: false, why: l.fit === 'fit' ? 'name_only_evidence' : 'outside_categories' };
}

// ───────────────────────── search rounds (spec 6.2) ─────────────────────────
/** Search area of a location: the most specific name and a clean geocoder string (no repeated parts, no hidden characters). */
function areaOf(l) {
  // Unique parts; a part already contained in a more specific one is dropped ("القاهرة" inside "التجمع الخامس القاهرة").
  const parts = [cleanPlace(l.district), cleanPlace(l.city), cleanPlace(l.governorate)].filter(Boolean);
  const kept = parts.filter((p, i) => !parts.some((q, j) => j !== i && norm(q) !== norm(p) && norm(q).includes(norm(p))) && parts.findIndex((q) => norm(q) === norm(p)) === i);
  return { area: cleanPlace(l.district || l.city || l.governorate || ''), locationQuery: kept.concat('Egypt').join(', ') };
}

/**
 * Plan the Apify searches for a round. Rounds: 1 base queries at real depth; 2 same queries deeper (only the ones that hit
 * their cap); 3 synonyms; 4 nearby districts; 5 broad fallback (city level, simplest keyword) used for zero results.
 * @returns {{round:number, searches:{query:string, area:string, locationQuery:string, depth:number}[]}|null} null = exhausted
 */
function planRound({ round, target, keywords, synonyms = [], locations, nearby = [], done = [], saturated = [], avoid = [], minDepth = 20, maxDepth = 120 }) {
  const doneSet = new Set(done.map((d) => norm(d)));
  const loc = areaOf;
  const mk = (kws, locs, depthMul = 1) => {
    const base = Math.min(maxDepth, Math.max(minDepth, Math.ceil((target * 2.5) / Math.max(1, kws.length * locs.length))));
    const depth = Math.min(maxDepth, Math.ceil(base * depthMul));
    const s = [];
    for (const l of locs) {
      const { area, locationQuery } = loc(l);
      for (const k of kws) {
        const query = `${cleanPlace(k)} ${area}`.trim();
        s.push({ query, area, locationQuery, depth, key: norm(`${depthMul}|${query}`) });
      }
    }
    return s;
  };
  let searches = [];
  if (round === 1) searches = mk(keywords, locations);
  else if (round === 2) {
    const sat = new Set(saturated.map(norm));
    searches = mk(keywords, locations, 2.5).filter((s) => sat.has(norm(s.query)));
  } else if (round === 3) searches = mk(synonyms, locations);
  else if (round === 4) searches = mk(keywords.concat(synonyms).slice(0, 4), nearby);
  else if (round === 5) {
    // Broad fallback: simplest keyword, city level (or governorate), no district polygon.
    const broad = locations.map((l) => ({ governorate: l.governorate, city: l.city || l.governorate, district: '' }));
    searches = mk(keywords.slice(0, 2), broad.length ? broad : locations);
  } else return null;
  // `avoid` = searches this organization already ran in earlier campaigns: the same companies would come back, so prefer new ones.
  const avoidSet = new Set(avoid.map(norm));
  searches = searches.filter((s) => s.query && !doneSet.has(norm(s.query) + '|' + round) && !avoidSet.has(norm(s.query)));
  return searches.length ? { round, searches } : null;
}

/**
 * After a round: which round next (null = stop). Normal order 1..5; if round 1 found no places at all the engine jumps to the
 * broad fallback first (city level, simplest keywords), then synonyms and nearby districts.
 * @returns {{next:number|null, mode:'normal'|'zero'}}
 */
function decideNext({ round, mode = 'normal', delivered, target, rawTotal }) {
  if (delivered >= target) return { next: null, mode };
  if (round === 1 && rawTotal === 0) return { next: 5, mode: 'zero' };
  if (mode === 'zero') return { next: round === 5 ? 3 : round === 3 ? 4 : null, mode };
  return { next: round < 5 ? round + 1 : null, mode };
}

/** Why a campaign delivered nothing (plain code, mapped to a user message with concrete suggestions in the UI). */
function emptyReason(f) {
  if (!f.raw_places) return 'no_places';
  if (f.removed_not_fit >= (f.raw_places - f.removed_category - f.removed_global - f.removed_closed) && f.removed_not_fit > 0) return 'all_not_fit';
  if (f.removed_category + f.removed_global >= f.raw_places * 0.8) return 'all_category';
  if (f.previously_found > 0 && f.previously_found >= f.raw_places * 0.5) return 'all_previously_found';
  if (f.cooldown > 0 && f.cooldown >= f.raw_places * 0.5) return 'all_cooldown';
  return 'all_filtered';
}

/** Funnel keys shown on the campaign page, in order (spec 6.2). */
const FUNNEL_KEYS = ['queries', 'raw_places', 'removed_category', 'removed_global', 'removed_closed', 'removed_landline', 'removed_filters', 'removed_not_fit', 'duplicates', 'previously_found', 'opted_out', 'cooldown', 'delivered'];

const meta = $('Select and build').item.json;
const res = $input.item.json;
const attempt = $prevNode.name === 'OpenRouter retry' ? 2 : 1;
const first = attempt === 2 ? $('Validate message').item.json : null;

const base = { lead_id: meta.lead_id, message_id: meta.message_id, regen_count: meta.regen_count, channel: meta.channel,
  organization_id: meta.organization_id, campaign_id: meta.campaign_id, job_id: meta.job_id, total: meta.total };
const body = res && res.body;
const u = (body && body.usage) || {};
const prevU = first || { tokens_in: 0, tokens_out: 0, cost: 0 };
const usage = { tokens_in: (u.prompt_tokens || 0) + prevU.tokens_in, tokens_out: (u.completion_tokens || 0) + prevU.tokens_out,
  cost: (Number(u.cost) || 0) + prevU.cost, model: (body && body.model) || (first && first.model) || null };
// Save instruction for the single "Save message" HTTP node: invalid items become a harmless no-op PATCH (matches no row).
// A final failure is stored as a visible 'failed' row (no text, never charged) so the review queue can show it with a regenerate button.
const failSave = (reason) => (meta.message_id
  ? { method: 'PATCH', path: `messages?id=eq.${meta.message_id}&review_status=neq.sent`, prefer: 'return=minimal', body: { review_status: 'failed', fail_reason: String(reason).slice(0, 120), job_id: meta.job_id } }
  : { method: 'POST', path: 'messages?on_conflict=lead_id,campaign_id,channel', prefer: 'resolution=ignore-duplicates,return=minimal',
      body: { organization_id: meta.organization_id, lead_id: meta.lead_id, campaign_id: meta.campaign_id, job_id: meta.job_id, channel: meta.channel, generated_text: '', review_status: 'failed', fail_reason: String(reason).slice(0, 120) } });

// A failed first attempt is retried ONCE with the reasons as feedback; a failed retry is final.
const bad = (reason, raw) => {
  const retryable = attempt === 1 && !/^http_/.test(reason);
  let retryBody = '{}';
  if (retryable) retryBody = retryRequestBody(meta.requestBody, raw, reason);
  return { json: { ...base, ...usage, ok: false, reason, retry: retryable, requestBody: retryBody, save: failSave(reason) } };
};

if (!res || res.statusCode < 200 || res.statusCode >= 300 || !body || !body.choices) return bad(`http_${res && res.statusCode}`);
const content = body.choices[0]?.message?.content || '';
let d;
try { d = JSON.parse(content.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim()); } catch (e) { return bad('bad_json', content); }
let message = typeof d.message === 'string' ? d.message.trim() : '';
if (!message) return bad('empty', content);

const words = message.split(/\s+/).filter(Boolean).length;
const chat = meta.channel !== 'email';
if (!chat && (words < 50 || words > 150)) return bad(`word_count_${words}`, content);
if (chat && /https?:|www\.|\.com\b|\.net\b|\.eg\b|wa\.me/i.test(message)) return bad('contains_link', content);
// The signature is a fixed string: when the model leaves it out we add it (everything else still has to pass).
if (chat && meta.signature && meta.sender_name && !norm(message.slice(-60)).includes(norm(meta.sender_name))) message = `${message} ${meta.signature}`;
// Tact: no complaints, low ratings or weaknesses in the first message (this lead's own complaint themes are checked too).
const tact = checkTact(message, meta.complaints || []);
if (!tact.ok) return bad(`tact:${tact.reasons.slice(0, 3).join(',')}`, content);
// Style and honesty rules (round 2): no rating, micro-district, jargon or time greeting; benefits only from the offer; a concrete call to action; a signature.
const style = checkMessage(message, { channel: meta.channel, areas: meta.areas, city: meta.city, offerText: meta.offer_text, offerQuote: typeof d.offer_quote === 'string' ? d.offer_quote : null, ctaOffer: meta.cta_offer, senderName: meta.sender_name, styleExamples: meta.style_examples });
if (!style.ok) return bad(`style:${style.reasons.slice(0, 3).join(',')}`, content);
// The opening (first five words) must differ from every earlier message of the campaign.
const opening = openingKey(message);
if (opening && (meta.used_openings || []).includes(opening)) return bad('duplicate_opening', content);
if (attempt === 2 && opening) {
  // The retry is final, so it also has to differ from the openings already accepted in this run (kept by "Dedupe openings").
  const sd = $getWorkflowStaticData('global');
  const seenNow = sd[`open_${meta.job_id}`] || [];
  const textsNow = sd[`open_${meta.job_id}_t`] || [];
  if (seenNow.includes(opening) || textsNow.some((t) => messageSimilarity(t, message) >= SIMILAR_LIMIT)) return bad('duplicate_opening', content);
  sd[`open_${meta.job_id}`] = [...seenNow, opening];
  sd[`open_${meta.job_id}_t`] = [...textsNow, message].slice(-60);
}
// At most ONE emoji (spec 6.4): keep the first, drop the rest instead of wasting the generation.
let seenEmoji = 0;
message = message.replace(/\p{Extended_Pictographic}️?/gu, (m) => (seenEmoji++ === 0 ? m : '')).replace(/[ \t]{2,}/g, ' ').trim();

const angle = typeof d.angle === 'string' ? d.angle.trim().slice(0, 120) : null;
const subject = typeof d.subject === 'string' ? d.subject.trim().slice(0, 100) : null;
const save = meta.message_id
  ? { method: 'PATCH', path: `messages?id=eq.${meta.message_id}&review_status=neq.sent`, prefer: 'return=minimal',
      body: { generated_text: message, edited_text: null, fail_reason: null, angle, subject, opportunity_type: meta.opportunity_type, review_status: 'pending', regen_count: meta.regen_count, llm_model: usage.model, job_id: meta.job_id } }
  : { method: 'POST', path: 'messages?on_conflict=lead_id,campaign_id,channel', prefer: 'resolution=ignore-duplicates,return=minimal',
      body: { organization_id: meta.organization_id, lead_id: meta.lead_id, campaign_id: meta.campaign_id, job_id: meta.job_id, channel: meta.channel,
        subject, generated_text: message, angle, opportunity_type: meta.opportunity_type, llm_model: usage.model } };
return { json: { ...base, ...usage, ok: true, retry: false, retried: attempt === 2, message, angle, subject, opening, save, raw_content: content } };

// per item: keep validate meta; flag DB errors from the save step
let m;
try { m = $('Validate retry').item.json; } catch (e) { m = $('Validate message').item.json; }
const inp = $input.item.json || {};
const saveErr = m.ok && (inp.code || inp.hint || inp.details);
return { json: { ok: m.ok && !saveErr, retried: !!m.retried, reason: saveErr ? String(inp.message || inp.code).slice(0, 80) : m.reason, tokens_in: m.tokens_in, tokens_out: m.tokens_out, cost: m.cost, model: m.model } };

// WF3 "Final": totals for settle_job. Credits are charged only for messages that were actually created.
const body = $('Webhook').first().json.body;
const job = $('Claim job').first().json;
const items = $input.all().map((i) => i.json);

let created = 0, failed = 0, retried = 0, tin = 0, tout = 0, cost = 0, model = null;
let skippedCooldown = 0;
try { skippedCooldown = Number($('Select and build').first().json.skippedCooldown) || 0; } catch (e) { skippedCooldown = 0; }
const reasons = {};
for (const r of items) {
  tin += r.tokens_in || 0;
  tout += r.tokens_out || 0;
  cost += r.cost || 0;
  model = r.model || model;
  if (r.retried) retried++;
  if (r.ok) created++; else { failed++; reasons[r.reason] = (reasons[r.reason] || 0) + 1; }
}
const status = created === 0 && failed > 0 ? 'failed' : 'succeeded';
return [{
  json: {
    job_id: body.job_id,
    status,
    credits_used: created,
    error: status === 'failed' ? 'generation_failed' : null,
    counts: { ...(job.counts || {}), generated: created, failed, retried, skipped_cooldown: skippedCooldown, failure_reasons: reasons },
    cost_usd: Math.round(cost * 1e6) / 1e6,
    model,
    tokens_in: tin,
    tokens_out: tout,
  },
}];
